          exp_ret_other_usd: 0,
          exp_pd_usd: 0,
          exp_vat_cr_usd: 0,
          exp_vat_pd_usd: 0,
          exp_cr_lbp: 0,
          exp_pd_lbp: 0,
          exp_vat_cr_lbp: 0,
          exp_vat_pd_lbp: 0,
          exp_rem_usd: 0,
