  function renderModalIndustryQuickBar(activeForm, activeTemplateId) {
    const ind = getActiveIndustry(STATE.company);
    if (!ind || ind === 'Manufacturing') return '';
    const templates = INDUSTRY_QUICK_ENTRY_TEMPLATES[ind] || [];
    if (!templates.length) return '';
    return `
      <div id="modalIndustryQuickBar" style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;padding:8px 12px;margin-bottom:8px;background:var(--bg-alt,#F8FAFC);border:1px solid var(--line,#E2E8F0);border-radius:8px">
        <div style="display:flex;align-items:center;gap:6px;font-size:11.5px;font-weight:700;color:var(--ink)">
          <span class="badge badge-brass">${esc(ind)}</span>
          <span>Domain Workflows:</span>
        </div>
        <div style="display:flex;gap:6px;flex-wrap:wrap">
          <button type="button" class="btn btn-primary" style="padding:3px 9px;font-size:11px" data-ind-open-new="${esc(STATE.view)}">+ Domain Register Form</button>
          ${templates.map(t => {
            const isAct = activeTemplateId ? (activeTemplateId === t.id) : (t.form === 'extended' ? STATE.modalGroupOverride === 'extended' : (activeForm === t.form && (t.form !== 'external' || STATE.modalGroupOverride !== 'extended')));
            return `<button type="button" class="btn ${isAct ? 'btn-primary' : 'btn-ghost-bar'}" style="padding:3px 9px;font-size:11px" data-ind-quick-tpl="${esc(t.id)}" data-ind-quick-form="${esc(t.form)}">${esc(t.label)}</button>`;
          }).join('')}
        </div>
      </div>
    `;
  }

  function getIndustryRowEditStore() {
    if (!STATE.industryRowEdits || typeof STATE.industryRowEdits !== 'object') {
      try {
        const raw = !IS_AUTOMATED_TEST ? appStoreGetRaw('isabi_mfg_ind_row_edits_v1') : null;
        STATE.industryRowEdits = raw ? JSON.parse(raw) : {};
      } catch (_) {
        STATE.industryRowEdits = {};
      }
    }
    return STATE.industryRowEdits;
  }

  function postIndustryDomainStoreToLocalApi() {
    if (!hasServerApi() || isDemoScopeActive()) return;
    if (rosterIsServerHeld() && !STATE.authed) return;
    try {
      const pLeg = STATE._purgedIndustryLegacy || { rows: [], editKeys: [] };
      const sentRows = Array.isArray(pLeg.rows) ? pLeg.rows.slice() : [];
      const sentEdits = Array.isArray(pLeg.editKeys) ? pLeg.editKeys.slice() : [];
      edgeApiFetch('./api/industry_domain_store', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          industryCustomRows: withoutTillOwnedRows(getIndustryCustomRowsStore()),
          industryRowEdits: withoutTillOwnedEdits(getIndustryRowEditStore()),
          purgedRows: sentRows,
          purgedEditKeys: sentEdits
        })
      }).then(res => {
        if (res && res.ok && STATE._purgedIndustryLegacy) {
          if (sentRows.length) {
            const doneR = new Set(sentRows.map(x => x.bucket + '::' + x.row_id));
            STATE._purgedIndustryLegacy.rows = (STATE._purgedIndustryLegacy.rows || []).filter(x => !doneR.has(x.bucket + '::' + x.row_id));
          }
          if (sentEdits.length) {
            const doneE = new Set(sentEdits);
            STATE._purgedIndustryLegacy.editKeys = (STATE._purgedIndustryLegacy.editKeys || []).filter(k => !doneE.has(k));
          }
        }
      }).catch(() => {});
    } catch (_) {}
  }

  function saveIndustryRowEditStore(store) {
    const nextStore = store || {};
    const nowIso = new Date().toISOString();
    Object.keys(nextStore).forEach(k => {
      const item = nextStore[k];
      if (item && typeof item === 'object') {
        item.rev = Math.max(1, Number(item.rev || 0) + (item._revBumped ? 0 : 1));
        item._revBumped = true;
        item.updated_at = item.updated_at || item.updatedAt || nowIso;
        item.updatedAt = item.updated_at;
      }
    });
    STATE.industryRowEdits = nextStore;
    STATE._indCustomRev = (STATE._indCustomRev || 0) + 1; // KPI / cash caches key on it
    if (window.MFG_CMD_PALETTE && typeof window.MFG_CMD_PALETTE.invalidateCache === 'function') {
      window.MFG_CMD_PALETTE.invalidateCache();
    }
    if (!IS_AUTOMATED_TEST) {
      try {
        appStoreSetRaw('isabi_mfg_ind_row_edits_v1', JSON.stringify(STATE.industryRowEdits));
      } catch (_) {}
    }
    postIndustryDomainStoreToLocalApi();
  }

  function makeIndustryRowEditKey(ind, tableTitle, primaryId) {
    const cleanTbl = String(tableTitle || '').replace(/\(\d+[^)]*\)/g, '').trim().slice(0, 60);
    return `${ind || 'IND'}::${cleanTbl}::${String(primaryId || '').trim()}`;
  }

  function setDomainCellTextPreservingBadge(tdEl, newVal) {
    if (!tdEl) return;
    const v = String(newVal ?? '');
    const attBadge = tdEl.querySelector ? tdEl.querySelector('.att-inline-badge') : null;
    const strong = tdEl.querySelector ? tdEl.querySelector('strong, b, .badge:not(.att-inline-badge)') : null;
    if (attBadge) {
      if (strong && tdEl.children.length <= 2) {
        strong.textContent = v;
      } else {
        const badgeClone = attBadge.cloneNode(true);
        tdEl.textContent = v;
        tdEl.appendChild(document.createTextNode(' '));
        tdEl.appendChild(badgeClone);
      }
      return;
    }
    if (strong && tdEl.children.length === 1) strong.textContent = v;
    else tdEl.textContent = v;
  }

  function applyIndustryDomRowEdits(root) {
    if (!root || getActiveIndustry(STATE.company) === 'Manufacturing') return;
    const store = getIndustryRowEditStore();
    if (!store || !Object.keys(store).length) return;
    const ind = getActiveIndustry(STATE.company);
    root.querySelectorAll('table tbody tr').forEach(tr => {
      if (tr.hasAttribute('data-rid') || tr.classList.contains('total-row') || tr.classList.contains('totals-row')) return;
      const tds = Array.from(tr.querySelectorAll('td')).filter(tdEl => tdEl.style.display !== 'none');
      if (tds.length < 2) return;
      const primaryId = tr.getAttribute('data-ind-row-id') || cleanDomainCellText(tds[0]);
      if (isTillOwnedRowId(primaryId)) return;
      const cardEl = tr.closest('.panel-card, .panel');
      const tableTitle = getDomainCardCanonicalTitle(cardEl);
      const key = makeIndustryRowEditKey(ind, tableTitle, primaryId);
      const saved = store[key];
      if (!saved) return;
      if (saved.voided) {
        tr.style.display = 'none';
        return;
      }
      if (Array.isArray(saved.cells)) {
        const tblEl = tr.closest('table');
        const curHeaders = getDomainTableEnHeaders(tblEl);
        const curRawCells = tds.map(cleanDomainCellText);
        const projected = projectSavedDomainCellsToHeaders(saved, curHeaders, curRawCells);
        projected.forEach((val, idx) => {
          if (tds[idx] && val != null && String(val) !== curRawCells[idx]) {
            setDomainCellTextPreservingBadge(tds[idx], val);
          }
        });
      }
    });
  }

  // Related Agreement count pills on the primary register rows of the 5 sibling industries (Real Estate
  // properties and units, Hospitality memberships, Trading serial units, Insurance policies and carrier
  // statements, Holding entities), in the hub and in the Tables explorer. The count comes from
  // computeIndustryRelatedAgreementsInfo with the same headers and cells the row click hands the 360
  // Inspector, so a pill and the inspector box always agree. A 0 pill is amber. Clicking it opens the
  // inspector at its Related Agreements box. Runs after applyIndustryDomRowEdits so saved edits count.
  // Holding's hub scorecard rows switch company on click (data-jump-co), so Holding entities get their
  // pills on the Tables explorer register, whose rows open the inspector.
  const IND_AGR_PILL_VIEWS = new Set(['re_properties', 're_units', 'hsp_memberships', 'trd_trucks', 'ins_policies', 'ins_statements']);
  const IND_AGR_PILL_EXPLORER_TABS = new Set(['re_prop_tbl', 'hsp_memb_tbl', 'trd_vin_tbl', 'ins_pol_tbl', 'ins_stm_tbl', 'hld_entities_tbl']);
  function applyIndustryRelatedAgreementPills(root) {
    if (!root || !root.querySelectorAll) return;
    const ind = getActiveIndustry(STATE.company);
    if (!ind || ind === 'Manufacturing') return;
    const tables = [];
    const explorer = root.querySelector('#industryDomainTablesExplorer');
    if (explorer && IND_AGR_PILL_EXPLORER_TABS.has(explorer.getAttribute('data-ind-tbl-active') || '')) {
      const exTbl = explorer.querySelector('table.data-table');
      if (exTbl) tables.push(exTbl);
    }
    if (IND_AGR_PILL_VIEWS.has(STATE.view)) {
      const hubTbl = Array.from(root.querySelectorAll('.panel table.data-table, .panel-card table.data-table, .panel table.ledger-table, .panel-card table.ledger-table'))
        .find(tb => !tb.closest('#industryDomainTablesExplorer') && !tb.closest('#industryPbiStudio') && !tb.closest('#industrySentinelsDetailPanel'));
      if (hubTbl) tables.push(hubTbl);
    }
    if (!tables.length) return;
    const pools = {};
    const rowCoDefault = COMPANY_BU_MATCH[STATE.company] || (!/^industry:/i.test(String(STATE.company || '')) ? COMPANY_LABELS[STATE.company] : '') || '';
    const tipLinked = 'Linked rate agreements. Click to review them.';
    const tipNone = 'No rate agreement linked yet. Click to add one.';
    for (const tbl of tables) {
      tbl.setAttribute('data-ind-agr-pills', '1');
      const headers = getDomainTableEnHeaders(tbl).map(h => String(h || '').replace(/\s*[▲▼]$/, '').trim());
      const trs = tbl.querySelectorAll('tbody tr');
      for (const tr of trs) {
        if (tr.hasAttribute('data-rid') || tr.hasAttribute('data-jump-co') || tr.hasAttribute('data-no-ind-inspect') || tr.classList.contains('total-row') || tr.classList.contains('totals-row') || tr.style.display === 'none') continue;
        const tds = Array.from(tr.querySelectorAll('td')).filter(tdEl => tdEl.style.display !== 'none');
        if (tds.length < 2 || tds[0].hasAttribute('colspan')) continue;
        const cells = tds.map(domainCellEnText);
        const primaryId = String(tr.getAttribute('data-ind-row-id') || cells[0] || '').trim();
        if (!primaryId) continue;
        cells[0] = primaryId;
        const info = computeIndustryRelatedAgreementsInfo({
          ind,
          headers,
          cells,
          primaryId,
          secondaryLbl: String(cells[1] || cells[2] || COMPANY_LABELS[STATE.company] || ind).trim(),
          rowCompany: tr.getAttribute('data-ind-row-co') || rowCoDefault,
          pools
        });
        if (!info) return; // this seat cannot see rate agreements
        const n = Math.max(0, Number(info.linkedCount) || 0);
        let pill = tds[0].querySelector('.ind-agr-pill');
        if (!pill) {
          pill = document.createElement('button');
          pill.type = 'button';
          pill.className = 'ind-agr-pill';
          pill.setAttribute('data-ind-agr-pill', '1');
          tds[0].appendChild(pill);
        }
        pill.classList.toggle('is-zero', n === 0);
        pill.setAttribute('data-ind-agr-count', String(n));
        pill.setAttribute('data-ui-tip', n ? tipLinked : tipNone);
        pill.setAttribute('aria-label', n ? tipLinked : tipNone);
        pill.innerHTML = `${ic('pricing')}<span class="ind-agr-pill-n" data-no-i18n="1">${n}</span>`;
      }
    }
  }

  function getIndustryCustomRowsStore() {
    if (!STATE.industryCustomRows || typeof STATE.industryCustomRows !== 'object') {
      STATE.industryCustomRows = (!IS_AUTOMATED_TEST ? lsGet('isabi_mfg_ind_custom_rows_v1', null) : null) || {};
    }
    return STATE.industryCustomRows;
  }

  function offloadIndustryCustomRowBlobs(storeObj) {
    const slim = {};
    Object.keys(storeObj || {}).forEach(bucket => {
      const arr = storeObj[bucket];
      if (!Array.isArray(arr)) { slim[bucket] = arr; return; }
      slim[bucket] = arr.map(rec => {
        if (!rec || typeof rec !== 'object') return rec;
        const copy = Object.assign({}, rec);
        if (typeof copy.data_url === 'string' && copy.data_url.length > 2048) {
          const bId = copy._blob_id || copy.id || copy.code;
          if (bId && typeof putDocBlob === 'function') {
            putDocBlob(bId, copy.data_url);
            copy._blob_id = bId;
            delete copy.data_url;
          }
        }
        if (Array.isArray(copy.attachments) && copy.attachments.length) {
          copy.attachments = copy.attachments.map(att => {
            if (!att || typeof att !== 'object') return att;
            const ac = Object.assign({}, att);
            if (typeof ac.data_url === 'string' && ac.data_url.length > 2048) {
              const abId = ac._blob_id || ac.id || ac.doc_id;
              if (abId && typeof putDocBlob === 'function') {
                putDocBlob(abId, ac.data_url);
                ac._blob_id = abId;
                delete ac.data_url;
              }
            }
            return ac;
          });
        }
        return copy;
      });
    });
    return slim;
  }

  function saveIndustryCustomRowsStore() {
    const store = getIndustryCustomRowsStore();
    const slim = offloadIndustryCustomRowBlobs(store);
    if (!IS_AUTOMATED_TEST) {
      try {
        appStoreSetRaw('isabi_mfg_ind_custom_rows_v1', JSON.stringify(slim));
      } catch (_) {}
    }
    postIndustryDomainStoreToLocalApi();
  }

  function getIndustryCustomRows(bucket) {
    const store = getIndustryCustomRowsStore();
    const arr = store[bucket];
    return Array.isArray(arr) ? arr.filter(r => r && !r.voided) : [];
  }

  function mergeCustomOverSeededRows(seededArr, customArr) {
    const custList = Array.isArray(customArr) ? customArr : [];
    const baseList = Array.isArray(seededArr) ? seededArr.slice() : [];
    if (!custList.length) return baseList;
    const prepend = [];
    custList.forEach(cr => {
      if (!cr || typeof cr !== 'object') return;
      const rawId = String(cr.id || cr.code || '').trim();
      const upgId = resolveLegacyIndustryId(rawId);
      const effId = upgId || rawId;
      const cid = effId.toUpperCase();
      if (!cid) { prepend.push(cr); return; }
      const idx = baseList.findIndex(sr => sr && String(sr.id || sr.code || '').trim().toUpperCase() === cid);
      if (idx >= 0) {
        baseList[idx] = Object.assign({}, baseList[idx], cr, { id: baseList[idx].id || effId });
      } else {
        prepend.push(upgId ? Object.assign({}, cr, { id: upgId }) : cr);
      }
    });
    return prepend.concat(baseList);
  }

  function invalidateIndustryDomainCaches() {
    STATE._indCustomRev = (STATE._indCustomRev || 0) + 1;
    if (typeof SEED !== 'undefined' && SEED) {
      SEED._customRev = (SEED._customRev || 0) + 1;
    }
    _icInteractionsCache = null;
    _icInteractionsSig = '';
    _reOpsCache = null;
    _reOpsSig = '';
    if (typeof _hspOpsCache !== 'undefined' && _hspOpsCache) _hspOpsCache.clear();
    if (typeof _indGlModelCache !== 'undefined' && _indGlModelCache) _indGlModelCache.clear();
    if (typeof _customAlertEvalCache !== 'undefined' && _customAlertEvalCache instanceof Map) _customAlertEvalCache.clear();
    if (typeof _sentinelRawItemsCache !== 'undefined' && _sentinelRawItemsCache instanceof Map) _sentinelRawItemsCache.clear();
    _liveSentinelCache = null;
    _FREQ_IDX = null;
  }

  // Rows the cloud totals from the resort gate tills: till close rows and, once a resort's posting date is
  // set, venue revenue rows. They belong to the server. This app shows them and never edits, voids or
  // patches them; a correction is made on the till (void the sale there) and the row re-totals itself.
  function isTillOwnedRowId(id) {
    return /^(HSP-REV-)?POS-[A-Z0-9_-]{1,64}-\d{8}-[0-9A-F]{6}$/.test(String(id || '').trim());
  }
  function isTillOwnedEditKey(editKey) {
    return /(^|::)(HSP-REV-)?POS-[A-Z0-9_-]{1,64}-\d{8}-[0-9A-F]{6}$/.test(String(editKey || ''));
  }
  // What this browser sends to the cloud never includes its copies of till rows or patches aimed at them
  // (the cloud would drop them anyway), so they are also left out when deciding whether there is anything to send.
  function withoutTillOwnedRows(rowsStore) {
    const out = {};
    Object.keys(rowsStore || {}).forEach(bk => {
      const list = rowsStore[bk];
      out[bk] = Array.isArray(list) ? list.filter(r => !(r && isTillOwnedRowId(r.id || r.code))) : list;
    });
    return out;
  }
  function withoutTillOwnedEdits(editStore) {
    const out = {};
    Object.keys(editStore || {}).forEach(ek => { if (!isTillOwnedEditKey(ek)) out[ek] = editStore[ek]; });
    return out;
  }
  function tillOwnedBadgeHtml() {
    return ` <span class="badge badge-info has-ico till-owned-badge" data-ui-tip="Totalled from the gate till's own sales. To correct it, void the sale on the till.">${ic('hsp_pos')}<span>From the till</span></span>`;
  }

  function getIndustryWorkflowPatch(bucket, rowId) {
    if (!bucket || !rowId) return null;
    if (isTillOwnedRowId(rowId)) return null;
    const store = getIndustryRowEditStore();
    const cleanId = String(rowId).trim();
    let hit = store[`WF::${bucket}::${cleanId}`];
    if (!hit) {
      const upg = resolveLegacyIndustryId(cleanId);
      if (upg) hit = store[`WF::${bucket}::${upg}`];
    }
    return (hit && typeof hit === 'object' && !hit.voided) ? hit : null;
  }

  function upgradeLegacyIndustryStores() {
    const map = SEED && SEED._industryLegacyIdMap;
    if (!map || !map.size) return false;
    let changed = false;
    if (!STATE._purgedIndustryLegacy || typeof STATE._purgedIndustryLegacy !== 'object') {
      STATE._purgedIndustryLegacy = { rows: [], editKeys: [] };
    }
    const pEditSet = new Set(STATE._purgedIndustryLegacy.editKeys || []);
    const pRowSet = new Set((STATE._purgedIndustryLegacy.rows || []).map(x => x.bucket + '::' + x.row_id));

    const editStore = getIndustryRowEditStore();
    if (editStore && typeof editStore === 'object') {
      Object.keys(editStore).forEach(ek => {
        if (isTillOwnedEditKey(ek)) return;
        const val = editStore[ek];
        if (!val || typeof val !== 'object') return;
        const parts = ek.split('::');
        if (parts.length < 3) return;
        const tailId = parts.slice(2).join('::').trim();
        const newId = resolveLegacyIndustryId(tailId);
        if (!newId || newId === tailId) return;
        const newKey = `${parts[0]}::${parts[1]}::${newId}`;
        const migrated = Object.assign({}, val);
        if (parts[0] !== 'WF') {
          migrated.primaryId = newId;
          if (Array.isArray(migrated.cells) && migrated.cells.length && String(migrated.cells[0] || '').trim().toUpperCase() === tailId.toUpperCase()) {
            migrated.cells = migrated.cells.slice();
            migrated.cells[0] = newId;
          }
        }
        delete editStore[ek];
        if (!pEditSet.has(ek)) {
          pEditSet.add(ek);
          STATE._purgedIndustryLegacy.editKeys.push(ek);
        }
        const existing = editStore[newKey];
        if (!existing || typeof existing !== 'object') {
          editStore[newKey] = migrated;
        } else {
          const eVoid = Boolean(existing.voided), mVoid = Boolean(migrated.voided);
          const eRev = Number(existing.rev || 1), mRev = Number(migrated.rev || 1);
          const eTs = String(existing.updated_at || existing.updatedAt || '');
          const mTs = String(migrated.updated_at || migrated.updatedAt || '');
          if (mVoid && !eVoid && mRev >= eRev) {
            editStore[newKey] = Object.assign({}, existing, migrated, { voided: true, rev: Math.max(eRev, mRev) });
          } else if (!(eVoid && !mVoid && eRev >= mRev) && (mRev > eRev || (mRev === eRev && mTs >= eTs))) {
            editStore[newKey] = Object.assign({}, existing, migrated, { rev: Math.max(eRev, mRev) });
          }
        }
        changed = true;
      });
    }

    const rowsStore = getIndustryCustomRowsStore();
    if (rowsStore && typeof rowsStore === 'object') {
      Object.keys(rowsStore).forEach(bucket => {
        const arr = rowsStore[bucket];
        if (!Array.isArray(arr) || !arr.length) return;
        let bucketChanged = false;
        const dedupByUp = new Map();
        const dedupOrder = [];
        arr.forEach(r => {
          if (!r || typeof r !== 'object') return;
          const rawId = String(r.id || r.code || '').trim();
          const newId = resolveLegacyIndustryId(rawId);
          if (newId && newId !== rawId) {
            if (r.code && String(r.code).trim().toUpperCase() === rawId.toUpperCase()) r.code = newId;
            r.id = newId;
            const rkPair = bucket + '::' + rawId;
            if (!pRowSet.has(rkPair)) {
              pRowSet.add(rkPair);
              STATE._purgedIndustryLegacy.rows.push({ bucket, row_id: rawId });
            }
            bucketChanged = true;
          }
          if (r.autoClosePriorId) {
            const upP = resolveLegacyIndustryId(r.autoClosePriorId);
            if (upP && upP !== r.autoClosePriorId) { r.autoClosePriorId = upP; bucketChanged = true; }
          }
          if (Array.isArray(r.autoClosePriorIds)) {
            let pidChanged = false;
            const nextPids = r.autoClosePriorIds.map(pid => {
              const upP = resolveLegacyIndustryId(pid);
              if (upP && upP !== pid) { pidChanged = true; return upP; }
              return pid;
            });
            if (pidChanged) { r.autoClosePriorIds = nextPids; bucketChanged = true; }
          }
          if (r._auto_closed_by_id) {
            const upBy = resolveLegacyIndustryId(r._auto_closed_by_id);
            if (upBy && upBy !== r._auto_closed_by_id) { r._auto_closed_by_id = upBy; bucketChanged = true; }
          }
          const keyUp = String(r.id || r.code || '').trim().toUpperCase();
          if (!keyUp) {
            dedupOrder.push({ raw: r });
            return;
          }
          if (!dedupByUp.has(keyUp)) {
            dedupByUp.set(keyUp, r);
            dedupOrder.push({ keyUp });
          } else {
            bucketChanged = true;
            const prev = dedupByUp.get(keyUp);
            const pVoid = Boolean(prev.voided), rVoid = Boolean(r.voided);
            const pRev = Number(prev.rev || 1), rRev = Number(r.rev || 1);
            const pTs = String(prev.updated_at || prev._createdAt || '');
            const rTs = String(r.updated_at || r._createdAt || '');
            if (rVoid && !pVoid && rRev >= pRev) {
              dedupByUp.set(keyUp, Object.assign({}, prev, r, { voided: true, rev: Math.max(pRev, rRev) }));
            } else if (!(pVoid && !rVoid && pRev >= rRev) && (rRev > pRev || (rRev === pRev && rTs >= pTs))) {
              dedupByUp.set(keyUp, Object.assign({}, prev, r, { rev: Math.max(pRev, rRev) }));
            }
          }
        });
        if (bucketChanged) {
          rowsStore[bucket] = dedupOrder.map(it => it.raw || dedupByUp.get(it.keyUp));
          changed = true;
        }
      });
    }

    const docArr = SEED && SEED.records && SEED.records.documents;
    if (Array.isArray(docArr)) {
      docArr.forEach(d => {
        if (!d || !d._demoSpineRow) return;
        const basePid = d._origParentId || d.parent_id;
        const newPid = resolveLegacyIndustryId(basePid);
        if (newPid && d.parent_id !== newPid) {
          if (d.parent_label === d.parent_id || d.parent_label === basePid) d.parent_label = newPid;
          d.parent_id = newPid;
          changed = true;
        }
      });
    }

    if (changed) {
      saveIndustryRowEditStore(editStore);
      saveIndustryCustomRowsStore();
      invalidateIndustryDomainCaches();
    }
    return changed;
  }

  function saveIndustryWorkflowPatch(bucket, rowId, patch) {
    if (!bucket || !rowId || !patch || typeof patch !== 'object') return null;
    if (isTillOwnedRowId(rowId)) return null;
    const store = getIndustryRowEditStore();
    const key = `WF::${bucket}::${String(rowId).trim()}`;
    const prev = (store[key] && typeof store[key] === 'object') ? store[key] : {};
    const next = Object.assign({}, prev, patch, {
      _revBumped: false,
      updated_at: new Date().toISOString()
    });
    store[key] = next;
    saveIndustryRowEditStore(store);
    invalidateIndustryDomainCaches();
    return next;
  }

  function addIndustryCustomRow(bucket, rowObj, opts = {}) {
    if (!bucket || !rowObj) return null;
    const store = getIndustryCustomRowsStore();
    if (!Array.isArray(store[bucket])) store[bucket] = [];
    const nowIso = new Date().toISOString();
    const pid = String(rowObj.id || rowObj.code || '').trim();
    if (isTillOwnedRowId(pid)) return null;
    const existingIdx = pid ? store[bucket].findIndex(r => r && String(r.id || r.code || '').trim() === pid) : -1;
    const prevRev = existingIdx >= 0 ? Number(store[bucket][existingIdx].rev || 1) : 0;
    const nextRev = Math.max(prevRev + 1, Number(rowObj.rev || 1));
    const tsIso = rowObj.updated_at || rowObj.updatedAt || nowIso;
    const rec = Object.assign(
      { _customBucket: bucket, _createdAt: nowIso, voided: false },
      existingIdx >= 0 ? store[bucket][existingIdx] : {},
      rowObj,
      { _customBucket: bucket, rev: nextRev, updated_at: tsIso, updatedAt: tsIso }
    );
    if (existingIdx >= 0) store[bucket][existingIdx] = rec;
    else store[bucket].unshift(rec);
    saveIndustryCustomRowsStore();
    invalidateIndustryDomainCaches();
    if ((!opts || !opts.skipCloudSync) && typeof syncWithCloud === 'function') syncWithCloud(true);
    return rec;
  }

  function voidIndustryCustomRowById(primaryId, opts = {}) {
    const pid = String(primaryId || '').trim();
    if (!pid || isTillOwnedRowId(pid)) return false;
    const store = getIndustryCustomRowsStore();
    const nowIso = new Date().toISOString();
    let hit = false;
    Object.keys(store).forEach(bucket => {
      if (!Array.isArray(store[bucket])) return;
      store[bucket].forEach(r => {
        if (r && String(r.id || r.code || '').trim() === pid) {
          r.voided = true;
          r.rev = Number(r.rev || 1) + 1;
          r.updated_at = nowIso;
          r.updatedAt = nowIso;
          hit = true;
        }
      });
    });
    if (hit) {
      saveIndustryCustomRowsStore();
      invalidateIndustryDomainCaches();
      if ((!opts || !opts.skipCloudSync) && typeof syncWithCloud === 'function') syncWithCloud(true);
    }
    return hit;
  }

  function mergeIndustryCustomRows(remoteMap) {
    if (!remoteMap || typeof remoteMap !== 'object') return false;
    const store = getIndustryCustomRowsStore();
    let changed = false;
    Object.keys(remoteMap).forEach(bucket => {
      const remArr = remoteMap[bucket];
      if (!Array.isArray(remArr)) return;
      if (!Array.isArray(store[bucket])) store[bucket] = [];
      const locArr = store[bucket];
      const byId = new Map();
      locArr.forEach(r => {
        if (!r || typeof r !== 'object') return;
        const id = String(r.id || r.code || '').trim();
        if (id) byId.set(id, r);
      });
      remArr.forEach(rem => {
        if (!rem || typeof rem !== 'object') return;
        const id = String(rem.id || rem.code || '').trim();
        if (!id) return;
        const loc = byId.get(id);
        if (!loc) {
          const clone = Object.assign({ _customBucket: bucket, rev: Number(rem.rev || 1), updated_at: rem.updated_at || rem._createdAt || new Date().toISOString() }, rem);
          locArr.push(clone);
          byId.set(id, clone);
          changed = true;
          return;
        }
        const lRev = Number(loc.rev || 1);
        const rRev = Number(rem.rev || 1);
        const lVoid = Boolean(loc.voided);
        const rVoid = Boolean(rem.voided);
        const lTs = String(loc.updated_at || loc._createdAt || '');
        const rTs = String(rem.updated_at || rem._createdAt || '');
        if (isTillOwnedRowId(id)) {
          // The server's copy of a till row always stands, whatever this browser holds (an older app
          // version could have voided or edited its own copy).
          if (lRev !== rRev || lVoid !== rVoid || lTs !== rTs) {
            const fresh = Object.assign({}, rem, { _customBucket: bucket });
            const idx = locArr.indexOf(loc);
            if (idx >= 0) locArr[idx] = fresh;
            byId.set(id, fresh);
            changed = true;
          }
          return;
        }
        if (rVoid && !lVoid && rRev >= lRev) {
          loc.voided = true;
          loc.rev = Math.max(lRev, rRev);
          loc.updated_at = rTs || lTs || new Date().toISOString();
          changed = true;
        } else if (lVoid && !rVoid && lRev >= rRev) {
          // keep local void tombstone
        } else if (rRev > lRev || (rRev === lRev && rTs > lTs)) {
          const merged = Object.assign({}, loc, rem, {
            _customBucket: bucket,
            voided: rVoid || (lVoid && lRev >= rRev),
            rev: Math.max(lRev, rRev),
            updated_at: rTs || lTs
          });
          const idx = locArr.indexOf(loc);
          if (idx >= 0) locArr[idx] = merged;
          byId.set(id, merged);
          changed = true;
        }
      });
    });
    if (changed) {
      upgradeLegacyIndustryStores();
      saveIndustryCustomRowsStore();
      invalidateIndustryDomainCaches();
    } else if (upgradeLegacyIndustryStores()) {
      changed = true;
    }
    return changed;
  }

  function mergeIndustryRowEdits(remoteMap) {
    if (!remoteMap || typeof remoteMap !== 'object') return false;
    const store = getIndustryRowEditStore();
    let changed = false;
    Object.keys(remoteMap).forEach(editKey => {
      const rem = remoteMap[editKey];
      if (!rem || typeof rem !== 'object') return;
      const loc = store[editKey];
      if (!loc || typeof loc !== 'object') {
        store[editKey] = Object.assign({ rev: Number(rem.rev || 1), _revBumped: true }, rem);
        changed = true;
        return;
      }
      const lRev = Number(loc.rev || 1);
      const rRev = Number(rem.rev || 1);
      const lVoid = Boolean(loc.voided);
      const rVoid = Boolean(rem.voided);
      const lTs = String(loc.updated_at || loc.updatedAt || '');
      const rTs = String(rem.updated_at || rem.updatedAt || '');
      const mergedRemovedDocs = Array.from(new Set([].concat(loc.removedDocIds || [], rem.removedDocIds || []).map(String).filter(Boolean)));
      if (rVoid && !lVoid && rRev >= lRev) {
        store[editKey] = Object.assign({}, loc, rem, {
          voided: true,
          rev: Math.max(lRev, rRev),
          removedDocIds: mergedRemovedDocs.length ? mergedRemovedDocs : undefined,
          updated_at: rTs || lTs,
          updatedAt: rTs || lTs,
          _revBumped: true
        });
        changed = true;
      } else if (rRev > lRev || (rRev === lRev && rTs > lTs)) {
        store[editKey] = Object.assign({}, loc, rem, {
          voided: rVoid || (lVoid && lRev >= rRev),
          rev: Math.max(lRev, rRev),
          removedDocIds: mergedRemovedDocs.length ? mergedRemovedDocs : undefined,
          updated_at: rTs || lTs,
          updatedAt: rTs || lTs,
          _revBumped: true
        });
        changed = true;
      } else if (mergedRemovedDocs.length > (Array.isArray(loc.removedDocIds) ? loc.removedDocIds.length : 0)) {
        loc.removedDocIds = mergedRemovedDocs;
        loc._revBumped = true;
        changed = true;
      }
    });
    if (changed) {
      upgradeLegacyIndustryStores();
      saveIndustryRowEditStore(store);
      invalidateIndustryDomainCaches();
    } else if (upgradeLegacyIndustryStores()) {
      changed = true;
    }
    return changed;
  }

  function clearIndustryCustomRows(bucket) {
    const store = getIndustryCustomRowsStore();
    if (bucket) delete store[bucket];
    else Object.keys(store).forEach(k => delete store[k]);
    saveIndustryCustomRowsStore();
    invalidateIndustryDomainCaches();
  }

  function prevCalendarDayISO(isoStr) {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(isoStr || '').trim());
    if (!m) return '2025-12-31';
    const dt = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
    dt.setUTCDate(dt.getUTCDate() - 1);
    return dt.toISOString().slice(0, 10);
  }

  function nextCalendarDayISO(isoStr) {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(isoStr || '').trim());
    if (!m) return '2026-01-02';
    const dt = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
    dt.setUTCDate(dt.getUTCDate() + 1);
    return dt.toISOString().slice(0, 10);
  }

  function normInsLineKey(rawLine) {
    const s = String(rawLine || '').trim();
    if (!s) return '';
    const parts = s.split('·').map(x => x.trim()).filter(Boolean);
    return (parts.length > 1 ? parts[parts.length - 1] : s).toLowerCase();
  }

  function lookupActiveInsuranceAgreementRate(carrier, line, effDate, recType) {
    const carStr = String(carrier || '').trim();
    const lineKey = normInsLineKey(line);
    const dtStr = /^\d{4}-\d{2}-\d{2}$/.test(String(effDate || '').trim())
      ? String(effDate).trim()
      : ((typeof todayISO === 'function' ? todayISO() : SEED_DATE) || '2026-11-06');
    const isRenewal = /renewal/i.test(String(recType || ''));
    const ops = typeof computeInsuranceOperations === 'function' ? computeInsuranceOperations() : { agreements: [], catalogue: [] };
    const agrs = Array.isArray(ops.agreements) ? ops.agreements : [];
    const activeHits = agrs.filter(a => {
      if (!a || norm(a.carrier) !== norm(carStr) || normInsLineKey(a.line) !== lineKey) return false;
      const sd = String(a.start_date || '1900-01-01').slice(0, 10);
      const ed = (!a.end_date || a.end_date === 'Open') ? '9999-12-31' : String(a.end_date).slice(0, 10);
      return dtStr >= sd && dtStr <= ed;
    }).sort((a, b) => {
      const sa = String(a.start_date || '');
      const sb = String(b.start_date || '');
      return sb > sa ? 1 : (sb < sa ? -1 : 0);
    });
    if (activeHits.length > 0) {
      const best = activeHits[0];
      const rate = Number(isRenewal ? (best.renewal_pct != null ? best.renewal_pct : best.new_bus_pct) : best.new_bus_pct);
      return {
        rate: Number.isFinite(rate) ? rate : 15,
        agreementId: best.id || 'AGR-ACTIVE',
        startDate: best.start_date || '',
        endDate: best.end_date || 'Open',
        isFallback: false
      };
    }
    const catList = Array.isArray(ops.catalogue) ? ops.catalogue : [];
    const catHit = catList.find(c => c && norm(c.carrier) === norm(carStr) && normInsLineKey(c.line) === lineKey)
      || catList.find(c => c && normInsLineKey(c.line) === lineKey);
    const fbRate = Number(catHit && catHit.base_comm_pct != null ? catHit.base_comm_pct : 15);
    return {
      rate: Number.isFinite(fbRate) ? fbRate : 15,
      agreementId: catHit && catHit.id ? catHit.id : 'CATALOGUE-BASELINE',
      startDate: '',
      endDate: '',
      isFallback: true
    };
  }

  function retroactiveBackfillInsuranceAgreement(agrObj, oldWindow = null) {
    if (!agrObj || !agrObj.carrier || !agrObj.line) return 0;
    const minDateCandidates = [String(agrObj.start_date || '2026-01-01').slice(0, 10)];
    if (oldWindow && oldWindow.start_date) minDateCandidates.push(String(oldWindow.start_date).slice(0, 10));
    minDateCandidates.sort();
    const sweepStart = minDateCandidates[0] || '2026-01-01';
    const newEnd = (!agrObj.end_date || agrObj.end_date === 'Open') ? '9999-12-31' : String(agrObj.end_date).slice(0, 10);
    const oldEnd = oldWindow ? ((!oldWindow.end_date || oldWindow.end_date === 'Open') ? '9999-12-31' : String(oldWindow.end_date).slice(0, 10)) : newEnd;
    const sweepEnd = newEnd >= oldEnd ? newEnd : oldEnd;

    const agrCar = norm(agrObj.carrier);
    const agrLineKey = normInsLineKey(agrObj.line);
    const ops = typeof computeInsuranceOperations === 'function' ? computeInsuranceOperations() : { policies: [] };
    const customPols = getIndustryCustomRows('ins_policies');
    const customIdSet = new Set(customPols.map(p => String(p.id || '').trim().toUpperCase()));
    let syncedCount = 0;
    (ops.policies || []).forEach(pol => {
      if (!pol || norm(pol.carrier) !== agrCar || normInsLineKey(pol.line) !== agrLineKey) return;
      const pDate = String(pol.date || pol.start_date || '').slice(0, 10);
      if (!pDate || pDate < sweepStart || pDate > sweepEnd) return;
      const rateHit = lookupActiveInsuranceAgreementRate(pol.carrier, pol.line, pDate, pol.type);
      const nextRate = Number(rateHit.rate || 0);
      const gwp = Number(pol.gross_prem_usd != null ? pol.gross_prem_usd : (pol.gwp_usd || 0));
      const gComm = round2(gwp * (nextRate / 100));
      const disc = Math.min(Number(pol.discount_usd || 0), gComm);
      const netComm = round2(gComm - disc);
      const payable = round2(gwp - gComm);
      const patch = {
        comm_rate_pct: nextRate,
        gross_comm_usd: gComm,
        discount_usd: disc,
        net_comm_usd: netComm,
        net_payable_4017_usd: payable
      };
      if (customIdSet.has(String(pol.id || '').trim().toUpperCase())) {
        addIndustryCustomRow('ins_policies', Object.assign({ id: pol.id }, patch), { skipCloudSync: true });
      } else {
        saveIndustryWorkflowPatch('ins_policies', pol.id, patch);
      }
      syncedCount += 1;
    });
    return syncedCount;
  }

  function computeChronoSweepBounds(newObj, oldWindow) {
    const starts = [String((newObj && newObj.start_date) || '2026-01-01').slice(0, 10)];
    if (oldWindow && oldWindow.start_date) starts.push(String(oldWindow.start_date).slice(0, 10));
    starts.sort();
    const sweepStart = starts[0] || '2026-01-01';
    const nEnd = (!newObj || !newObj.end_date || newObj.end_date === 'Open') ? '9999-12-31' : String(newObj.end_date).slice(0, 10);
    const oEnd = oldWindow ? ((!oldWindow.end_date || oldWindow.end_date === 'Open') ? '9999-12-31' : String(oldWindow.end_date).slice(0, 10)) : nEnd;
    return { sweepStart, sweepEnd: nEnd >= oEnd ? nEnd : oEnd };
  }

  function resolveDomainChronoSaveState(peers, existingSelf, sd, ed, isEditMode, guardLabel) {
    if (!sd || !/^\d{4}-\d{2}-\d{2}$/.test(sd)) {
      return { ok: false, error: `${guardLabel}: Effective Start Date (YYYY-MM-DD) is required.` };
    }
    const normEd = (!ed || /^open$/i.test(String(ed).trim())) ? 'Open' : String(ed).trim().slice(0, 10);
    if (normEd !== 'Open' && !/^\d{4}-\d{2}-\d{2}$/.test(normEd)) {
      return { ok: false, error: `${guardLabel}: Effective End Date must be YYYY-MM-DD or Open.` };
    }
    if (normEd !== 'Open' && sd >= normEd) {
      return { ok: false, error: `${guardLabel}: Effective End Date must be strictly after Start Date (or left Open).` };
    }
    const peerList = Array.isArray(peers) ? peers.filter(Boolean) : [];
    if (!isEditMode) {
      const priorOpens = peerList.filter(p => p.end_date === 'Open' || !p.end_date);
      if (priorOpens.some(p => sd <= p.start_date)) {
        const latestOpenStart = priorOpens.map(p => p.start_date).sort().slice(-1)[0];
        return { ok: false, error: `${guardLabel}: Start Date (${sd}) must be strictly after active Open schedule start (${latestOpenStart}).` };
      }
      const closedConflict = peerList.find(p => p.end_date && p.end_date !== 'Open' && sd <= p.end_date && (normEd === 'Open' || normEd >= p.start_date));
      if (closedConflict) {
        return { ok: false, error: `${guardLabel}: Start Date (${sd}) overlaps closed window ${closedConflict.id} (${closedConflict.start_date} to ${closedConflict.end_date}).` };
      }
      const priorOpen = priorOpens[0] || null;
      const closeIds = priorOpens.map(p => p.id);
      const closeDate = closeIds.length ? prevCalendarDayISO(sd) : '';
      return { ok: true, ed: normEd, priorOpen, closeIds, closeDate, priorPrimaryId: priorOpen ? priorOpen.id : '' };
    }

    const origStart = existingSelf && existingSelf.start_date ? String(existingSelf.start_date).slice(0, 10) : '';
    const origPrevDay = origStart ? prevCalendarDayISO(origStart) : '';
    let linkedIds = (existingSelf && Array.isArray(existingSelf.autoClosePriorIds) && existingSelf.autoClosePriorIds.length)
      ? existingSelf.autoClosePriorIds.slice()
      : ((existingSelf && existingSelf.autoClosePriorId) ? [existingSelf.autoClosePriorId] : []);
    if (!linkedIds.length && origPrevDay) {
      linkedIds = peerList
        .filter(p => p.end_date && p.end_date !== 'Open' && String(p.end_date).slice(0, 10) === origPrevDay)
        .map(p => p.id);
    }
    const linkedUpper = new Set(linkedIds.map(x => String(x || '').trim().toUpperCase()));
    const linkedPeers = peerList.filter(p => linkedUpper.has(String(p.id || '').trim().toUpperCase()));
    if (linkedPeers.some(p => sd <= p.start_date)) {
      const latestLinkedStart = linkedPeers.map(p => p.start_date).sort().slice(-1)[0];
      return { ok: false, error: `${guardLabel}: Start Date (${sd}) must remain after predecessor schedule start (${latestLinkedStart}).` };
    }
    const origEndRaw = existingSelf && existingSelf.end_date ? String(existingSelf.end_date).trim() : 'Open';
    const origEndCmp = (!origEndRaw || /^open$/i.test(origEndRaw)) ? '9999-12-31' : origEndRaw.slice(0, 10);
    const effEndCmp = normEd === 'Open' ? '9999-12-31' : normEd;
    const conflict = peerList.find(p => {
      if (linkedUpper.has(String(p.id || '').trim().toUpperCase())) return false;
      const pStart = String(p.start_date || '1900-01-01').slice(0, 10);
      const pEnd = (!p.end_date || p.end_date === 'Open') ? '9999-12-31' : String(p.end_date).slice(0, 10);
      if (origStart && origStart <= pEnd && origEndCmp >= pStart) return false;
      return sd <= pEnd && effEndCmp >= pStart;
    });
    if (conflict) {
      return { ok: false, error: `${guardLabel}: Window (${sd} to ${normEd}) overlaps schedule ${conflict.id} (${conflict.start_date} to ${conflict.end_date || 'Open'}).` };
    }
    const closeDate = linkedIds.length ? prevCalendarDayISO(sd) : '';
    const priorPeer = linkedPeers[0] || null;
    return {
      ok: true,
      ed: normEd,
      priorOpen: priorPeer,
      closeIds: linkedIds,
      closeDate,
      priorPrimaryId: linkedIds[0] || ''
    };
  }

  const SIBLING_CHRONO_FORM_KEYS = new Set([
    'ins_agreements', 're_leases', 'trd_targets', 'hsp_tariffs', 'hld_partners', 'hld_loans'
  ]);
  function isSiblingChronoFormKey(formKey) {
    return SIBLING_CHRONO_FORM_KEYS.has(String(formKey || '').trim());
  }
  function canManageSiblingChronoSchedule(formKey, u) {
    if (!isSiblingChronoFormKey(formKey)) return true;
    return canModifyData(u);
  }
  function syncSiblingCustomPredecessorsOnSave(bucket, savedId, closeIds, closeDate) {
    if (!bucket || !savedId) return;
    const store = getIndustryCustomRowsStore();
    const list = store[bucket];
    if (!Array.isArray(list) || !list.length) return;
    const savedIdUp = String(savedId).trim().toUpperCase();
    const closeSet = new Set((Array.isArray(closeIds) ? closeIds : []).map(x => String(x || '').trim().toUpperCase()).filter(Boolean));
    const nowIso = nextMonotonicIso();
    let changed = false;
    list.forEach(cp => {
      if (!cp || cp.voided) return;
      const cidUp = String(cp.id || cp.code || '').trim().toUpperCase();
      if (!cidUp || cidUp === savedIdUp) return;
      const wasClosedBySaved = String(cp._auto_closed_by_id || '').trim().toUpperCase() === savedIdUp;
      const origPrevEnd = cp._prev_end_date !== undefined ? String(cp._prev_end_date || 'Open') : '';
      const origBoundedPrev = /^\d{4}-\d{2}-\d{2}$/.test(origPrevEnd) ? origPrevEnd : '';
      if (closeSet.has(cidUp) && closeDate && (!origBoundedPrev || origBoundedPrev >= closeDate)) {
        if (cp._prev_end_date === undefined) cp._prev_end_date = cp.end_date || 'Open';
        if (cp._prev_status === undefined) cp._prev_status = cp.status || 'Active (Open)';
        cp.end_date = closeDate;
        cp._auto_closed_by_id = savedId;
        cp.status = 'Closed Window';
        cp.backfill_status = `Auto-Closed at ${closeDate}`;
        cp.rev = Number(cp.rev || 1) + 1;
        cp.updated_at = nowIso;
        cp.updatedAt = nowIso;
        changed = true;
      } else if (wasClosedBySaved) {
        const restEnd = origPrevEnd || 'Open';
        cp.end_date = restEnd;
        cp.status = cp._prev_status || (restEnd === 'Open' ? 'Active (Open)' : 'Scheduled Window');
        cp.backfill_status = 'Chrono Active';
        delete cp._auto_closed_by_id;
        delete cp._prev_end_date;
        delete cp._prev_status;
        cp.rev = Number(cp.rev || 1) + 1;
        cp.updated_at = nowIso;
        cp.updatedAt = nowIso;
        changed = true;
      }
    });
    if (changed) {
      saveIndustryCustomRowsStore();
      invalidateIndustryDomainCaches();
    }
  }
  function voidSiblingChronoSchedule(bucket, primaryId, origSched) {
    if (!bucket || !primaryId) return;
    const store = getIndustryCustomRowsStore();
    if (!Array.isArray(store[bucket])) store[bucket] = [];
    const list = store[bucket];
    const targetId = String((origSched && origSched.id) || primaryId).trim();
    const targetUp = targetId.toUpperCase();
    const nowIso = nextMonotonicIso();
    const exIdx = list.findIndex(r => r && String(r.id || r.code || '').trim().toUpperCase() === targetUp);
    const prevObj = exIdx >= 0 ? list[exIdx] : {};
    const linkedCloseIds = new Set(
      (Array.isArray(prevObj.autoClosePriorIds) ? prevObj.autoClosePriorIds : [])
        .concat(prevObj.autoClosePriorId ? [prevObj.autoClosePriorId] : [])
        .concat(origSched && Array.isArray(origSched.autoClosePriorIds) ? origSched.autoClosePriorIds : [])
        .concat(origSched && origSched.autoClosePriorId ? [origSched.autoClosePriorId] : [])
        .map(x => String(x || '').trim().toUpperCase())
        .filter(Boolean)
    );
    const nextRev = Number(prevObj.rev || 1) + 1;
    const tombstone = Object.assign(
      { _customBucket: bucket, _createdAt: nowIso },
      origSched || {},
      prevObj,
      {
        id: targetId,
        _customBucket: bucket,
        voided: true,
        _scheduleVoided: true,
        rev: nextRev,
        updated_at: nowIso,
        updatedAt: nowIso
      }
    );
    if (exIdx >= 0) list[exIdx] = tombstone;
    else list.unshift(tombstone);

    const vStart = String((prevObj && prevObj.start_date) || (origSched && origSched.start_date) || '').slice(0, 10);
    const vPrevDay = /^\d{4}-\d{2}-\d{2}$/.test(vStart) ? prevCalendarDayISO(vStart) : '';
    list.forEach(cp => {
      if (!cp || cp.voided) return;
      const cidUp = String(cp.id || cp.code || '').trim().toUpperCase();
      if (!cidUp || cidUp === targetUp) return;
      const closedByThis = String(cp._auto_closed_by_id || '').trim().toUpperCase() === targetUp
        || linkedCloseIds.has(cidUp)
        || (!cp._auto_closed_by_id && vPrevDay && String(cp.end_date || '').slice(0, 10) === vPrevDay && cp.status === 'Closed Window');
      if (!closedByThis) return;
      const restEnd = cp._prev_end_date !== undefined ? (cp._prev_end_date || 'Open') : 'Open';
      cp.end_date = restEnd;
      cp.status = cp._prev_status || (restEnd === 'Open' ? 'Active (Open)' : 'Scheduled Window');
      cp.backfill_status = 'Chrono Active';
      delete cp._auto_closed_by_id;
      delete cp._prev_end_date;
      delete cp._prev_status;
      cp.rev = Number(cp.rev || 1) + 1;
      cp.updated_at = nowIso;
      cp.updatedAt = nowIso;
    });
    saveIndustryCustomRowsStore();
    invalidateIndustryDomainCaches();
  }

  function runDomainChronoScheduleBackfill(formKey, schedRec, oldWindow) {
    if (formKey === 'ins_agreements') return retroactiveBackfillInsuranceAgreement(schedRec, oldWindow);
    if (formKey === 're_leases') return retroactiveBackfillRealEstateLease(schedRec, oldWindow);
    if (formKey === 'trd_targets') return retroactiveBackfillTradingTariff(schedRec, oldWindow);
    if (formKey === 'hsp_tariffs') return retroactiveBackfillHospitalityTariff(schedRec, oldWindow);
    if (formKey === 'hld_partners') return retroactiveBackfillHoldingPartner(schedRec, oldWindow);
    if (formKey === 'hld_loans') return retroactiveBackfillHoldingLoan(schedRec, oldWindow);
    return 0;
  }

  function lookupActiveHospitalityTariff(company, tierOrUnit, effDate) {
    const coStr = String(company || 'Blanca').trim();
    const tierStr = String(tierOrUnit || '').trim();
    const dtStr = /^\d{4}-\d{2}-\d{2}$/.test(String(effDate || '').trim())
      ? String(effDate).trim()
      : ((typeof todayISO === 'function' ? todayISO() : SEED_DATE) || '2026-11-06');
    const hsp = typeof computeHospitalityOperations === 'function' ? computeHospitalityOperations({ ignoreSearch: true }) : { tariffRows: [] };
    const coTariffs = (hsp.tariffRows || []).filter(t => t && norm(t.company) === norm(coStr));
    const dateHits = coTariffs.filter(t => {
      const sd = String(t.start_date || '1900-01-01').slice(0, 10);
      const ed = (!t.end_date || t.end_date === 'Open') ? '9999-12-31' : String(t.end_date).slice(0, 10);
      return dtStr >= sd && dtStr <= ed;
    });
    const exactDateHits = tierStr ? dateHits.filter(t => norm(t.tier) === norm(tierStr)) : [];
    const activeHits = (exactDateHits.length ? exactDateHits : dateHits).sort((a, b) => {
      const sa = String(a.start_date || '');
      const sb = String(b.start_date || '');
      return sb > sa ? 1 : (sb < sa ? -1 : 0);
    });
    if (activeHits.length > 0) {
      const best = activeHits[0];
      return {
        seasonal_rate_usd: Number(best.seasonal_rate_usd || 18500),
        nightly_rate_usd: Number(best.nightly_rate_usd || 560),
        tariffId: best.id || 'TRF-ACTIVE',
        tier: best.tier || tierStr,
        startDate: best.start_date || '',
        endDate: best.end_date || 'Open',
        isFallback: false
      };
    }
    const resortBaseMap = {
      'blanca': { seasonal: 18500, nightly: 560 },
      'palms': { seasonal: 15000, nightly: 490 },
      'voile': { seasonal: 22000, nightly: 680 },
      'la una': { seasonal: 9500, nightly: 350 },
      'platinum': { seasonal: 19500, nightly: 620 }
    };
    const fb = resortBaseMap[norm(coStr)] || { seasonal: 16500, nightly: 520 };
    return {
      seasonal_rate_usd: fb.seasonal,
      nightly_rate_usd: fb.nightly,
      tariffId: 'RESORT-CATALOG-BASELINE',
      tier: tierStr || 'Standard Resort Catalog',
      startDate: '',
      endDate: '',
      isFallback: true
    };
  }

  function retroactiveBackfillHospitalityTariff(trfObj, oldWindow = null) {
    if (!trfObj || !trfObj.company) return 0;
    const { sweepStart, sweepEnd } = computeChronoSweepBounds(trfObj, oldWindow);
    const hsp = typeof computeHospitalityOperations === 'function' ? computeHospitalityOperations({ ignoreSearch: true }) : { membershipRows: [], tariffRows: [] };
    const coTariffs = (hsp.tariffRows || []).filter(t => t && norm(t.company) === norm(trfObj.company));
    const customMems = getIndustryCustomRows('hsp_memberships');
    const customMemIds = new Set(customMems.map(m => String(m.id || '').trim().toUpperCase()));
    let syncedCount = 0;
    (hsp.membershipRows || []).forEach(m => {
      if (!m || norm(m.company) !== norm(trfObj.company)) return;
      const mDate = String(m.start_date || m.due_date || '').slice(0, 10);
      if (!mDate || mDate < sweepStart || mDate > sweepEnd) return;
      const qTier = m.tier || m.unit || '';
      const exactMatchExists = qTier ? coTariffs.some(t => norm(t.tier) === norm(qTier)) : false;
      if (exactMatchExists && norm(qTier) !== norm(trfObj.tier)) return;
      const hit = lookupActiveHospitalityTariff(m.company, qTier, mDate);
      const nextContract = round2(Number(hit.seasonal_rate_usd || m.contract_usd || 0));
      const paid = Math.min(nextContract, Number(m.paid_usd || 0));
      const bal = Math.max(0, round2(nextContract - paid));
      const patch = {
        contract_usd: nextContract,
        paid_usd: paid,
        balance_usd: bal,
        status: bal <= 0 ? 'Paid in Full' : 'Partial / Active'
      };
      if (customMemIds.has(String(m.id || '').trim().toUpperCase())) {
        addIndustryCustomRow('hsp_memberships', Object.assign({ id: m.id }, patch), { skipCloudSync: true });
      } else {
        saveIndustryWorkflowPatch('hsp_memberships', m.id, patch);
      }
      syncedCount += 1;
    });
    const customRevs = getIndustryCustomRows('hsp_revenue');
    customRevs.forEach(rev => {
      if (!rev || rev.voided || norm(rev.company) !== norm(trfObj.company)) return;
      if (!/chalet/i.test(String(rev.category || ''))) return;
      const rDate = String(rev.date || '').slice(0, 10);
      if (!rDate || rDate < sweepStart || rDate > sweepEnd) return;
      const hit = lookupActiveHospitalityTariff(rev.company, trfObj.tier || rev.outlet, rDate);
      const rooms = Math.max(1, Number(rev.rooms || 1));
      const tot = round2(rooms * Number(hit.nightly_rate_usd || 560));
      const ht = round2(tot / 1.11);
      const vat = round2(tot - ht);
      addIndustryCustomRow('hsp_revenue', Object.assign({}, rev, { ttc_usd: tot, ht_usd: ht, vat_usd: vat }), { skipCloudSync: true });
      syncedCount += 1;
    });
    return syncedCount;
  }

  function lookupActiveRealEstateLeaseRate(company, property, tenantOrUnit, effDate) {
    const coStr = String(company || '').trim();
    const propStr = String(property || '').trim();
    const tuStr = String(tenantOrUnit || '').trim();
    const dtStr = /^\d{4}-\d{2}-\d{2}$/.test(String(effDate || '').trim())
      ? String(effDate).trim()
      : ((typeof todayISO === 'function' ? todayISO() : SEED_DATE) || '2026-11-06');
    const re = typeof computeRealEstateOperations === 'function' ? computeRealEstateOperations({ ignoreSearch: true }) : { leases: [], units: [] };
    const leases = Array.isArray(re.leases) ? re.leases : [];
    const matchTenantOrUnit = l => {
      if (!tuStr) return !propStr || norm(l.property) === norm(propStr);
      const nTu = norm(tuStr);
      const nTen = norm(l.tenant || '');
      const nUnt = norm(l.unit || '');
      return nTen === nTu || nUnt === nTu || (nTen && (nTu.includes(nTen) || nTen.includes(nTu)));
    };
    const activeHits = leases.filter(l => {
      if (!l) return false;
      if (coStr && norm(l.company) !== norm(coStr)) return false;
      if (!matchTenantOrUnit(l)) return false;
      const sd = String(l.start_date || '1900-01-01').slice(0, 10);
      const ed = (!l.end_date || l.end_date === 'Open') ? '9999-12-31' : String(l.end_date).slice(0, 10);
      return dtStr >= sd && dtStr <= ed;
    }).sort((a, b) => {
      const sa = String(a.start_date || '');
      const sb = String(b.start_date || '');
      return sb > sa ? 1 : (sb < sa ? -1 : 0);
    });
    if (activeHits.length > 0) {
      const best = activeHits[0];
      const is4235 = /4235/i.test(best.company || coStr);
      return {
        net_period_usd: Number(best.net_period_usd || 12500),
        vat_rate: is4235 ? 11 : 0,
        frequency: best.frequency || 'Quarterly',
        leaseId: best.id || 'LSE-ACTIVE',
        property: best.property || propStr,
        tenant: best.tenant || tuStr,
        startDate: best.start_date || '',
        endDate: best.end_date || 'Open',
        isFallback: false
      };
    }
    const units = Array.isArray(re.units) ? re.units : [];
    const unitHit = units.find(u => u && ((tuStr && (norm(u.unit_name || u.name) === norm(tuStr) || norm(u.tenant) === norm(tuStr))) || (propStr && norm(u.property) === norm(propStr))))
      || units.find(u => u && (!coStr || norm(u.company) === norm(coStr)));
    const annRent = Number(unitHit && unitHit.annual_rent_usd > 0 ? unitHit.annual_rent_usd : (/4235/i.test(coStr) ? 44000 : 60000));
    const fbNet = round2(annRent / 4);
    const is4235 = /4235/i.test(coStr || (unitHit && unitHit.company) || '');
    return {
      net_period_usd: fbNet,
      vat_rate: is4235 ? 11 : 0,
      frequency: 'Quarterly',
      leaseId: (unitHit && unitHit.id) ? `${unitHit.id}-MARKET` : 'UNIT-MARKET-BASELINE',
      property: (unitHit && unitHit.property) || propStr,
      tenant: tuStr,
      startDate: '',
      endDate: '',
      isFallback: true
    };
  }

  function retroactiveBackfillRealEstateLease(leaseObj, oldWindow = null) {
    if (!leaseObj || !leaseObj.company) return 0;
    const { sweepStart, sweepEnd } = computeChronoSweepBounds(leaseObj, oldWindow);
    const re = typeof computeRealEstateOperations === 'function' ? computeRealEstateOperations({ ignoreSearch: true }) : { invoices: [] };
    const customInvs = getIndustryCustomRows('re_invoicing');
    const customInvIds = new Set(customInvs.map(iv => String(iv.id || '').trim().toUpperCase()));
    const nLeaseTen = norm(leaseObj.tenant || '');
    let syncedCount = 0;
    (re.invoices || []).forEach(inv => {
      if (!inv || norm(inv.company) !== norm(leaseObj.company)) return;
      const nInvTen = norm(inv.tenant || '');
      const sameTen = nLeaseTen && nInvTen && (nInvTen === nLeaseTen || nInvTen.includes(nLeaseTen) || nLeaseTen.includes(nInvTen));
      const linkedAutoInv = String(inv.id || '').toUpperCase() === `INV-${String(leaseObj.id || '').toUpperCase()}`;
      if (!sameTen && !linkedAutoInv) return;
      const iDate = String(inv.date || '').slice(0, 10);
      if (!iDate || iDate < sweepStart || iDate > sweepEnd) return;
      const hit = lookupActiveRealEstateLeaseRate(inv.company, inv.property || leaseObj.property, inv.tenant || leaseObj.tenant, iDate);
      const net = round2(Number(hit.net_period_usd || 0));
      const is4235 = /4235/i.test(inv.company);
      const vat = is4235 ? round2(net * 0.11) : 0;
      const tot = round2(net + vat);
      const col = Math.min(tot, Number(inv.collected_usd || 0));
      const openAr = Math.max(0, round2(tot - col));
      const patch = {
        net_usd: net,
        base_usd: net,
        vat_usd: vat,
        amount_ttc_usd: tot,
        ttc_usd: tot,
        collected_usd: col,
        open_ar_usd: openAr,
        status: openAr <= 0 ? 'Paid' : (col > 0 ? 'Partial' : 'Open')
      };
      if (customInvIds.has(String(inv.id || '').trim().toUpperCase())) {
        addIndustryCustomRow('re_invoicing', Object.assign({ id: inv.id }, patch), { skipCloudSync: true });
      } else {
        saveIndustryWorkflowPatch('re_invoicing', inv.id, patch);
      }
      syncedCount += 1;
    });
    return syncedCount;
  }

  function normTradingTariffCat(rawCat, coHint) {
    const s = String(rawCat || '').trim();
    if (/heavy truck|chassis|tractor|tipper|mixer|x3000|f3000|m3000/i.test(s)) return 'Heavy Truck Sale';
    if (/spare|part|tyre|component|filter|lubricant|hydraulic/i.test(s)) return 'Spare Parts & Tyres';
    return /shacman/i.test(String(coHint || '')) ? 'Heavy Truck Sale' : 'Spare Parts & Tyres';
  }

  function lookupActiveTradingTariff(company, categoryOrSupplier, effDate, mode = 'sale') {
    const coStr = String(company || 'Shacman').trim();
    const isShac = /shacman/i.test(coStr);
    const dtStr = /^\d{4}-\d{2}-\d{2}$/.test(String(effDate || '').trim())
      ? String(effDate).trim()
      : ((typeof todayISO === 'function' ? todayISO() : SEED_DATE) || '2026-11-06');
    const trd = typeof computeTradingOperations === 'function' ? computeTradingOperations({ ignoreSearch: true }) : { targetRows: [], serialUnits: [], stockRows: [] };
    const wantedCat = normTradingTariffCat(categoryOrSupplier, coStr);
    const activeHits = (trd.targetRows || []).filter(t => {
      if (!t || norm(t.company) !== norm(coStr)) return false;
      if (mode !== 'import' && normTradingTariffCat(t.category || t.segment, t.company) !== wantedCat) return false;
      const sd = String(t.start_date || `${t.month || '2026-08'}-01`).slice(0, 10);
      const ed = (!t.end_date || t.end_date === 'Open') ? '9999-12-31' : String(t.end_date).slice(0, 10);
      return dtStr >= sd && dtStr <= ed;
    }).sort((a, b) => {
      const sa = String(a.start_date || '');
      const sb = String(b.start_date || '');
      return sb > sa ? 1 : (sb < sa ? -1 : 0);
    });
    if (activeHits.length > 0) {
      const best = activeHits[0];
      return {
        unit_net_usd: Number(best.unit_net_usd != null ? best.unit_net_usd : (best.list_floor_usd || (isShac ? 79000 : 360))),
        unit_cost_usd: Number(best.unit_cost_usd != null ? best.unit_cost_usd : (isShac ? 65600 : 270)),
        fob_unit_usd: Number(best.fob_unit_usd != null ? best.fob_unit_usd : (isShac ? 62500 : 190)),
        landed_pct: Number(best.landed_pct != null ? best.landed_pct : (isShac ? 9.06 : 13.44)),
        scheduleId: best.id || 'TGT-ACTIVE',
        startDate: best.start_date || '',
        endDate: best.end_date || 'Open',
        isFallback: false
      };
    }
    const unitRef = isShac ? (trd.serialUnits || []).find(u => u && norm(u.company) === norm(coStr)) : null;
    const stkRef = !isShac ? (trd.stockRows || []).find(k => k && norm(k.company) === norm(coStr)) : null;
    return {
      unit_net_usd: isShac ? round2(Number(unitRef && unitRef.list_price_usd ? unitRef.list_price_usd / 1.11 : 78000)) : Number(stkRef && stkRef.retail_usd ? stkRef.retail_usd : 345),
      unit_cost_usd: isShac ? Number(unitRef && unitRef.landed_cost_usd ? unitRef.landed_cost_usd : 65600) : Number(stkRef && stkRef.wac_usd ? stkRef.wac_usd : 265),
      fob_unit_usd: isShac ? Number(unitRef && unitRef.fob_usd ? unitRef.fob_usd : 60200) : 185,
      landed_pct: isShac ? 8.97 : 12.50,
      scheduleId: isShac ? 'SHOWROOM-CATALOG-BASELINE' : 'PARTS-CATALOG-BASELINE',
      startDate: '',
      endDate: '',
      isFallback: true
    };
  }

  function retroactiveBackfillTradingTariff(tgtObj, oldWindow = null) {
    if (!tgtObj || !tgtObj.company) return 0;
    const { sweepStart, sweepEnd } = computeChronoSweepBounds(tgtObj, oldWindow);
    const trd = typeof computeTradingOperations === 'function' ? computeTradingOperations({ ignoreSearch: true }) : { salesRows: [], importRows: [] };
    const customSalesIds = new Set(getIndustryCustomRows('trd_sales').map(s => String(s.id || '').trim().toUpperCase()));
    const customImpIds = new Set(getIndustryCustomRows('trd_purchases').map(i => String(i.id || '').trim().toUpperCase()));
    const tgtCat = normTradingTariffCat(tgtObj.category || tgtObj.segment, tgtObj.company);
    let syncedCount = 0;
    (trd.salesRows || []).forEach(sl => {
      if (!sl || sl.is_gap || norm(sl.company) !== norm(tgtObj.company)) return;
      if (normTradingTariffCat(sl.category, sl.company) !== tgtCat) return;
      const sDate = String(sl.date || '').slice(0, 10);
      if (!sDate || sDate < sweepStart || sDate > sweepEnd) return;
      const hit = lookupActiveTradingTariff(sl.company, sl.category, sDate, 'sale');
      const qty = Math.max(1, Number(sl.qty || 1));
      const net = round2(qty * Number(hit.unit_net_usd || 0));
      const vat = round2(net * 0.11);
      const ttc = round2(net + vat);
      const cost = round2(qty * Number(hit.unit_cost_usd || 0));
      const patch = { net_usd: net, vat_usd: vat, ttc_usd: ttc, cost_usd: cost };
      if (customSalesIds.has(String(sl.id || '').trim().toUpperCase())) {
        addIndustryCustomRow('trd_sales', Object.assign({ id: sl.id }, patch), { skipCloudSync: true });
      } else {
        saveIndustryWorkflowPatch('trd_sales', sl.id, patch);
      }
      syncedCount += 1;
    });
    (trd.importRows || []).forEach(im => {
      if (!im || norm(im.company) !== norm(tgtObj.company)) return;
      const iDate = String(im.date || '').slice(0, 10);
      if (!iDate || iDate < sweepStart || iDate > sweepEnd) return;
      const hit = lookupActiveTradingTariff(im.company, im.supplier, iDate, 'import');
      const ord = Math.max(1, Number(im.ordered_qty || 1));
      const fob = round2(ord * Number(hit.fob_unit_usd || 0));
      const add = round2(fob * (Number(hit.landed_pct || 0) / 100));
      const tot = round2(fob + add);
      const patch = { fob_usd: fob, landed_add_usd: add, total_landed_usd: tot };
      if (customImpIds.has(String(im.id || '').trim().toUpperCase())) {
        addIndustryCustomRow('trd_purchases', Object.assign({ id: im.id }, patch), { skipCloudSync: true });
      } else {
        saveIndustryWorkflowPatch('trd_purchases', im.id, patch);
      }
      syncedCount += 1;
    });
    return syncedCount;
  }

  function lookupActiveHoldingPartnerSplit(entity, partner, effDate) {
    const entStr = String(entity || 'Bdeir Holding').trim();
    const prtStr = String(partner || '').trim();
    const normEnt = s => norm(String(s || '').split('·')[0]);
    const dtStr = /^\d{4}-\d{2}-\d{2}$/.test(String(effDate || '').trim())
      ? String(effDate).trim()
      : ((typeof todayISO === 'function' ? todayISO() : SEED_DATE) || '2026-11-06');
    const sched = typeof computeHoldingSchedules === 'function' ? computeHoldingSchedules() : { partnerAgreements: [] };
    const entPeers = (sched.partnerAgreements || []).filter(a => a && normEnt(a.entity) === normEnt(entStr));
    const dateHits = entPeers.filter(a => {
      const sd = String(a.start_date || '1900-01-01').slice(0, 10);
      const ed = (!a.end_date || a.end_date === 'Open') ? '9999-12-31' : String(a.end_date).slice(0, 10);
      return dtStr >= sd && dtStr <= ed;
    });
    const exactDateHits = prtStr ? dateHits.filter(a => norm(a.partner) === norm(prtStr)) : [];
    const activeHits = (exactDateHits.length ? exactDateHits : dateHits).sort((a, b) => {
      const sa = String(a.start_date || '');
      const sb = String(b.start_date || '');
      return sb > sa ? 1 : (sb < sa ? -1 : 0);
    });
    if (activeHits.length > 0) {
      const best = activeHits[0];
      const sid = best.id || 'HLD-PRT-ACTIVE';
      return {
        pct: Number(best.pct || 50),
        agreementId: sid,
        scheduleId: sid,
        startDate: best.start_date || '',
        endDate: best.end_date || 'Open',
        isFallback: false
      };
    }
    const peerBase = entPeers[0] || null;
    const fbPct = Number(peerBase && peerBase.baseline_pct != null ? peerBase.baseline_pct : (/bdeir holding/i.test(entStr) ? 45.0 : 30.0));
    return {
      pct: fbPct,
      agreementId: 'CHARTER-DEFAULT-SPLIT',
      scheduleId: 'CHARTER-DEFAULT-SPLIT',
      startDate: '',
      endDate: '',
      isFallback: true
    };
  }

  function retroactiveBackfillHoldingPartner(prtObj, oldWindow = null) {
    if (!prtObj || !prtObj.entity) return 0;
    const normEnt = s => norm(String(s || '').split('·')[0]);
    const { sweepStart, sweepEnd } = computeChronoSweepBounds(prtObj, oldWindow);
    const sched = typeof computeHoldingSchedules === 'function' ? computeHoldingSchedules() : { partnerDistributions: [] };
    const customDistIds = new Set(getIndustryCustomRows('hld_distributions').map(d => String(d.id || '').trim().toUpperCase()));
    const entDists = (sched.partnerDistributions || []).filter(dist => dist && normEnt(dist.entity) === normEnt(prtObj.entity));
    const hasExactPrtDist = prtObj.partner ? entDists.some(d => norm(d.partner) === norm(prtObj.partner)) : false;
    let syncedCount = 0;
    entDists.forEach(dist => {
      if (hasExactPrtDist && norm(dist.partner) !== norm(prtObj.partner)) return;
      const dDate = String(dist.date || '').slice(0, 10);
      if (!dDate || dDate < sweepStart || dDate > sweepEnd) return;
      const hit = lookupActiveHoldingPartnerSplit(dist.entity, dist.partner, dDate);
      const pool = Number(dist.pool_usd || 0);
      const ent = round2(pool * (Number(hit.pct || 0) / 100));
      const paid = Math.min(ent, Number(dist.paid_usd || 0));
      const opn = Math.max(0, round2(ent - paid));
      const patch = {
        pct: hit.pct,
        entitled_usd: ent,
        paid_usd: paid,
        open_usd: opn,
        agreement_id: hit.agreementId,
        status: opn <= 0 ? 'Settled' : 'Active Tranche'
      };
      if (customDistIds.has(String(dist.id || '').trim().toUpperCase())) {
        addIndustryCustomRow('hld_distributions', Object.assign({ id: dist.id }, patch), { skipCloudSync: true });
      } else {
        saveIndustryWorkflowPatch('hld_distributions', dist.id, patch);
      }
      syncedCount += 1;
    });
    return syncedCount;
  }

  function lookupActiveHoldingLoanRate(company, lender, facType, effDate) {
    if (effDate === undefined && /^\d{4}-\d{2}-\d{2}$/.test(String(facType || '').trim())) {
      effDate = facType;
      facType = '';
    }
    const coStr = String(company || 'Bdeir Holding').trim();
    const lndStr = String(lender || '').trim();
    const dtStr = /^\d{4}-\d{2}-\d{2}$/.test(String(effDate || '').trim())
      ? String(effDate).trim()
      : ((typeof todayISO === 'function' ? todayISO() : SEED_DATE) || '2026-11-06');
    const sched = typeof computeHoldingSchedules === 'function' ? computeHoldingSchedules() : { facilitySchedules: [] };
    const facs = sched.facilitySchedules || [];
    const hasLenderPeers = lndStr ? facs.some(f => f && norm(f.lender) === norm(lndStr)) : false;
    const activeHits = facs.filter(f => {
      if (!f) return false;
      if (hasLenderPeers ? norm(f.lender) !== norm(lndStr) : norm(f.company) !== norm(coStr)) return false;
      const sd = String(f.start_date || '1900-01-01').slice(0, 10);
      const ed = (!f.end_date || f.end_date === 'Open') ? '9999-12-31' : String(f.end_date).slice(0, 10);
      return dtStr >= sd && dtStr <= ed;
    }).sort((a, b) => {
      const sa = String(a.start_date || '');
      const sb = String(b.start_date || '');
      return sb > sa ? 1 : (sb < sa ? -1 : 0);
    });
    if (activeHits.length > 0) {
      const best = activeHits[0];
      const apr = Number(best.apr_pct != null ? best.apr_pct : (best.interest_rate_pct != null ? best.interest_rate_pct : (best.rate_apr_pct != null ? best.rate_apr_pct : 6.5)));
      const fid = best.id || 'FAC-ACTIVE';
      return {
        apr_pct: apr,
        rate_apr_pct: apr,
        interest_rate_pct: apr,
        facilityId: fid,
        scheduleId: fid,
        startDate: best.start_date || '',
        endDate: best.end_date || 'Open',
        isFallback: false
      };
    }
    const peerBase = facs.find(f => f && (hasLenderPeers ? norm(f.lender) === norm(lndStr) : norm(f.company) === norm(coStr)));
    const fbApr = Number(peerBase && peerBase.baseline_rate_pct != null ? peerBase.baseline_rate_pct : 5.0);
    return {
      apr_pct: fbApr,
      rate_apr_pct: fbApr,
      interest_rate_pct: fbApr,
      facilityId: 'TREASURY-BENCHMARK-APR',
      scheduleId: 'TREASURY-BENCHMARK-APR',
      startDate: '',
      endDate: '',
      isFallback: true
    };
  }

  function retroactiveBackfillHoldingLoan(loanObj, oldWindow = null) {
    if (!loanObj) return 0;
    const { sweepStart, sweepEnd } = computeChronoSweepBounds(loanObj, oldWindow);
    const sched = typeof computeHoldingSchedules === 'function' ? computeHoldingSchedules() : { loanAccruals: [] };
    const customAccIds = new Set(getIndustryCustomRows('hld_loan_accruals').map(a => String(a.id || '').trim().toUpperCase()));
    let syncedCount = 0;
    (sched.loanAccruals || []).forEach(ac => {
      if (!ac) return;
      const sameLender = loanObj.lender && norm(ac.lender) === norm(loanObj.lender);
      const sameFac = String(ac.facility_id || '').toUpperCase() === String(loanObj.id || '').toUpperCase();
      if (!sameLender && !sameFac) return;
      const aDate = String(ac.date || '').slice(0, 10);
      if (!aDate || aDate < sweepStart || aDate > sweepEnd) return;
      const hit = lookupActiveHoldingLoanRate(ac.company || loanObj.company, ac.lender || loanObj.lender, loanObj.type || '', aDate);
      const prin = Number(ac.principal_usd != null ? ac.principal_usd : (ac.balance_usd != null ? ac.balance_usd : (loanObj.balance_usd || loanObj.principal_usd || 0)));
      const yearFrac = ac.days != null ? (Math.max(1, Number(ac.days)) / 365) : 0.25;
      const aprVal = Number(hit.apr_pct != null ? hit.apr_pct : (hit.rate_apr_pct || 0));
      const interest = round2(prin * (aprVal / 100) * yearFrac);
      const patch = {
        apr_pct: aprVal,
        interest_rate_pct: aprVal,
        rate_apr_pct: aprVal,
        accrued_usd: interest,
        interest_usd: interest,
        facility_id: hit.facilityId || hit.scheduleId
      };
      if (customAccIds.has(String(ac.id || '').trim().toUpperCase())) {
        addIndustryCustomRow('hld_loan_accruals', Object.assign({ id: ac.id }, patch), { skipCloudSync: true });
      } else {
        saveIndustryWorkflowPatch('hld_loan_accruals', ac.id, patch);
      }
      syncedCount += 1;
    });
    return syncedCount;
  }

  function freqRankCandidates(colHint, candidates) {
    const uniq = [];
    const seen = new Set();
    (candidates || []).forEach(v => {
      const s = String(v == null ? '' : v).trim();
      if (!s) return;
      const k = s.toLowerCase();
      if (!seen.has(k)) { seen.add(k); uniq.push(s); }
    });
    try {
      const fIdx = typeof window.MFG_FREQ === 'function' ? window.MFG_FREQ() : null;
      if (fIdx && typeof fIdx.forCol === 'function') {
        const ranked = fIdx.forCol(colHint || 'party', uniq);
        if (Array.isArray(ranked) && ranked.length) return ranked;
      }
    } catch (_) {}
    return uniq;
  }

