    FORM_UI.lastTruck = val('f_truck'); FORM_UI.lastExpTruck = val('f_truck'); FORM_UI.lastWhItem = ''; FORM_UI.lastOilUnit = ''; FORM_UI.lastOilType = '';
    FORM_UI.lastTruckOwner = val('f_truckowner');
    FORM_UI.lastSaleType = val('f_saletype'); FORM_UI.lastTransportBy = val('f_transportby');
    FORM_UI.lastSite = val('f_site'); FORM_UI.lastSiteOwner = val('f_siteowner'); FORM_UI.lastProduct = val('f_product');
    FORM_UI.siteAutoFilledFromCustomer = false; FORM_UI.custAutoFilledFromSite = false; FORM_UI.siteAutoFilledFromOwner = false; FORM_UI.lastSalesSiteCustKey = ''; FORM_UI.lastRawEffDate = val('f_date') || '';
    FORM_UI.lastCustomer = val('f_customer'); FORM_UI.lastSupplier = val('f_supplier'); FORM_UI.lastSettleSupplier = val('f_supplier'); FORM_UI.lastDupSig = ''; FORM_UI.lastUom = val('f_uom') || ''; FORM_UI.lastPrCoSide = '';
    FORM_UI.lastWinKey = ''; FORM_UI.lastFuelWinKey = ''; FORM_UI.lastFuelItem = val('f_item'); FORM_UI.greaseAutoPreset = false;
    FORM_UI.defectRefPreset = false; FORM_UI.lastSeverity = ''; FORM_UI.lastDefectRef = '';
    FORM_UI.attPreset = 'regular'; FORM_UI.attClockManual = false;
    FORM_UI.lastAttStaff = ''; FORM_UI.lastAttShiftKey = ''; FORM_UI.lastAttDate = val('f_date'); FORM_UI.lastAttTimeKey = '';
    FORM_UI.lastEmpRole = ''; FORM_UI.lastStaffRoleName = '';
    FORM_UI.lastSalStaffMonthKey = '';
    FORM_UI.salBackpayOn = false; FORM_UI.lastSalBackpayKey = '';
    FORM_UI.wasPricePending = false; FORM_UI.methodBeforePending = '';
    FORM_UI.originMode = 'company'; FORM_UI.originBu = ''; FORM_UI.originPriorDisposition = 'keep'; FORM_UI.lastAutoFilledOriginTicket = '';
    FORM_UI.originMiniMapOpen = false; FORM_UI.originMapTarget = 'dest'; FORM_UI.originKmEditOpen = false;
    FORM_UI.ticketDisposition = 'standard'; FORM_UI.returnWtcSubMode = 'pair'; FORM_UI.returnRtKmManual = false; FORM_UI.lastDispMode = 'standard'; FORM_UI.ticketSeriesTabOpen = false; FORM_UI.ticketBookGridOpen = false; FORM_UI.lastAutoFilledReturnTicket = '';
    FORM_UI.convPrimarySide = ''; FORM_UI.convRateFromAmounts = false;
