    if (window.MFG_I18N && window.MFG_I18N.getLang() !== 'en') {
      window.MFG_I18N.translateDom(modal || document.body);
    }
    FORM_UI.userInteracted = false;
    FORM_UI.initialModalSig = getEntryModalStateSignature();
