  function closeEntryModal(force, ev) {
    if (STATE.saving && !force) return;
    const isInteractiveClose = Boolean((ev && ev.isTrusted) || window.__MFG_TEST_UNSAVED_CLOSE);
    if (!force && isInteractiveClose && isEntryModalDirty()) {
      promptUnsavedEntrySwitch({ type: 'close' });
      return;
    }
    hideEntryUnsavedPrompt();
    FORM_UI.userInteracted = false;
    FORM_UI.initialModalSig = '';
    if (window.MFG_SMART_SCAN && typeof window.MFG_SMART_SCAN.resetModalState === 'function') {
      window.MFG_SMART_SCAN.resetModalState();
    }
    if (window.MFG_AI_EDGE && typeof window.MFG_AI_EDGE.stopVoiceCapture === 'function') {
      window.MFG_AI_EDGE.stopVoiceCapture();
    }
    if (window.MFG_GEO && typeof window.MFG_GEO.cleanupTicketOriginMiniMap === 'function') {
      window.MFG_GEO.cleanupTicketOriginMiniMap();
    }
    STATE.editingRecord = null;
    STATE.editingPendingExpenseId = '';
    STATE.editingPendingRawId = '';
    STATE.editingPendingSalaryId = '';
    const openInspBtn = $('modalOpenInspectorBtn');
    if (openInspBtn) { openInspBtn.hidden = true; openInspBtn.onclick = null; }
    const printThermalBtn = $('modalPrintThermalBtn');
    if (printThermalBtn) { printThermalBtn.hidden = true; printThermalBtn.onclick = null; }
    const tw = $('modalTabs');
    if (tw) tw.hidden = false;
    const modal = $('entryModal');
    if (modal) modal.hidden = true;
    document.body.classList.remove('modal-open');
    if (STATE.view === 'kiosks') {
      const mBody = $('modalBody');
      if (mBody) mBody.innerHTML = '';
      STATE.renderPending = false;
      renderApp();
      return;
    }
    if (STATE.renderPending) { STATE.renderPending = false; renderApp(); }
  }

