  function getActiveIndustry(coKey) {
    const k = String(coKey || STATE.company || 'manufacturing-group');
    if (k === DEMO_COMPANY_KEY) return STATE.demoCompanyIndustry || 'Hospitality & Resorts';
    if (k === 'manufacturing-group' || k === 'ALL') return 'Manufacturing';
    if (k === 'bdeirholding') return 'Holding & Treasury';
    if (k.startsWith('industry:')) {
      const slug = k.slice(9).trim();
      const sl = slug.toLowerCase();
      if (sl === 'holding' || sl === 'holding & treasury') return 'Holding & Treasury';
      if (sl === 'hospitality' || sl === 'hospitality & resorts') return 'Hospitality & Resorts';
      if (sl === 'trading' || sl === 'automotive & heavy trading') return 'Automotive & Heavy Trading';
      if (sl === 'realestate' || sl === 'real estate' || sl === 'real estate & property') return 'Real Estate & Property';
      if (sl === 'insurance' || sl === 'insurance & brokerage') return 'Insurance & Brokerage';
      if (sl === 'manufacturing') return 'Manufacturing';
      return slug || 'Manufacturing';
    }
    if (COMPANY_INDUSTRY_BY_KEY[k]) return COMPANY_INDUSTRY_BY_KEY[k];
    const cat = getCompanyCatalog();
    const hit = cat.find(c => c.key === k || c.name.toLowerCase() === k.toLowerCase());
    return (hit && hit.industry) || 'Manufacturing';
  }
  window.__mfgGetActiveIndustry = getActiveIndustry;

  function isRowInActiveIndustry(r, ind = getActiveIndustry()) {
    if (!r) return false;
    return ind === 'Manufacturing'
      ? (!r._multiIndustrySeed && (!r._industry || r._industry === 'Manufacturing'))
      : r._industry === ind;
  }

  function resolveIndustryCompatibleView(view, targetInd) {
    const effInd = (targetInd && INDUSTRY_SIDEBAR_SPEC[targetInd])
      ? targetInd
      : (INDUSTRY_SIDEBAR_SPEC[getActiveIndustry(STATE.company)] ? getActiveIndustry(STATE.company) : 'Manufacturing');
    const nextSpec = INDUSTRY_SIDEBAR_SPEC[effInd] || INDUSTRY_SIDEBAR_SPEC['Manufacturing'];
    const curHub = VIEW_TO_HUB[view] || view;
    const allSpecs = Object.values(INDUSTRY_SIDEBAR_SPEC);
    for (let i = 0; i < allSpecs.length; i++) {
      const sIdx = allSpecs[i].slots.findIndex(s => s.hub === curHub);
      if (sIdx >= 0) {
        if (nextSpec.slots[sIdx] && nextSpec.slots[sIdx].hub !== curHub) {
          return nextSpec.slots[sIdx].view;
        }
        return view;
      }
    }
    const hubDef = getHubDef(curHub);
    if (hubDef && hubDef.industry && hubDef.industry !== effInd) {
      return (nextSpec.slots[0] && nextSpec.slots[0].view) || 'overview';
    }
    return view;
  }

  function syncSidebarHubVisibilityDom(u) {
    const user = u || activeUser();
    document.querySelectorAll('#sidebarNav .nav-item').forEach(btn => {
      const hubId = btn.getAttribute('data-hub') || btn.getAttribute('data-view');
      btn.hidden = !canViewHub(hubId, user);
    });
    document.querySelectorAll('#sidebarNav .grp').forEach(grpEl => {
      let sib = grpEl.nextElementSibling, anyVisible = false;
      while (sib && !sib.classList.contains('grp')) {
        if (sib.classList.contains('nav-item') && !sib.hidden) { anyVisible = true; break; }
        sib = sib.nextElementSibling;
      }
      grpEl.hidden = !anyVisible;
    });
    const sysBar = $('railSystemBar');
    if (sysBar) {
      let anySysVisible = false;
      sysBar.querySelectorAll('button.rail-sys-btn[data-hub]').forEach(btn => {
        const hubId = btn.getAttribute('data-hub') || btn.getAttribute('data-view');
        const vis = canViewHub(hubId, user);
        btn.hidden = !vis;
        if (vis) anySysVisible = true;
      });
      sysBar.hidden = !anySysVisible;
    }
  }

  let _lastSyncedSidebarInd = 'Manufacturing';
  function syncIndustrySidebarDom(indId) {
    const effInd = (indId && INDUSTRY_SIDEBAR_SPEC[indId]) ? indId : (INDUSTRY_SIDEBAR_SPEC[getActiveIndustry(STATE.company)] ? getActiveIndustry(STATE.company) : 'Manufacturing');
    const navEl = $('sidebarNav');
    if (!navEl) return;
    const spec = INDUSTRY_SIDEBAR_SPEC[effInd] || INDUSTRY_SIDEBAR_SPEC['Manufacturing'];
    const grps = navEl.querySelectorAll('.grp');
    if (grps[1] && grps[1].textContent !== spec.grp1) grps[1].textContent = spec.grp1;
    if (grps[2] && grps[2].textContent !== spec.grp2) grps[2].textContent = spec.grp2;

    // The 4 swappable operational hub buttons sit at indices 3, 4 (before expenses at 5) and 6, 7 (before payroll at 8)
    const navBtns = navEl.querySelectorAll('button.nav-item');
    const slotIndices = [3, 4, 6, 7];
    const activeHubId = VIEW_TO_HUB[STATE.view] || 'overview';
    slotIndices.forEach((btnIdx, slotIdx) => {
      const btn = navBtns[btnIdx];
      const slot = spec.slots[slotIdx];
      if (!btn || !slot) return;
      const prevHub = btn.getAttribute('data-hub');
      if (prevHub !== slot.hub) {
        btn.setAttribute('data-hub', slot.hub);
        btn.setAttribute('data-view', slot.view);
        btn.setAttribute('aria-label', slot.label);
        const icoEl = btn.querySelector('.nav-ico');
        if (icoEl && window.MFG_ICONS) {
          icoEl.outerHTML = window.MFG_ICONS.nav(slot.view);
        }
        const lblSpan = btn.querySelector('span');
        if (lblSpan) lblSpan.textContent = slot.label;
      }
      btn.classList.toggle('on', slot.hub === activeHubId);
    });
    _lastSyncedSidebarInd = effInd;
    syncSidebarHubVisibilityDom(activeUser());
  }

  function getInitials(name) {
    return String(name || 'IS').split(/\s+/).filter(Boolean).slice(0, 2).map(p => p[0].toUpperCase()).join('');
  }

  let _demoCompanySandboxActive = false;
  let _demoCompanyLiveSnap = null;
  let _demoCompanySandboxSeed = null;
  let _demoCompanyIndPromise = null;
  let _preloadedDemoBundle = null;
  let _demoCompanyPrevRealCo = 'manufacturing-group';
  const _demoCompanySandboxStores = { customRecords: {}, industryCustomRows: {}, industryRowEdits: {} };

  async function buildStandaloneDemoBundle(coreJson, recJson, indJson) {
    const tmpSeed = { models: {}, records: {}, sentinels: [] };
    if (coreJson) await unpackPackedRecordsIntoSeed(coreJson, false, tmpSeed);
    if (recJson) await unpackPackedRecordsIntoSeed(recJson, false, tmpSeed);
    const demoLive = indJson ? unpackIndustrySeedPayload(indJson, { returnOnly: true, asDemo: true }) : null;
    applyPublicDemoSanitization(tmpSeed, { forceDemoCoIds: true, skipBackup: true });
    return {
      models: tmpSeed.models || {},
      records: tmpSeed.records || {},
      industryLive: demoLive,
      industryLegacyIdMap: (demoLive && demoLive._legacyIdMap) || null
    };
  }

  function attachDemoBundleToActiveSandbox(bundle) {
    if (!bundle) return;
    SEED.models = bundle.models;
    SEED.records = bundle.records;
    SEED.sentinels = [];
    SEED.industryLive = bundle.industryLive;
    SEED._industryLegacyIdMap = bundle.industryLegacyIdMap || null;
    SEED._industryRev = (SEED._industryRev || 0) + 1;
    SEED._coreReady = true;
    SEED._recordsReady = true;
    SEED._demoSpinePresent = false;
    SEED._multiIndustrySpineSeeded = false;
    SEED._liveIndustrySpineOnlyReady = false;
    _demoSanitizedActive = true;
    window.MFG_SEED = SEED;
    if (SEED.industryLive) {
      SEED._industryLiveSpineMergedRev = -1;
      mergeIndustryLiveSpineIntoRecords();
    }
    ensureMultiIndustrySpineSeeded();
    _demoCompanySandboxSeed = {
      models: SEED.models,
      records: SEED.records,
      industryLive: SEED.industryLive,
      industryLegacyIdMap: SEED._industryLegacyIdMap,
      voidedSnap: (_demoCompanySandboxSeed && _demoCompanySandboxSeed.voidedSnap) || {},
      bundleReady: true
    };
    _preloadedDemoBundle = null;
    if (typeof upgradeLegacyIndustryStores === 'function') upgradeLegacyIndustryStores();
    if (typeof applyCustomRecordsToSeed === 'function') applyCustomRecordsToSeed();
    _officialLookupSig = '';
    SEED._canonicalById = null;
    SEED._canonicalByMain = null;
    SEED._origModelMasters = null;
    SEED._customRev = (SEED._customRev || 0) + 1;
    STATE._indCustomRev = (STATE._indCustomRev || 0) + 1;
    if (_hspOpsCache) _hspOpsCache.clear();
    _reOpsSig = '';
    if (typeof _indGlModelCache !== 'undefined' && _indGlModelCache) _indGlModelCache.clear();
    if (typeof invalidateAllSeedCaches === 'function') invalidateAllSeedCaches();
  }

  function ensureDemoCompanySeedLoaded() {
    if (_demoCompanySandboxSeed && _demoCompanySandboxSeed.bundleReady) {
      return Promise.resolve(_demoCompanySandboxSeed.industryLive);
    }
    if (_preloadedDemoBundle) {
      if (_demoCompanySandboxActive) {
        attachDemoBundleToActiveSandbox(_preloadedDemoBundle);
        safeRender();
        return Promise.resolve(_demoCompanySandboxSeed.industryLive);
      }
      return Promise.resolve(_preloadedDemoBundle.industryLive);
    }
    if (_demoCompanyIndPromise) return _demoCompanyIndPromise;
    const demoCoreUrl = (typeof SEED_MANIFEST !== 'undefined' && SEED_MANIFEST && SEED_MANIFEST.demoCore) || './js/seed_demo_core.json';
    const demoRecUrl = (typeof SEED_MANIFEST !== 'undefined' && SEED_MANIFEST && SEED_MANIFEST.demoRecords) || './js/seed_demo_records.json';
    const demoIndUrl = (typeof SEED_MANIFEST !== 'undefined' && SEED_MANIFEST && SEED_MANIFEST.demoIndustries) || './js/seed_demo_industries.json';
    _demoCompanyIndPromise = Promise.all([
      fetchSeedPayloadJson(demoCoreUrl, false).catch(() => null),
      fetchSeedPayloadJson(demoRecUrl, false).catch(() => null),
      fetchSeedPayloadJson(demoIndUrl, false).catch(() => null)
    ])
      .then(async ([coreJson, recJson, indJson]) => {
        if (!coreJson && !recJson && !indJson) return null;
        const bundle = await buildStandaloneDemoBundle(coreJson, recJson, indJson);
        _preloadedDemoBundle = bundle;
        if (_demoCompanySandboxActive) {
          attachDemoBundleToActiveSandbox(bundle);
          safeRender();
        }
        return bundle.industryLive;
      })
      .catch(() => null)
      .finally(() => {
        _demoCompanyIndPromise = null;
      });
    return _demoCompanyIndPromise;
  }
  window.__mfgEnsureDemoCompanyReady = ensureDemoCompanySeedLoaded;

  function syncDemoScopeDataState() {
    if (!SEED) return;
    if (isDemoSandboxSession()) {
      if (SEED._rawIndustryPayload) unpackIndustrySeedPayload(SEED._rawIndustryPayload);
      SEED._liveIndustrySpineOnlyReady = false;
      ensureMultiIndustrySpineSeeded();
      if (_hspOpsCache) _hspOpsCache.clear();
      _reOpsSig = '';
      if (typeof invalidateAllSeedCaches === 'function') invalidateAllSeedCaches();
      return;
    }
    const wantSandbox = STATE.company === DEMO_COMPANY_KEY;
    if (wantSandbox && !_demoCompanySandboxActive) {
      const voidedSnap = {};
      Object.keys(SEED_VOIDED_ARCHIVE).forEach(k => {
        if (SEED_VOIDED_ARCHIVE[k] instanceof Map) voidedSnap[k] = new Map(SEED_VOIDED_ARCHIVE[k]);
      });
      const origArchiveSnap = {};
      Object.keys(SEED_ORIG_ARCHIVE).forEach(k => {
        origArchiveSnap[k] = SEED_ORIG_ARCHIVE[k];
      });
      _demoCompanyLiveSnap = {
        models: SEED.models || {},
        records: SEED.records || {},
        sentinels: Array.isArray(SEED.sentinels) ? JSON.parse(JSON.stringify(SEED.sentinels)) : [],
        voidedSnap,
        origArchiveSnap,
        coreReady: Boolean(SEED._coreReady),
        recordsReady: Boolean(SEED._recordsReady),
        rawIndustryPayload: SEED._rawIndustryPayload || null,
        industryLive: SEED.industryLive || null,
        industryLegacyIdMap: SEED._industryLegacyIdMap || null,
        industryRev: SEED._industryRev || 0,
        industryLiveSpineMergedRev: SEED._industryLiveSpineMergedRev || 0,
        liveIndustrySpineOnlyReady: Boolean(SEED._liveIndustrySpineOnlyReady),
        multiIndustrySpineSeeded: Boolean(SEED._multiIndustrySpineSeeded),
        needsCustomApply: false,
        customRecords: STATE.customRecords,
        industryCustomRows: STATE.industryCustomRows,
        industryRowEdits: STATE.industryRowEdits,
        pendingCloudPush: Boolean(STATE.pendingCloudPush),
        sentinelReviews: JSON.parse(JSON.stringify(STATE.sentinelReviews || {})),
        stepUpAudits: Array.isArray(STATE.stepUpAudits) ? JSON.parse(JSON.stringify(STATE.stepUpAudits)) : []
      };

      Object.keys(SEED_VOIDED_ARCHIVE).forEach(k => { delete SEED_VOIDED_ARCHIVE[k]; });
      Object.keys(SEED_ORIG_ARCHIVE).forEach(k => { delete SEED_ORIG_ARCHIVE[k]; });
      STATE.customRecords = _demoCompanySandboxStores.customRecords || {};
      STATE.industryCustomRows = _demoCompanySandboxStores.industryCustomRows || {};
      STATE.industryRowEdits = _demoCompanySandboxStores.industryRowEdits || {};
      STATE.pendingCloudPush = false;
      _demoCompanySandboxActive = true;
      if (window.MFG_AI_EDGE && typeof window.MFG_AI_EDGE.resetTransientDemoInputs === 'function') {
        window.MFG_AI_EDGE.resetTransientDemoInputs();
      }

      if (_demoCompanySandboxSeed && _demoCompanySandboxSeed.bundleReady) {
        SEED.models = _demoCompanySandboxSeed.models;
        SEED.records = _demoCompanySandboxSeed.records;
        SEED.sentinels = [];
        SEED.industryLive = _demoCompanySandboxSeed.industryLive;
        SEED._industryLegacyIdMap = _demoCompanySandboxSeed.industryLegacyIdMap || null;
        SEED._industryRev = (SEED._industryRev || 0) + 1;
        SEED._coreReady = true;
        SEED._recordsReady = true;
        window.MFG_SEED = SEED;
        Object.keys(_demoCompanySandboxSeed.voidedSnap || {}).forEach(k => {
          SEED_VOIDED_ARCHIVE[k] = new Map(_demoCompanySandboxSeed.voidedSnap[k]);
        });
        SEED._demoSpinePresent = true;
        SEED._multiIndustrySpineSeeded = true;
        SEED._liveIndustrySpineOnlyReady = false;
        _demoSanitizedActive = true;
        if (SEED.industryLive) {
          SEED._industryLiveSpineMergedRev = -1;
          mergeIndustryLiveSpineIntoRecords();
        }
        ensureMultiIndustrySpineSeeded();
        if (typeof applyCustomRecordsToSeed === 'function') applyCustomRecordsToSeed();
      } else if (_preloadedDemoBundle) {
        attachDemoBundleToActiveSandbox(_preloadedDemoBundle);
      } else {
        SEED.models = {};
        SEED.records = {};
        SEED.sentinels = [];
        SEED.industryLive = null;
        SEED._industryLegacyIdMap = null;
        SEED._industryRev = (SEED._industryRev || 0) + 1;
        SEED._demoSpinePresent = false;
        SEED._multiIndustrySpineSeeded = false;
        SEED._liveIndustrySpineOnlyReady = false;
        _demoSanitizedActive = true;
        ensureMultiIndustrySpineSeeded();
        if (typeof applyCustomRecordsToSeed === 'function') applyCustomRecordsToSeed();
        ensureDemoCompanySeedLoaded();
      }
    } else if (!wantSandbox && _demoCompanySandboxActive && _demoCompanyLiveSnap) {
      _demoCompanySandboxStores.customRecords = STATE.customRecords || {};
      _demoCompanySandboxStores.industryCustomRows = STATE.industryCustomRows || {};
      _demoCompanySandboxStores.industryRowEdits = STATE.industryRowEdits || {};
      if (_demoCompanySandboxSeed) {
        const sbxVoid = {};
        Object.keys(SEED_VOIDED_ARCHIVE).forEach(k => {
          if (SEED_VOIDED_ARCHIVE[k] instanceof Map) sbxVoid[k] = new Map(SEED_VOIDED_ARCHIVE[k]);
        });
        _demoCompanySandboxSeed.voidedSnap = sbxVoid;
      }

      SEED.models = _demoCompanyLiveSnap.models;
      SEED.records = _demoCompanyLiveSnap.records;
      SEED.sentinels = _demoCompanyLiveSnap.sentinels;
      SEED._coreReady = Boolean(_demoCompanyLiveSnap.coreReady);
      SEED._recordsReady = Boolean(_demoCompanyLiveSnap.recordsReady);
      SEED._rawIndustryPayload = _demoCompanyLiveSnap.rawIndustryPayload || null;
      SEED._industryLegacyIdMap = _demoCompanyLiveSnap.industryLegacyIdMap || null;
      Object.keys(SEED_VOIDED_ARCHIVE).forEach(k => { delete SEED_VOIDED_ARCHIVE[k]; });
      Object.keys(_demoCompanyLiveSnap.voidedSnap || {}).forEach(k => {
        SEED_VOIDED_ARCHIVE[k] = new Map(_demoCompanyLiveSnap.voidedSnap[k]);
      });
      Object.keys(SEED_ORIG_ARCHIVE).forEach(k => { delete SEED_ORIG_ARCHIVE[k]; });
      Object.keys(_demoCompanyLiveSnap.origArchiveSnap || {}).forEach(k => {
        SEED_ORIG_ARCHIVE[k] = _demoCompanyLiveSnap.origArchiveSnap[k];
      });

      SEED.industryLive = _demoCompanyLiveSnap.industryLive;
      SEED._industryRev = (SEED._industryRev || 0) + 1;
      const needsDeferredLiveMerge = Boolean(SEED.industryLive && _demoCompanyLiveSnap.industryLiveSpineMergedRev === -1);
      const needsCustomApply = Boolean(_demoCompanyLiveSnap.needsCustomApply || needsDeferredLiveMerge);
      SEED._industryLiveSpineMergedRev = needsDeferredLiveMerge
        ? -1
        : ((_demoCompanyLiveSnap.industryLiveSpineMergedRev === _demoCompanyLiveSnap.industryRev)
          ? SEED._industryRev
          : _demoCompanyLiveSnap.industryLiveSpineMergedRev);
      SEED._liveIndustrySpineOnlyReady = _demoCompanyLiveSnap.liveIndustrySpineOnlyReady;
      SEED._multiIndustrySpineSeeded = _demoCompanyLiveSnap.multiIndustrySpineSeeded;
      SEED._demoSpinePresent = false;

      STATE.customRecords = _demoCompanyLiveSnap.customRecords;
      STATE.industryCustomRows = _demoCompanyLiveSnap.industryCustomRows;
      STATE.industryRowEdits = _demoCompanyLiveSnap.industryRowEdits;
      STATE.pendingCloudPush = Boolean(_demoCompanyLiveSnap.pendingCloudPush);
      STATE.sentinelReviews = _demoCompanyLiveSnap.sentinelReviews;
      STATE.stepUpAudits = _demoCompanyLiveSnap.stepUpAudits;

      _demoSanitizedActive = false;
      _demoSanitizeBackup = null;
      _demoCompanySandboxActive = false;
      _demoCompanyLiveSnap = null;

      if (SEED._industryLegacyIdMap && typeof upgradeLegacyIndustryStores === 'function') {
        upgradeLegacyIndustryStores();
      }
      if (needsDeferredLiveMerge) mergeIndustryLiveSpineIntoRecords();
      if (needsCustomApply && typeof applyCustomRecordsToSeed === 'function') applyCustomRecordsToSeed();
      if (SEED._coreReady) {
        const periodSelInit = $('periodSelect');
        const gp = (((SEED.models || {})['manufacturing-group'] || {}).periods) || {};
        if (periodSelInit) Array.from(periodSelInit.options).forEach(o => { const lbl = gp[o.value] && gp[o.value].label; if (lbl) o.textContent = lbl; });
      }
      if (window.MFG_AI_EDGE && typeof window.MFG_AI_EDGE.resetTransientDemoInputs === 'function') {
        window.MFG_AI_EDGE.resetTransientDemoInputs();
      }
    }
    _officialLookupSig = '';
    SEED._canonicalById = null;
    SEED._canonicalByMain = null;
    SEED._origModelMasters = null;
    SEED._customRev = (SEED._customRev || 0) + 1;
    STATE._indCustomRev = (STATE._indCustomRev || 0) + 1;
    if (_hspOpsCache) _hspOpsCache.clear();
    _reOpsSig = '';
    if (typeof _icInteractionsSig !== 'undefined') _icInteractionsSig = '';
    if (window.MFG_CMD_PALETTE && typeof window.MFG_CMD_PALETTE.invalidateCache === 'function') {
      window.MFG_CMD_PALETTE.invalidateCache();
    }
    if (typeof invalidateAllSeedCaches === 'function') invalidateAllSeedCaches();
  }

  function setDemoCompanyIndustry(indId) {
    if (!indId || !INDUSTRY_SIDEBAR_SPEC[indId]) return;
    if (STATE.company && STATE.company !== DEMO_COMPANY_KEY) _demoCompanyPrevRealCo = STATE.company;
    const prevDemo = isDemoScopeActive();
    const prevInd = getActiveIndustry(STATE.company);
    STATE.company = DEMO_COMPANY_KEY;
    STATE.demoCompanyIndustry = indId;
    if (!prevDemo) syncDemoScopeDataState();
    STATE.cfTillScrubDate = '';
    STATE.cfTillScrubKey = '';
    STATE.cfFocusDate = '';
    STATE.cfFocusDateFromScrub = false;
    clearCfScrubChipState();
    STATE.shown = {};
    STATE.pbiTablePage = {};
    let nextView = resolveIndustryCompatibleView(STATE.view, indId);
    const nextHub = VIEW_TO_HUB[nextView] || nextView;
    if (canViewHub(nextHub, activeUser()) && !canViewView(nextView, activeUser())) {
      nextView = resolveHubView(nextHub, activeUser());
    }
    if (!canViewView(nextView, activeUser())) {
      nextView = defaultViewFor(activeUser());
    }
    if (prevInd !== indId) {
      const defStmtByInd = {
        'Manufacturing': '01',
        'Holding & Treasury': '23',
        'Hospitality & Resorts': '24',
        'Automotive & Heavy Trading': '25',
        'Real Estate & Property': '26',
        'Insurance & Brokerage': '27'
      };
      STATE.activeStatement = defStmtByInd[indId] || '01';
    }
    if (nextView !== STATE.view || prevInd !== indId) {
      STATE.view = nextView;
      STATE.search = '';
      STATE.chipFilter = 'all';
      STATE._resetWorkspaceScroll = true;
      const ws = $('workspace');
      if (ws && ws.scrollTop !== 0) ws.scrollTop = 0;
    }
    syncIndustrySidebarDom(indId);
    _companySwitchUiSig = '';
    syncCompanySwitchUi();
    renderApp();
  }
  window.__mfgSetDemoCompanyIndustry = setDemoCompanyIndustry;

  // True only between a pick that left the company switcher open and the moment that same popover closes
  // or reopens. It lets "industry tab, then company" count as one Back step without ever merging two
  // separate visits to the switcher.
  let _coPickOpenSession = false;
  function selectCompanyScope(coKey, closePopover = true, opts = null) {
    if (!coKey) return;
    if (STATE.company && STATE.company !== DEMO_COMPANY_KEY && coKey === DEMO_COMPANY_KEY) _demoCompanyPrevRealCo = STATE.company;
    const prevDemo = isDemoScopeActive();
    const prevInd = getActiveIndustry(STATE.company);
    const nextInd = getActiveIndustry(coKey);
    const prevView = STATE.view;
    const prevCompany = STATE.company;
    const fromHistory = Boolean(opts && opts.fromHistory);
    STATE.company = coKey;
    const nextDemo = isDemoScopeActive();
    if (prevDemo !== nextDemo) {
      syncDemoScopeDataState();
    }
    if (prevCompany !== coKey) {
      STATE.cfTillScrubDate = '';
      STATE.cfTillScrubKey = '';
      STATE.cfFocusDate = '';
      STATE.cfFocusDateFromScrub = false;
      clearCfScrubChipState();
    }
    STATE.shown = {};
    STATE.pbiTablePage = {};
    let nextView = resolveIndustryCompatibleView(STATE.view, nextInd);
    const nextHub = VIEW_TO_HUB[nextView] || nextView;
    if (canViewHub(nextHub, activeUser()) && !canViewView(nextView, activeUser())) {
      nextView = resolveHubView(nextHub, activeUser());
    }
    if (!canViewView(nextView, activeUser())) {
      nextView = defaultViewFor(activeUser());
    }
    if (prevInd !== nextInd) {
      const defStmtByInd = {
        'Manufacturing': '01',
        'Holding & Treasury': '23',
        'Hospitality & Resorts': '24',
        'Automotive & Heavy Trading': '25',
        'Real Estate & Property': '26',
        'Insurance & Brokerage': '27'
      };
      STATE.activeStatement = defStmtByInd[nextInd] || '01';
    }
    if (nextView !== STATE.view || prevInd !== nextInd) {
      STATE.view = nextView;
      STATE.search = '';
      STATE.chipFilter = 'all';
      STATE._resetWorkspaceScroll = true;
      _preModalWorkspaceScrollSnap = null;
      _preModalWorkspaceScope = '';
      const ws = $('workspace');
      if (ws && ws.scrollTop !== 0) ws.scrollTop = 0;
    }
    if (STATE.authed && VIEW_TITLES[STATE.view]) {
      const targetHash = '#' + STATE.view;
      if (!fromHistory && prevCompany !== coKey) {
        // A company switch is its own history entry, so browser Back returns to the previous company.
        // Several picks made while the switcher stays open (industry tab, then company) collapse into one entry.
        const popNow = $('companySwitchPopover');
        const curState = history.state;
        const collapse = Boolean(_coPickOpenSession && curState && curState.coPick && popNow && !popNow.hidden);
        const nextState = { view: STATE.view, company: STATE.company };
        if (!closePopover) nextState.coPick = true;
        try {
          if (collapse) {
            history.replaceState(nextState, '', targetHash);
          } else {
            history.replaceState({ view: prevView, company: prevCompany }, '', location.href);
            history.pushState(nextState, '', targetHash);
          }
        } catch (_) {}
        _coPickOpenSession = !closePopover;
        if (location.hash !== targetHash) {
          try { location.hash = targetHash; } catch (__) {}
        }
      } else if (location.hash !== targetHash || STATE.view !== prevView || fromHistory) {
        try {
          history.replaceState({ view: STATE.view, company: STATE.company }, '', targetHash);
        } catch (_) {}
        if (location.hash !== targetHash) {
          try { location.hash = targetHash; } catch (__) {}
        }
      }
    }
    syncIndustrySidebarDom(nextInd);
    saveFilterState();
    if (closePopover) {
      const switchEl = $('companySwitch');
      const popEl = $('companySwitchPopover');
      const trigEl = $('companySwitchTrigger');
      if (switchEl) switchEl.classList.remove('open');
      if (popEl) popEl.hidden = true;
      if (trigEl) trigEl.setAttribute('aria-expanded', 'false');
    }
    renderApp();
  }

  let _companySwitchUiSig = '';
  function syncCompanySwitchUi() {
    const switchEl = $('companySwitch');
    if (!switchEl) return;
    const user = activeUser();
    const allowedCos = getAllowedCompanyKeys(user);
    const allowedNames = allowedCompanyNames(user);
    const catalog = getCompanyCatalog();
    const searchInpEarly = $('companySwitchSearch');
    const qEarly = searchInpEarly ? String(searchInpEarly.value || '').trim().toLowerCase() : '';
    const uiSig = `${(user && user.id) || ''}|${allowedCos.join(',')}|${allowedNames.join(',')}|${catalog.length}|${_companyCatalogSig}|${STATE.company}|${STATE.demoCompanyIndustry || ''}|${STATE.companySwitchIndFilter || 'all'}|${qEarly}|${Boolean(STATE.demoVisitor)}|${isOfficialScopeActive(user)}|${Boolean(STATE.enterpriseScalePreview)}`;
    if (_companySwitchUiSig === uiSig && switchEl.querySelector('.entity-btn')) return;
    _companySwitchUiSig = uiSig;
    const allowedNameSet = new Set(allowedNames.map(n => n.toLowerCase()));
    const indGroups = getIndustryGroups(catalog);
    const coFreqSwitch = (_FREQ_IDX && _FREQ_IDX.company) ? _FREQ_IDX.company : null;
    const listEl = $('companySwitchList') || switchEl;

    // Allowed industries for this user — ranked strictly by summed operational frequency of permitted companies
    const allowedIndGroups = indGroups.map(g => {
      const permittedCos = g.companies.filter(c => allowedNameSet.has(c.name.toLowerCase()));
      const permittedFreq = (coFreqSwitch && coFreqSwitch.size)
        ? permittedCos.reduce((s, c) => s + (coFreqSwitch.get(norm(c.name)) || 0), 0)
        : (g.freq || 0);
      return { ...g, permittedCos, permittedFreq };
    }).filter(g => g.permittedCos.length > 0);
    if (coFreqSwitch && coFreqSwitch.size) {
      allowedIndGroups.sort((a, b) => (b.permittedFreq || 0) - (a.permittedFreq || 0));
    }
    const orderedSwitchGroups = allowedIndGroups.concat(indGroups.filter(g => !allowedIndGroups.some(ag => ag.id === g.id)));

    // Order each industry's consolidated group row directly above its member companies (preserving MFG_FREQ industry & company rank)
    const desiredKeys = [];
    orderedSwitchGroups.forEach(g => {
      if (g.id === 'Manufacturing' && allowedCos.includes('manufacturing-group')) {
        desiredKeys.push('manufacturing-group');
      }
      const indKey = `industry:${g.id}`;
      if (indGroups.length >= 2 && allowedCos.includes(indKey) && !desiredKeys.includes(indKey)) {
        desiredKeys.push(indKey);
      }
      g.companies.forEach(c => {
        if (!desiredKeys.includes(c.key)) desiredKeys.push(c.key);
      });
    });
    if (!desiredKeys.includes('manufacturing-group')) desiredKeys.unshift('manufacturing-group');
    catalog.forEach(c => { if (!desiredKeys.includes(c.key)) desiredKeys.push(c.key); });
    allowedCos.forEach(k => { if (!desiredKeys.includes(k)) desiredKeys.push(k); });

    desiredKeys.forEach(coKey => {
      let btn = switchEl.querySelector(`.entity-btn[data-company="${coKey}"]`);
      if (!btn) {
        btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'entity-btn';
        btn.setAttribute('data-company', coKey);
        if (coKey === DEMO_COMPANY_KEY) {
          btn.textContent = 'Demo Company (Showcase Sandbox)';
        } else if (coKey.startsWith('industry:')) {
          btn.textContent = `All ${coKey.slice(9)}`;
        } else {
          btn.textContent = COMPANY_BU_MATCH[coKey] || coKey;
        }
        btn.addEventListener('click', e => {
          e.stopPropagation();
          selectCompanyScope(coKey, true);
        });
      }
      btn.classList.toggle('is-group-scope', coKey === 'manufacturing-group' || coKey === DEMO_COMPANY_KEY || coKey.startsWith('industry:'));
      listEl.appendChild(btn);
    });

    const allowedIndCount = Math.max(1, allowedIndGroups.length);
    const firstAllowedInd = allowedIndGroups[0] ? allowedIndGroups[0].id : 'Manufacturing';
    const liveInd = getActiveIndustry(STATE.company);

    if (STATE.companySwitchIndFilter !== 'all' && !allowedIndGroups.some(g => g.id === STATE.companySwitchIndFilter)) {
      STATE.companySwitchIndFilter = 'all';
    }

    const indHeadEl = $('companySwitchIndHead');
    if (indHeadEl) {
      indHeadEl.textContent = `Industries (${allowedIndCount})`;
    }

    // Populate Left Column: Industry Tabs (#companySwitchIndustryList)
    const indListEl = $('companySwitchIndustryList');
    if (indListEl) {
      const isExactIndMatch = g => {
        const ql = qEarly;
        if (!ql) return false;
        const idL = String(g.id || '').toLowerCase();
        const lblL = String(g.label || '').toLowerCase();
        const codeL = String(g.code || '').toLowerCase();
        const shortL = lblL.split(/\s*&\s*/)[0].trim();
        return idL === ql || lblL === ql || codeL === ql || shortL === ql;
      };
      const displayIndGroups = qEarly
        ? allowedIndGroups.filter(isExactIndMatch).concat(allowedIndGroups.filter(g => !isExactIndMatch(g)))
        : allowedIndGroups;
      const indTabsHtml = [
        `<button type="button" class="ep-ind-tab ${STATE.companySwitchIndFilter === 'all' ? 'active' : ''}" data-ep-ind="all" data-ui-tip="Show all ${allowedNames.length} permitted companies across ${allowedIndCount} industries">
          <span class="ep-ind-tab-name">All Industries</span>
          <em class="ep-ind-tab-cnt">${allowedNames.length}</em>
        </button>`
      ].concat(displayIndGroups.map(g => `
        <button type="button" class="ep-ind-tab ${STATE.companySwitchIndFilter === g.id ? 'active' : ''}" data-ep-ind="${esc(g.id)}" data-ui-tip="${esc(g.label)} (${g.permittedCos.length} permitted${g.id === liveInd ? ' · Active' : ''})">
          <span class="ep-ind-tab-name">${g.id === liveInd ? '<span class="ep-ind-live-dot" aria-hidden="true"></span>' : ''}${esc(g.label)}</span>
          <em class="ep-ind-tab-cnt">${g.permittedCos.length}</em>
        </button>
      `)).join('');
      indListEl.innerHTML = indTabsHtml;
      indListEl.querySelectorAll('[data-ep-ind]').forEach(tabBtn => {
        tabBtn.addEventListener('click', e => {
          e.stopPropagation();
          const pickedInd = tabBtn.getAttribute('data-ep-ind') || 'all';
          STATE.companySwitchIndFilter = pickedInd;
          if (searchInpEarly && searchInpEarly.value) searchInpEarly.value = '';
          if (pickedInd === 'all') {
            syncCompanySwitchUi();
            return;
          }
          const grp = allowedIndGroups.find(g => g.id === pickedInd);
          const targetKey = pickedInd === 'Manufacturing'
            ? (allowedCos.includes('manufacturing-group') ? 'manufacturing-group' : (grp && grp.permittedCos[0] ? grp.permittedCos[0].key : 'wtc'))
            : (grp && grp.permittedCos.length === 1 ? grp.permittedCos[0].key : `industry:${pickedInd}`);
          if (getActiveIndustry(STATE.company) !== pickedInd || STATE.company !== targetKey || resolveIndustryCompatibleView(STATE.view, pickedInd) !== STATE.view) {
            selectCompanyScope(targetKey, false);
            return;
          }
          syncCompanySwitchUi();
        });
      });
    }

    const searchInp = $('companySwitchSearch');
    const q = searchInp ? String(searchInp.value || '').trim().toLowerCase() : '';
    const indFilter = q ? 'all' : (STATE.companySwitchIndFilter || 'all');

    const mfgAllowedCount = STATE.enterpriseScalePreview
      ? allowedNames.length
      : allowedNames.filter(n => !/^(bdeir\s*holding|blanca|la\s*una|palms|voile|platinum|korri\s*auto|shacman|properties|4235\s*company(\s*s\.?a\.?l\.?)?|insurance\s*company)$/i.test(n)).length;
    const mfgCatalogCount = STATE.enterpriseScalePreview
      ? catalog.length
      : catalog.filter(c => !['bdeirholding', 'blanca', 'launa', 'palms', 'voile', 'platinum', 'korriauto', 'shacman', 'properties', '4235company', 'insurance'].includes(c.key)).length;

    let visibleBtnCount = 0;
    const exactBtns = [];
    const freqBtns = [];
    switchEl.querySelectorAll('.entity-btn').forEach(btn => {
      btn.classList.remove('kbd-focus');
      const key = btn.getAttribute('data-company') || '';
      const isAllowed = allowedCos.includes(key);
      if (key === 'manufacturing-group') {
        btn.textContent = mfgAllowedCount >= mfgCatalogCount
          ? `All Group (${mfgAllowedCount})`
          : `All Assigned (${mfgAllowedCount})`;
        btn.setAttribute('data-ind', 'all');
        btn.setAttribute('data-ind-tag', STATE.enterpriseScalePreview && allowedIndCount > 1 ? `${allowedIndCount} Ind` : firstAllowedInd);
        btn.setAttribute('data-co-search', `all group assigned consolidated manufacturing ${allowedNames.join(' ').toLowerCase()}`);
      } else if (key === DEMO_COMPANY_KEY) {
        btn.textContent = 'Demo Company (Showcase Sandbox)';
        btn.setAttribute('data-ind', 'all');
        btn.setAttribute('data-ind-tag', '6 Verticals');
        btn.setAttribute('data-co-search', 'demo company showcase sandbox sample all 6 industries verticals');
      } else if (key.startsWith('industry:')) {
        const indName = key.slice(9);
        const grp = allowedIndGroups.find(g => g.id === indName);
        const cnt = grp ? grp.permittedCos.length : 0;
        btn.textContent = `All ${indName} (${cnt})`;
        btn.setAttribute('data-ind', indName);
        btn.setAttribute('data-ind-tag', `All · ${cnt}`);
        btn.setAttribute('data-co-search', `all ${indName.toLowerCase()} industry consolidated`);
      } else {
        const coMeta = catalog.find(c => c.key === key);
        const indName = (coMeta && coMeta.industry) || COMPANY_INDUSTRY_BY_KEY[key] || 'Manufacturing';
        btn.setAttribute('data-ind', indName);
        btn.setAttribute('data-ind-tag', indName);
        btn.setAttribute('data-co-search', ((coMeta ? `${coMeta.name} ${coMeta.label} ${coMeta.sector} ${indName} ${coMeta.key}` : `${btn.textContent} ${key}`)).toLowerCase());
      }

      if (!isAllowed) {
        btn.hidden = true;
      } else {
        const btnInd = btn.getAttribute('data-ind') || 'Manufacturing';
        const hay = btn.getAttribute('data-co-search') || btn.textContent.toLowerCase();
        let matchInd = (indFilter === 'all' || key === DEMO_COMPANY_KEY) ? true : (key === 'manufacturing-group' ? indFilter === 'Manufacturing' : btnInd === indFilter);
        if (key === 'industry:Manufacturing' && allowedCos.includes('manufacturing-group') && !STATE.enterpriseScalePreview && STATE.company !== key) {
          matchInd = false;
        } else if (key.startsWith('industry:') && !STATE.enterpriseScalePreview && STATE.company !== key) {
          const grp = allowedIndGroups.find(g => g.id === key.slice(9));
          if (!grp || grp.permittedCos.length < 2) matchInd = false;
        }
        const matchQ = !q || hay.includes(q);
        btn.hidden = !(matchInd && matchQ);
        if (!btn.hidden) {
          visibleBtnCount += 1;
          if (q) {
            const labelNorm = btn.textContent.trim().toLowerCase();
            if (labelNorm === q || key.toLowerCase() === q) exactBtns.push(btn);
            else freqBtns.push(btn);
          }
        }
      }
      btn.classList.toggle('active', key === STATE.company);
    });

    if (q && (exactBtns.length || freqBtns.length)) {
      if (freqBtns.length > 1 && coFreqSwitch && coFreqSwitch.size) {
        const btnFreqScore = btn => {
          const bk = btn.getAttribute('data-company') || '';
          if (bk === 'manufacturing-group') {
            const mg = allowedIndGroups.find(g => g.id === 'Manufacturing');
            return mg ? (mg.permittedFreq || 0) : 0;
          }
          if (bk.startsWith('industry:')) {
            const ig = allowedIndGroups.find(g => g.id === bk.slice(9));
            return ig ? (ig.permittedFreq || 0) : 0;
          }
          const coName = COMPANY_BU_MATCH[bk] || bk;
          return coFreqSwitch.get(norm(coName)) || 0;
        };
        freqBtns.sort((a, b) => btnFreqScore(b) - btnFreqScore(a));
      }
      exactBtns.concat(freqBtns).forEach(btn => listEl.appendChild(btn));
    }

    // Update Trigger Box 2-Segment Labels (IND + CO)
    const indTextEl = $('companySwitchIndText');
    const coTextEl = $('companySwitchCoText');
    let trigInd = firstAllowedInd;
    let trigCo = `All Group (${mfgAllowedCount})`;
    if (STATE.company === 'manufacturing-group') {
      trigInd = (STATE.enterpriseScalePreview && allowedIndCount > 1) ? `All (${allowedIndCount} Ind)` : firstAllowedInd;
      trigCo = mfgAllowedCount >= mfgCatalogCount
        ? `All Group (${mfgAllowedCount})`
        : `All Assigned (${mfgAllowedCount})`;
    } else if (STATE.company === DEMO_COMPANY_KEY) {
      trigInd = getActiveIndustry(DEMO_COMPANY_KEY);
      trigCo = 'Demo Company';
    } else if (String(STATE.company || '').startsWith('industry:')) {
      const indName = String(STATE.company).slice(9);
      const grp = allowedIndGroups.find(g => g.id === indName);
      const cnt = grp ? grp.permittedCos.length : 0;
      trigInd = indName;
      trigCo = `All ${indName === 'Real Estate & Property' ? 'Real Estate' : indName.split(' ')[0]} (${cnt})`;
    } else {
      const coMeta = catalog.find(c => c.key === STATE.company);
      const rawInd = (coMeta && coMeta.industry) || COMPANY_INDUSTRY_BY_KEY[STATE.company] || 'Manufacturing';
      trigInd = rawInd;
      trigCo = (coMeta && coMeta.name) || COMPANY_BU_MATCH[STATE.company] || STATE.company;
    }
    if (indTextEl) { indTextEl.textContent = trigInd; indTextEl.setAttribute('data-ui-tip', `Click to browse all ${allowedIndCount} industries`); }
    if (coTextEl) { coTextEl.textContent = trigCo; coTextEl.setAttribute('data-ui-tip', `Click to switch companies in ${liveInd}`); }

    // Populate Quick Domain Hubs deck inside right column when a specific industry is selected
    if (listEl && listEl.parentElement) {
      let quickDeckEl = $('companySwitchQuickHubs');
      if (!quickDeckEl) {
        quickDeckEl = document.createElement('div');
        quickDeckEl.id = 'companySwitchQuickHubs';
        quickDeckEl.className = 'ep-co-quick-deck';
        listEl.parentElement.appendChild(quickDeckEl);
      }
      const quickHubsByInd = {
        'Manufacturing': [
          { view: 'overview', label: 'Overview' },
          { view: 'sales', label: 'Sales & Dispatch' },
          { view: 'raw', label: 'Quarry & Haulage' },
          { view: 'fleet', label: 'Fleet & Diesel' },
          { view: 'kiosks', label: 'Plant Kiosks' }
        ],
        'Holding & Treasury': [
          { view: 'overview', label: 'Overview' },
          { view: 'hld_consolidation', label: 'Group P&L' },
          { view: 'hld_interactions', label: 'Intercompany Hub' },
          { view: 'hld_partners', label: 'Partner Capital' },
          { view: 'hld_extended', label: 'Extended Ledger' },
          { view: 'hld_loans', label: 'Loans & Treasury' }
        ],
        'Hospitality & Resorts': [
          { view: 'overview', label: 'Overview' },
          { view: 'hsp_revenue', label: 'Venue Revenue' },
          { view: 'hsp_pos', label: 'POS & Shift Close' },
          { view: 'hsp_memberships', label: 'Memberships' },
          { view: 'hsp_stock', label: 'Cellar & Kitchen' }
        ],
        'Automotive & Heavy Trading': [
          { view: 'overview', label: 'Overview' },
          { view: 'trd_sales', label: 'Sales Invoices' },
          { view: 'trd_trucks', label: 'Showroom VINs' },
          { view: 'trd_stock', label: '5-Whse Parts' },
          { view: 'trd_purchases', label: 'Import Files' }
        ],
        'Real Estate & Property': [
          { view: 'overview', label: 'Overview' },
          { view: 're_properties', label: 'Properties & Map' },
          { view: 're_leases', label: 'Active Leases' },
          { view: 're_invoicing', label: 'Rent Invoices' },
          { view: 're_sales', label: 'Deed Sales' }
        ],
        'Insurance & Brokerage': [
          { view: 'overview', label: 'Overview' },
          { view: 'ins_policies', label: 'Policies & Discounts' },
          { view: 'ins_renewals', label: 'Renewal Queue' },
          { view: 'ins_billing', label: 'Client Billing' },
          { view: 'ins_statements', label: 'Carrier Recon' },
          { view: 'ins_claims', label: 'FNOL Claims' }
        ]
      };
      const deckInd = indFilter !== 'all' ? indFilter : (STATE.company !== 'manufacturing-group' ? liveInd : null);
      const deckHubs = (!q && deckInd) ? (quickHubsByInd[deckInd] || null) : null;
      if (deckHubs && deckHubs.length) {
        const grp = allowedIndGroups.find(g => g.id === deckInd);
        const targetKey = deckInd === 'Manufacturing'
          ? (allowedCos.includes('manufacturing-group') ? 'manufacturing-group' : (grp && grp.permittedCos[0] ? grp.permittedCos[0].key : 'wtc'))
          : (grp && grp.permittedCos.length === 1 ? grp.permittedCos[0].key : `industry:${deckInd}`);
        quickDeckEl.hidden = false;
        quickDeckEl.innerHTML = `
          <div class="ep-co-quick-title">Jump Directly to ${esc(deckInd)} Hubs</div>
          <div class="ep-co-quick-chips">
            ${deckHubs.map(h => `<button type="button" class="ep-co-quick-chip" data-ep-quick-view="${esc(h.view)}" data-ep-quick-co="${esc(targetKey)}">${esc(h.label)}</button>`).join('')}
          </div>
        `;
        quickDeckEl.querySelectorAll('[data-ep-quick-view]').forEach(chip => {
          chip.addEventListener('click', ev => {
            ev.stopPropagation();
            const qView = chip.getAttribute('data-ep-quick-view') || 'overview';
            const qCo = chip.getAttribute('data-ep-quick-co') || STATE.company;
            if (getActiveIndustry(STATE.company) !== deckInd) {
              selectCompanyScope(qCo, true);
            } else {
              switchEl.classList.remove('open');
              const p = $('companySwitchPopover');
              if (p) p.hidden = true;
              const tb = $('companySwitchTrigger');
              if (tb) tb.setAttribute('aria-expanded', 'false');
            }
            setView(qView);
          });
        });
      } else {
        quickDeckEl.hidden = true;
        quickDeckEl.innerHTML = '';
      }
    }

    const popElAlign = $('companySwitchPopover');
    if (popElAlign && !popElAlign.hidden) {
      const rect = switchEl.getBoundingClientRect();
      popElAlign.classList.toggle('align-right', rect.left + 585 > window.innerWidth - 12);
    }

    const coHeadEl = $('companySwitchCoHead');
    if (coHeadEl) {
      coHeadEl.textContent = q
        ? `Matching Companies (${visibleBtnCount})`
        : (indFilter === 'all'
          ? `Operating Companies (${allowedNames.length} Permitted)`
          : `${indFilter} (${(allowedIndGroups.find(g => g.id === indFilter) || { permittedCos: [] }).permittedCos.length} Permitted)`);
    }
    const footEl = $('companySwitchFootStatus');
    if (footEl) {
      footEl.textContent = q
        ? `Showing ${visibleBtnCount} match${visibleBtnCount === 1 ? '' : 'es'} · Press Enter to select`
        : `Active: ${trigInd} · ${trigCo} (${allowedIndCount} ${allowedIndCount === 1 ? 'Industry' : 'Industries'} · ${allowedNames.length} ${allowedNames.length === 1 ? 'Company' : 'Companies'} RLS)`;
    }
    const demoBtn = $('companySwitchScalePreviewBtn');
    if (demoBtn) {
      const isDemoSession = Boolean(STATE.demoVisitor || IS_DEMO || PARAMS.get('demo') === '1' || PARAMS.get('autologin') === '1' || PARAMS.get('scale') === '1' || STATE.enterpriseScalePreview);
      demoBtn.hidden = !(isOwner(user) && isDemoSession);
      demoBtn.classList.toggle('active', !!STATE.enterpriseScalePreview);
      demoBtn.innerHTML = STATE.enterpriseScalePreview
        ? `${ic('check_circle')} 10 Ind × 150 Co Preview (Reset to 14)`
        : `${ic('bolt')} Preview 10 Ind × 150 Co`;
    }
    const offBtn = $('officialScopeToggleBtn');
    if (offBtn) {
      const showOffToggle = isOwner(user) && !STATE.demoVisitor && getUserBookScope(user) !== 'official';
      const offOn = isOfficialScopeActive(user);
      offBtn.hidden = !showOffToggle;
      offBtn.classList.toggle('active', offOn);
      offBtn.innerHTML = offOn ? `${ic('shield')} Official Books (11% VAT)` : `${ic('shield')} All Books`;
    }
  }

  function wireCompanySwitch() {
    const switchEl = $('companySwitch');
    if (!switchEl || switchEl.dataset.pickerWired === '1') return;
    switchEl.dataset.pickerWired = '1';
    const trigBtn = $('companySwitchTrigger');
    const popEl = $('companySwitchPopover');
    const searchEl = $('companySwitchSearch');
    const allBtn = $('companySwitchSelectAllBtn');
    const demoBtn = $('companySwitchScalePreviewBtn');
    const offBtn = $('officialScopeToggleBtn');
    const doneBtn = $('companySwitchDoneBtn');

    const setOpen = (open) => {
      _coPickOpenSession = false;
      switchEl.classList.toggle('open', !!open);
      if (popEl) popEl.hidden = !open;
      if (trigBtn) trigBtn.setAttribute('aria-expanded', String(!!open));
      if (open) {
        syncCompanySwitchUi();
        if (searchEl) setTimeout(() => { try { searchEl.focus({ preventScroll: true }); } catch (_) {} }, 20);
      } else {
        if (searchEl && searchEl.value) {
          searchEl.value = '';
          syncCompanySwitchUi();
        }
        if (STATE.renderPending) renderApp();
      }
    };

    if (trigBtn) {
      trigBtn.addEventListener('click', e => {
        e.stopPropagation();
        const willOpen = popEl ? popEl.hidden : !switchEl.classList.contains('open');
        if (willOpen) {
          const clickedCoSeg = e.target && e.target.closest && e.target.closest('.ep-seg-co');
          const clickedIndSeg = e.target && e.target.closest && e.target.closest('.ep-seg-ind');
          if (clickedCoSeg) {
            STATE.companySwitchIndFilter = getActiveIndustry(STATE.company);
          } else if (clickedIndSeg) {
            STATE.companySwitchIndFilter = 'all';
          }
        }
        setOpen(willOpen);
      });
    }
    if (doneBtn) {
      doneBtn.addEventListener('click', e => {
        e.stopPropagation();
        setOpen(false);
      });
    }
    if (searchEl) {
      searchEl.addEventListener('input', () => {
        syncCompanySwitchUi();
      });
      searchEl.addEventListener('keydown', e => {
        const visibleBtns = Array.from(switchEl.querySelectorAll('.entity-btn:not([hidden])'));
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
          if (!visibleBtns.length) return;
          e.preventDefault();
          const curIdx = visibleBtns.findIndex(b => b.classList.contains('kbd-focus'));
          visibleBtns.forEach(b => b.classList.remove('kbd-focus'));
          const nextIdx = e.key === 'ArrowDown'
            ? (curIdx < visibleBtns.length - 1 ? curIdx + 1 : 0)
            : (curIdx > 0 ? curIdx - 1 : visibleBtns.length - 1);
          const targetBtn = visibleBtns[nextIdx];
          if (targetBtn) {
            targetBtn.classList.add('kbd-focus');
            try { targetBtn.scrollIntoView({ block: 'nearest' }); } catch (_) {}
          }
        } else if (e.key === 'Enter') {
          e.preventDefault();
          const focusedBtn = switchEl.querySelector('.entity-btn.kbd-focus:not([hidden])') || visibleBtns[0];
          if (focusedBtn) {
            selectCompanyScope(focusedBtn.getAttribute('data-company'), true);
          }
        } else if (e.key === 'Escape') {
          e.preventDefault();
          if (searchEl.value) {
            searchEl.value = '';
            syncCompanySwitchUi();
          } else {
            setOpen(false);
          }
        }
      });
    }
    if (allBtn) {
      allBtn.addEventListener('click', e => {
        e.stopPropagation();
        STATE.companySwitchIndFilter = 'all';
        if (searchEl) searchEl.value = '';
        const allowedCos = getAllowedCompanyKeys(activeUser());
        selectCompanyScope(allowedCos[0] || 'manufacturing-group', true);
      });
    }
    if (demoBtn) {
      demoBtn.addEventListener('click', e => {
        e.stopPropagation();
        if (!isOwner() || !(STATE.demoVisitor || IS_DEMO || PARAMS.get('demo') === '1' || PARAMS.get('autologin') === '1' || PARAMS.get('scale') === '1' || STATE.enterpriseScalePreview)) return;
        STATE.enterpriseScalePreview = !STATE.enterpriseScalePreview;
        STATE.enterprisePreviewCompanies = STATE.enterpriseScalePreview ? buildEnterprisePreviewCatalog() : [];
        STATE.companySwitchIndFilter = 'all';
        applyUserRlsAndPermissions();
        if (STATE.view === 'users') {
          updateSeatEditorDom();
        }
        toast(STATE.enterpriseScalePreview
          ? '⚡ Enterprise Scale Preview active: 10 Industries × 15 Companies (150 Companies) loaded'
          : 'Restored live BHFIRMS multi-industry catalog (6 Industries · 14 Companies)');
      });
    }
    if (offBtn) {
      offBtn.addEventListener('click', e => {
        e.stopPropagation();
        if (!isOwner() || STATE.demoVisitor || getUserBookScope() === 'official') return;
        STATE.officialBookScope = !STATE.officialBookScope;
        STATE.shown = {};
        STATE.pbiTablePage = {};
        applyUserRlsAndPermissions();
        renderApp();
        toast(STATE.officialBookScope
          ? 'Official Books active: scoped strictly to 11% VAT-invoiced activity'
          : 'All Books active: showing complete operational ledger');
      });
    }
    switchEl.querySelectorAll('.entity-btn').forEach(btn => {
      btn.addEventListener('click', e => {
        e.stopPropagation();
        selectCompanyScope(btn.getAttribute('data-company'), true);
      });
    });
    document.addEventListener('mousedown', e => {
      if (switchEl.classList.contains('open') && (!e.target || !e.target.closest('#companySwitch'))) {
        setOpen(false);
      }
    });
    window.addEventListener('resize', () => {
      if (popEl && !popEl.hidden) {
        const rect = switchEl.getBoundingClientRect();
        popEl.classList.toggle('align-right', rect.left + 585 > window.innerWidth - 12);
      }
    });
  }

  function applyUserRlsAndPermissions() {
    const user = activeUser();
    if (STATE._lastRlsUserId !== String(user && user.id || '')) {
      STATE._lastRlsUserId = String(user && user.id || '');
      STATE.companySwitchIndFilter = 'all';
      const searchInp = $('companySwitchSearch');
      if (searchInp) searchInp.value = '';
    }
    const allowedCos = getAllowedCompanyKeys(user);
    const allowedNames = allowedCompanyNames(user);
    const catalog = getCompanyCatalog();
    STATE.allowedCompanyNames = allowedNames;
    STATE._officialScopeActive = isOfficialScopeActive(user);
    STATE._canSeeTaxBreakdown = canSeeTaxBreakdown(user);
    STATE.isOfficialRecord = isOfficialRecord;
    STATE.canAccessRdlReport = r => canAccessRdlReport(r, user);

    const isPermittedIndScope = String(STATE.company || '').startsWith('industry:') && allowedNames.some(n => {
      const hit = catalog.find(c => c.name.toLowerCase() === n.toLowerCase());
      return hit && hit.industry === String(STATE.company).slice(9);
    });
    if (!allowedCos.includes(STATE.company) && !isPermittedIndScope) STATE.company = allowedCos[0];
    const activeIndNow = getActiveIndustry(STATE.company);
    let compatViewNow = resolveIndustryCompatibleView(STATE.view, activeIndNow);
    if (!canViewView(compatViewNow, user)) {
      const curHubNow = VIEW_TO_HUB[compatViewNow];
      if (curHubNow && canViewHub(curHubNow, user)) {
        compatViewNow = resolveHubView(curHubNow, user);
      } else {
        compatViewNow = resolveIndustryCompatibleView(defaultViewFor(user), activeIndNow);
      }
    }
    if (compatViewNow !== STATE.view) {
      STATE.view = compatViewNow;
      STATE.search = '';
      STATE.chipFilter = 'all';
      STATE.shown = {};
      STATE._resetWorkspaceScroll = true;
      _preModalWorkspaceScrollSnap = null;
      _preModalWorkspaceScope = '';
      if (STATE.authed && VIEW_TITLES[STATE.view]) {
        const targetHash = '#' + STATE.view;
        if (location.hash !== targetHash) {
          try {
            history.replaceState({ view: STATE.view, company: STATE.company }, '', targetHash);
          } catch (_) {}
          if (location.hash !== targetHash) {
            try { location.hash = targetHash; } catch (__) {}
          }
        }
      }
    }
    syncIndustrySidebarDom(activeIndNow);
    syncCompanySwitchUi();

    const mfgAllowed = STATE.enterpriseScalePreview ? allowedNames : allowedNames.filter(n => !/^(bdeir\s*holding|blanca|la\s*una|palms|voile|platinum|korri\s*auto|shacman|properties|4235\s*company(\s*s\.?a\.?l\.?)?|insurance\s*company)$/i.test(n));
    const mfgCatLen = STATE.enterpriseScalePreview ? catalog.length : catalog.filter(c => !['bdeirholding', 'blanca', 'launa', 'palms', 'voile', 'platinum', 'korriauto', 'shacman', 'properties', '4235company', 'insurance'].includes(c.key)).length;
    COMPANY_LABELS['manufacturing-group'] = mfgAllowed.length >= mfgCatLen
      ? `All Manufacturing Group (${mfgAllowed.slice(0, 3).join(' · ')}${mfgAllowed.length > 3 ? ' +' + (mfgAllowed.length - 3) + ' more' : ''})`
      : `Assigned Entities (${mfgAllowed.slice(0, 3).join(' · ')}${mfgAllowed.length > 3 ? ' +' + (mfgAllowed.length - 3) + ' more' : ''})`;
    COMPANY_MOBILE_LABELS['manufacturing-group'] = mfgAllowed.length >= mfgCatLen
      ? `All Group (${mfgAllowed.length})`
      : `All Assigned (${mfgAllowed.length})`;

    syncSidebarHubVisibilityDom(user);
    if (!canViewView(STATE.view, user)) STATE.view = defaultViewFor(user);

    if (STATE.pbiPage && !canAccessPbiPage(STATE.pbiPage, user)) {
      STATE.pbiPage = 'p01_overview';
    }
    if (STATE.activeTableKey && !canAccessTable(STATE.activeTableKey, user)) {
      STATE.activeTableKey = 'sales_tickets';
    }
    if (window.MFG_RDL && Array.isArray(window.MFG_RDL.RDL_CATALOG)) {
      const permittedRdl = window.MFG_RDL.RDL_CATALOG.filter(r => canAccessRdlReport(r, user));
      if (permittedRdl.length && !permittedRdl.some(r => String(r.id || r.code) === String(STATE.activeStatement))) {
        STATE.activeStatement = permittedRdl[0].id || permittedRdl[0].code;
      }
    }

    const newBtn = $('newEntryBtn');
    if (newBtn) newBtn.hidden = !canEnterAny(user);
    const mNewBtn = $('mobileNewEntryBtn');
    if (mNewBtn) mNewBtn.hidden = !canEnterAny(user);

    const avEl = $('railUserAvatar'), nmEl = $('railUserName'), rlEl = $('activeRoleBadge'), scEl = $('railRlsScope');
    if (avEl) avEl.textContent = getInitials(user.full_name);
    if (nmEl) { nmEl.textContent = user.full_name; nmEl.setAttribute('data-full-text', user.full_name); nmEl.removeAttribute('title'); }
    if (rlEl) { rlEl.textContent = user.role; rlEl.setAttribute('data-full-text', user.role); rlEl.removeAttribute('title'); }
    if (scEl) {
      const shortNames = allowedNames.map(n => n.replace(/BBConstruction/g, 'BBC').replace(/Lions Transport/g, 'Lions'));
      const fullScope = allowedNames.join(' · ');
      scEl.textContent = shortNames.length <= 3
        ? shortNames.join(', ')
        : `${shortNames.slice(0, 2).join(', ')} +${shortNames.length - 2} more`;
      scEl.setAttribute('data-full-text', fullScope || scEl.textContent);
      scEl.removeAttribute('title');
    }
  }

  function resolveSelectedAuthUser() {
    if (FACE_STATE.pending2faUser || FACE_STATE.pendingPinUser) return null;
    const sel = norm(FACE_STATE.selectedAuthEmail || '');
    if (!sel) return null;
    return STATE.users.find(u => u.status !== 'Suspended' && norm(u.email) === sel) || null;
  }

  function syncAuthSelectedSeatUi() {
    const grp = $('authSelectedGroup');
    const bar = $('authSelectedSeatBar');
    const pinRow = $('authPinRow');
    const pinEl = $('authPinInput');
    const emEl = $('authEmailInput');
    const avEl = $('authSelectedSeatAvatar');
    const nmEl = $('authSelectedSeatName');
    const metaEl = $('authSelectedSeatMeta');
    const drawer = $('authSeatDrawer');
    const divEl = $('authMethodDivider');
    const divLblEl = $('authMethodDividerLabel');
    const serverHeld = rosterIsServerHeld();
    const selUser = serverHeld ? null : resolveSelectedAuthUser();
    const waitingCam2FA = !!FACE_STATE.pending2faUser;
    const waitingPin2FA = !!FACE_STATE.pendingPinUser;

    if (serverHeld) {
      const showCreds = !waitingCam2FA;
      FACE_STATE.seatDrawerOpen = showCreds;
      if (drawer) drawer.hidden = !showCreds;
      if (grp) grp.hidden = !showCreds;
      if (bar) bar.hidden = true;
      if (pinRow) pinRow.hidden = !showCreds;
      if (emEl) {
        emEl.setAttribute('placeholder', 'Work email address');
        emEl.setAttribute('aria-label', 'Work email address');
        if (waitingPin2FA && FACE_STATE.pendingPinUser && FACE_STATE.pendingPinUser.email && !emEl.value) {
          emEl.value = FACE_STATE.pendingPinUser.email;
        }
      }
      if (pinEl) {
        pinEl.setAttribute('placeholder', 'Access PIN');
        pinEl.setAttribute('aria-label', 'Access PIN');
      }
      if (divEl) {
        const wsMode = getWorkspaceAuthMode();
        if (waitingCam2FA || waitingPin2FA || wsMode === 'pin_only') {
          divEl.hidden = true;
        } else {
          divEl.hidden = false;
          if (divLblEl) divLblEl.textContent = 'or sign in with Email & PIN';
        }
      }
      return;
    }

    const showPicker = !selUser && !waitingCam2FA && !waitingPin2FA;
    const showPinGroup = !!(selUser || waitingPin2FA);

    FACE_STATE.seatDrawerOpen = showPicker;

    if (drawer) {
      drawer.hidden = !showPicker;
    }
    if (grp) {
      grp.hidden = !showPinGroup;
    }
    if (bar) {
      if (selUser) {
        bar.hidden = false;
        if (avEl) avEl.textContent = getInitials(selUser.full_name);
        if (nmEl) nmEl.textContent = selUser.full_name;
        if (metaEl) metaEl.textContent = `${formatCleanSeatRole(selUser.role)} · ${formatSeatEntityCountLabel(selUser)}`;
      } else {
        bar.hidden = true;
      }
    }
    if (pinRow) {
      pinRow.hidden = !showPinGroup;
    }
    if (pinEl) {
      const targetUser = waitingPin2FA ? FACE_STATE.pendingPinUser : selUser;
      if (targetUser) {
        const firstName = String(targetUser.full_name || '').trim().split(/\s+/)[0] || 'account';
        pinEl.setAttribute('placeholder', `Enter PIN for ${firstName}`);
        pinEl.setAttribute('aria-label', `Access PIN for ${targetUser.full_name}`);
      } else {
        pinEl.setAttribute('placeholder', 'Access PIN');
        pinEl.setAttribute('aria-label', 'Access PIN');
      }
    }
    if (divEl) {
      const wsMode = getWorkspaceAuthMode();
      if (waitingCam2FA || waitingPin2FA || wsMode === 'pin_only') {
        divEl.hidden = true;
      } else {
        divEl.hidden = false;
        if (divLblEl) {
          divLblEl.textContent = showPicker
            ? (IS_DEMO ? 'or open a demo workspace' : 'or select account for PIN')
            : 'or sign in with PIN';
        }
      }
    }
  }

  function setAuthSeatDrawerOpen(open, opts = {}) {
    if (open) {
      FACE_STATE.selectedAuthEmail = '';
    }
    FACE_STATE.seatDrawerOpen = !!open;
    if (!open) FACE_STATE.disambiguatePin = '';
    const emEl = $('authEmailInput');
    const pinEl = $('authPinInput');
    if (emEl && !rosterIsServerHeld()) {
      emEl.value = '';
    }
    renderQuickSeatsInAuthGate();
    syncAuthSelectedSeatUi();
    if (!opts.silentFocus && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
      const coarse = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
      if (open && emEl && !coarse) {
        setTimeout(() => { try { emEl.focus({ preventScroll: true }); } catch (_) {} }, 30);
      } else if (!open && pinEl && !coarse) {
        setTimeout(() => { try { pinEl.focus({ preventScroll: true }); } catch (_) {} }, 30);
      }
    }
  }

  const DEVICE_PAIRED_SEATS_KEY = 'isabi_mfg_device_seats_v1';
  function getRememberedDeviceSeats() {
    if (isDemoScopeActive()) return [];
    try {
      const raw = JSON.parse(localStorage.getItem(DEVICE_PAIRED_SEATS_KEY) || '[]');
      if (!Array.isArray(raw)) return [];
      const seen = new Set();
      const out = [];
      for (const item of raw) {
        if (!item || typeof item !== 'object') continue;
        const em = String(item.email || '').trim().toLowerCase();
        if (!em || !em.includes('@') || seen.has(em)) continue;
        seen.add(em);
        out.push({
          email: em,
          full_name: String(item.full_name || em).trim().slice(0, 80),
          role: String(item.role || 'Staff').trim().slice(0, 48)
        });
        if (out.length >= 8) break;
      }
      return out;
    } catch (_) {
      return [];
    }
  }
  function rememberVerifiedDeviceSeat(u) {
    if (!u || isDemoScopeActive()) return;
    const em = String(u.email || '').trim().toLowerCase();
    if (!em || !em.includes('@')) return;
    const entry = {
      email: em,
      full_name: String(u.full_name || em).trim().slice(0, 80),
      role: String(u.role || 'Staff').trim().slice(0, 48)
    };
    const rest = getRememberedDeviceSeats().filter(x => x.email !== em);
    try {
      localStorage.setItem(DEVICE_PAIRED_SEATS_KEY, JSON.stringify([entry].concat(rest).slice(0, 8)));
    } catch (_) {}
  }
  function forgetRememberedDeviceSeat(emailRaw) {
    const em = String(emailRaw || '').trim().toLowerCase();
    if (!em) return;
    const next = getRememberedDeviceSeats().filter(x => x.email !== em);
    try {
      if (next.length) localStorage.setItem(DEVICE_PAIRED_SEATS_KEY, JSON.stringify(next));
      else localStorage.removeItem(DEVICE_PAIRED_SEATS_KEY);
    } catch (_) {}
  }

  function renderQuickSeatsInAuthGate() {
    const listEl = $('quickSeatList');
    if (!listEl) return;
    if (rosterIsServerHeld()) {
      const paired = getRememberedDeviceSeats();
      if (!paired.length) {
        listEl.hidden = true;
        listEl.innerHTML = '';
        return;
      }
      listEl.hidden = false;
      const emEl = $('authEmailInput');
      const curEm = norm((emEl && emEl.value) || '');
      listEl.innerHTML = paired.map(s => {
        const selected = curEm && curEm === norm(s.email);
        return `
          <div class="quick-seat-paired-row">
            <button type="button" class="quick-seat-item${selected ? ' is-selected' : ''}" data-quick-seat="${esc(s.email)}">
              <span class="quick-seat-av" aria-hidden="true" data-no-i18n="1">${esc(getInitials(s.full_name))}</span>
              <div class="quick-seat-copy">
                <b data-no-i18n="1">${esc(s.full_name)}</b>
                <small>${esc(formatCleanSeatRole(s.role))} · <span data-no-i18n="1">${esc(s.email)}</span></small>
              </div>
              <span class="quick-seat-cue">PIN</span>
            </button>
            <button type="button" class="quick-seat-forget" data-forget-device-seat="${esc(s.email)}" aria-label="Forget ${esc(s.full_name)}" data-ui-tip="Remove remembered account from this browser">✕</button>
          </div>
        `;
      }).join('');
      listEl.querySelectorAll('[data-quick-seat]').forEach(btn => {
        btn.addEventListener('click', () => {
          const targetEm = btn.getAttribute('data-quick-seat') || '';
          const emInp = $('authEmailInput');
          const pinInp = $('authPinInput');
          if (emInp) {
            emInp.value = targetEm;
            emInp.dispatchEvent(new Event('input', { bubbles: true }));
          }
          const errEl = $('authErrorBox');
          if (errEl) errEl.hidden = true;
          renderQuickSeatsInAuthGate();
          if (pinInp) {
            pinInp.value = '';
            try { pinInp.focus({ preventScroll: true }); } catch (_) {}
          }
        });
      });
      listEl.querySelectorAll('[data-forget-device-seat]').forEach(btn => {
        btn.addEventListener('click', ev => {
          ev.stopPropagation();
          const targetEm = btn.getAttribute('data-forget-device-seat') || '';
          forgetRememberedDeviceSeat(targetEm);
          const emInp = $('authEmailInput');
          if (emInp && norm(emInp.value) === norm(targetEm)) emInp.value = '';
          renderQuickSeatsInAuthGate();
        });
      });
      return;
    }
    listEl.hidden = false;
    const emEl = $('authEmailInput');
    const rawFilter = (!resolveSelectedAuthUser() && emEl) ? norm(emEl.value) : '';
    const disPin = String(FACE_STATE.disambiguatePin || '').trim();
    const sessFreq = new Map();
    (STATE.sessions || []).forEach(s => {
      if (!s) return;
      const ek = norm(s.email || s.user_email || '');
      const nk = norm(s.user_name || s.full_name || '');
      if (ek) sessFreq.set(ek, (sessFreq.get(ek) || 0) + 1);
      if (nk) sessFreq.set(nk, (sessFreq.get(nk) || 0) + 1);
    });
    const activeSeats = STATE.users.filter(u => u.status !== 'Suspended').slice().sort((a, b) => {
      const fa = (sessFreq.get(norm(a.email)) || 0) + (sessFreq.get(norm(a.full_name)) || 0);
      const fb = (sessFreq.get(norm(b.email)) || 0) + (sessFreq.get(norm(b.full_name)) || 0);
      return fb - fa;
    });
    const filtered = activeSeats.filter(u => {
      if (disPin && u.pin_code && String(u.pin_code).trim() !== disPin) return false;
      if (!rawFilter) return true;
      return norm(u.full_name).includes(rawFilter) || norm(u.email).includes(rawFilter) || norm(u.role).includes(rawFilter);
    });

    if (!filtered.length) {
      listEl.innerHTML = `<div class="quick-seat-empty">No matching team account</div>`;
      return;
    }

    listEl.innerHTML = filtered.map(u => {
      const active = norm(FACE_STATE.selectedAuthEmail || '') === norm(u.email);
      const seatMode = effectiveSeatAuthMode(u);
      const rightTag = IS_DEMO
        ? `<span class="quick-seat-demo-tag">Open</span>`
        : (seatMode === 'face_only'
          ? `<span class="quick-seat-cue">Face ID</span>`
          : `<span class="quick-seat-cue">PIN <svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg></span>`);
      return `
      <button type="button" class="quick-seat-item${active ? ' is-selected' : ''}" data-quick-seat="${esc(u.email)}">
        <span class="quick-seat-av" aria-hidden="true" data-no-i18n="1">${esc(getInitials(u.full_name))}</span>
        <div class="quick-seat-copy">
          <b data-no-i18n="1">${esc(u.full_name)}</b>
          <small>${esc(formatCleanSeatRole(u.role))} · ${esc(formatSeatEntityCountLabel(u))}</small>
        </div>
        ${rightTag}
      </button>
    `;
    }).join('');

    listEl.querySelectorAll('[data-quick-seat]').forEach(btn => {
      btn.addEventListener('click', () => {
        const u = STATE.users.find(x => norm(x.email) === norm(btn.getAttribute('data-quick-seat')));
        if (!u) return;
        const pinEl = $('authPinInput');
        if (IS_DEMO) {
          FACE_STATE.selectedAuthEmail = u.email;
          if (pinEl) pinEl.value = u.pin_code || DEMO_FALLBACK_PIN;
          performLogin(u.email, u.pin_code || DEMO_FALLBACK_PIN, { bypass2FA: true });
          return;
        }
        if (effectiveSeatAuthMode(u) === 'face_only') {
          authError(`${u.full_name} uses Face ID only. Look at the camera above.`, { noShake: true, keepPin: true });
          setAuthHint(`Look at camera to sign in as ${u.full_name}`, 'warn');
          if (!FACE_STATE.camActive && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) startAuthFaceScanner(true);
          return;
        }
        const pendingDisPin = String(FACE_STATE.disambiguatePin || '').trim();
        FACE_STATE.selectedAuthEmail = u.email;
        FACE_STATE.disambiguatePin = '';
        FACE_STATE.seatDrawerOpen = false;
        if (emEl) emEl.value = '';
        const errEl = $('authErrorBox');
        if (errEl) errEl.hidden = true;
        syncAuthSelectedSeatUi();
        if (pendingDisPin && (!u.pin_code || pendingDisPin === String(u.pin_code).trim())) {
          performLogin(u.email, pendingDisPin);
          return;
        }
        if (pinEl) {
          pinEl.value = '';
          try { pinEl.focus({ preventScroll: true }); } catch (_) {}
        }
      });
    });
  }

  function openAuthGate(prefillEmail) {
    // Every way back to the sign-in screen (sign-out, idle lock, session expiry) starts the next person clean:
    // no carried-over face misses and no held face descriptor that could ride along with their PIN.
    FACE_STATE.edgeMissCount = 0;
    FACE_STATE.edgeProbeLockedUntil = 0;
    FACE_STATE.lastLiveGateDescriptor = null;
    FACE_STATE.lastLiveGateAt = 0;
    FACE_STATE.lastVerifiedDescriptor = null;
    FACE_STATE.pendingPinDescriptor = null;
    // A stakeholder balance card must not stay in the page once the seat signs out or the session ends.
    if (typeof closeHoldingExtendedShareCard === 'function') closeHoldingExtendedShareCard();
    if (window.MFG_CMD_PALETTE && typeof window.MFG_CMD_PALETTE.close === 'function') {
      window.MFG_CMD_PALETTE.close({ clearCache: true });
    }
    if (window.MFG_ASK && typeof window.MFG_ASK.clearSessionState === 'function') {
      window.MFG_ASK.clearSessionState();
    }
    if (window.MFG_STEP_UP && typeof window.MFG_STEP_UP.clearLease === 'function') {
      window.MFG_STEP_UP.clearLease();
    }
    // A signed-out screen keeps no other seat's unlock requests or saved views. Reset first, while the
    // session can still cancel a waiting request (idle lock or expiry reach here without signOut).
    if (window.MFG_APPROVALS && typeof window.MFG_APPROVALS.reset === 'function') window.MFG_APPROVALS.reset();
    if (window.MFG_SAVED_VIEWS && typeof window.MFG_SAVED_VIEWS.reset === 'function') window.MFG_SAVED_VIEWS.reset();
    STATE.authed = false;
    STATE.cashflowBehind = null;
    STATE.sourceBehind = null;
    STATE.behindDayPrev = null;
    _cashflowBehindGen++;
    window.__mfgSwResuming = false;
    document.documentElement.classList.remove('sw-resuming');
    FACE_STATE.pending2faUser = null;
    FACE_STATE.pending2faPin = '';
    FACE_STATE.pendingPinUser = null;
    FACE_STATE.lastLiveGateDescriptor = null;
    FACE_STATE.lastLiveGateMethod = '';
    FACE_STATE.lastLiveGateAt = 0;
    FACE_STATE.streakUser = null;
    FACE_STATE.streakCount = 0;
    FACE_STATE.edgeProbeStreak = 0;
    FACE_STATE.detectorStreak = 0;
    FACE_STATE.edgeProbeCooldownUntil = 0;
    FACE_STATE.edgeProbeBusy = false;
    FACE_STATE.disambiguatePin = '';
    setAuthStreak(0, 3);
    const serverHeld = rosterIsServerHeld();
    if (hasServerApi() && !isDemoSandboxSession() && !serverHeld && !_usersApiHydratedOnce) {
      hydrateServerUsersOnce();
    }
    let candidateEmail = prefillEmail || '';
    if (!candidateEmail && !IS_DEMO && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
      try { candidateEmail = localStorage.getItem('isabi_mfg_last_seat') || ''; } catch (_) {}
    }
    const preUser = (!serverHeld && candidateEmail) ? STATE.users.find(u => u.status !== 'Suspended' && norm(u.email) === norm(candidateEmail)) : null;
    FACE_STATE.selectedAuthEmail = preUser ? preUser.email : '';
    FACE_STATE.seatDrawerOpen = serverHeld ? true : !preUser;
    resetLivenessState();
    window.__mfgAuthedEmail = '';
    const emEl = $('authEmailInput');
    const pinEl = $('authPinInput');
    if (emEl) emEl.value = (serverHeld && candidateEmail) ? candidateEmail : '';
    if (pinEl) pinEl.value = '';
    const errEl = $('authErrorBox');
    if (errEl) errEl.hidden = true;
    renderQuickSeatsInAuthGate();
    updateCloudBadges();
    updateAuthFaceUi();
    syncAuthSelectedSeatUi();
    const gate = $('authGate');
    if (gate) gate.hidden = false;
    document.body.classList.add('locked');
    if (!FACE_STATE.authCamStoppedByUser) startAuthFaceScanner(false);
    setTimeout(() => {
      if (!STATE.authed) {
        const coarse = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
        if (!coarse && window.innerWidth > 860) {
          const focusTarget = (preUser || (serverHeld && candidateEmail)) ? pinEl : (serverHeld ? emEl : null);
          if (focusTarget) {
            try { focusTarget.focus({ preventScroll: true }); } catch (_) {}
          }
        }
      }
    }, 60);
  }

  function closeAuthGate() {
    STATE.authed = true;
    window.__mfgSwResuming = false;
    document.documentElement.classList.remove('sw-resuming');
    if (FACE_STATE.loopTimer) { clearTimeout(FACE_STATE.loopTimer); FACE_STATE.loopTimer = null; }
    FACE_STATE.camActive = false;
    FACE_STATE.pending2faUser = null;
    FACE_STATE.pending2faPin = '';
    FACE_STATE.pendingPinUser = null;
    FACE_STATE.lastLiveGateDescriptor = null;
    FACE_STATE.lastLiveGateMethod = '';
    FACE_STATE.lastLiveGateAt = 0;
    FACE_STATE.streakUser = null;
    FACE_STATE.streakCount = 0;
    FACE_STATE.edgeProbeStreak = 0;
    FACE_STATE.detectorStreak = 0;
    FACE_STATE.edgeProbeCooldownUntil = 0;
    FACE_STATE.edgeProbeBusy = false;
    FACE_STATE.seatDrawerOpen = false;
    FACE_STATE.disambiguatePin = '';
    FACE_STATE.enrolCamActive = false;
    window.__mfgAuthedEmail = activeUser().email;
    const gate = $('authGate');
    if (gate) gate.hidden = true;
    document.body.classList.remove('locked');
    setAuthStreak(0, 3);
    resetLivenessState();
    if (hasServerApi() && !isDemoSandboxSession()) {
      hydrateServerUsersOnce();
    }
    try { window.dispatchEvent(new CustomEvent('mfg:auth-gate-closed')); } catch (_) {}
    const shouldKeepNonAuthCam = () => Boolean(
      FACE_STATE.enrolCamActive ||
      KIOSK_ATT_STATE.camActive ||
      KIOSK_ATT_STATE.camStarting ||
      KIOSK_ADMIN_MODAL_STATE.camActive ||
      STAFF_FACE_MODAL_STATE.camActive ||
      (STATE.view === 'kiosks' && STATE.activeKiosk === 'attendance' && STATE.kioskLocked)
    );
    if (IS_AUTOMATED_TEST) {
      if (!shouldKeepNonAuthCam()) stopFaceCamera();
      updateAuthFaceUi();
    } else if (typeof requestAnimationFrame === 'function') {
      requestAnimationFrame(() => {
        setTimeout(() => {
          if (STATE.authed && !shouldKeepNonAuthCam()) {
            stopFaceCamera();
            updateAuthFaceUi();
          }
        }, 0);
      });
    } else {
      if (!shouldKeepNonAuthCam()) stopFaceCamera();
      updateAuthFaceUi();
    }
    const keep = new URLSearchParams();
    ['demo', 'nosse'].forEach(p => { if (PARAMS.has(p)) keep.set(p, PARAMS.get(p)); });
    if (STATE.kioskLocked && STATE.view === 'kiosks' && STATE.activeKiosk) {
      keep.set('kiosk', STATE.activeKiosk);
    }
    const targetUrl = location.pathname + (keep.toString() ? '?' + keep.toString() : '') + (VIEW_TITLES[STATE.view] ? '#' + STATE.view : '');
    if (location.pathname + location.search + location.hash !== targetUrl) {
      history.replaceState({ view: STATE.view }, '', targetUrl);
    }
  }

  function purgePrivateSeedCachesOnLogout() {
    try {
      if (navigator.serviceWorker && navigator.serviceWorker.controller) {
        navigator.serviceWorker.controller.postMessage({ type: 'PURGE_SEED_CACHE' });
      }
      if (navigator.serviceWorker && navigator.serviceWorker.ready) {
        navigator.serviceWorker.ready.then(reg => {
          if (reg && reg.active) reg.active.postMessage({ type: 'PURGE_SEED_CACHE' });
        }).catch(() => {});
      }
    } catch (_) {}
    try {
      if (window.caches && typeof window.caches.open === 'function') {
        window.caches.open('isabi-mfg-data-v3').then(async cache => {
          const keys = await cache.keys();
          await Promise.all(keys.map(req => {
            try {
              const p = new URL(req.url).pathname;
              if (p.includes('/api/seed/') || /\/seed_(core|records|industries)\.json$/.test(p)) {
                return cache.delete(req);
              }
            } catch (_) {}
            return false;
          }));
        }).catch(() => {});
      }
    } catch (_) {}
  }

  function signOut() {
    // Withdraw a waiting unlock request while this session can still cancel it (before the logout call).
    if (window.MFG_APPROVALS && typeof window.MFG_APPROVALS.cancelActive === 'function') window.MFG_APPROVALS.cancelActive(false);
    if (window.MFG_CMD_PALETTE && typeof window.MFG_CMD_PALETTE.close === 'function') {
      window.MFG_CMD_PALETTE.close({ clearCache: true });
    }
    closeTabletKeysModal();
    resetQuoteDrafts();
    // Nothing kept for the seat that is leaving stays in memory (kept lookup indexes and workforce audits).
    STATE.cashflowBehind = null;
    STATE.sourceBehind = null;
    STATE.behindDayPrev = null;
    _cashflowBehindGen++;
    _WF_AUDIT_KEPT.clear();
    _WF_AUDIT_CACHE = null;
    if (window.MFG_PBI && typeof window.MFG_PBI.clearHubRelKept === 'function') window.MFG_PBI.clearHubRelKept();
    if (isDemoSandboxSession()) {
      try {
        for (let i = sessionStorage.length - 1; i >= 0; i--) {
          const k = sessionStorage.key(i);
          if (k && k.startsWith('demo_sbx_')) sessionStorage.removeItem(k);
        }
        sessionStorage.removeItem('isabi_mfg_sw_resume');
      } catch (_) {}
    } else {
      if (STATE.company === DEMO_COMPANY_KEY || _demoCompanySandboxActive) {
        STATE.company = (_demoCompanyPrevRealCo && _demoCompanyPrevRealCo !== DEMO_COMPANY_KEY) ? _demoCompanyPrevRealCo : 'manufacturing-group';
        try { syncDemoScopeDataState(); } catch (_) {}
      }
      _demoCompanyLiveSnap = null;
      _demoCompanySandboxSeed = null;
      _demoCompanyIndPromise = null;
      _demoCompanySandboxActive = false;
      _demoSanitizedActive = false;
      _demoCompanySandboxStores.customRecords = {};
      _demoCompanySandboxStores.industryCustomRows = {};
      _demoCompanySandboxStores.industryRowEdits = {};
      try {
        for (let i = sessionStorage.length - 1; i >= 0; i--) {
          const k = sessionStorage.key(i);
          if (k && k.startsWith('demo_sbx_')) sessionStorage.removeItem(k);
        }
      } catch (_) {}
      if (hasServerApi()) {
        try { edgeApiFetch('./api/auth/logout', { method: 'POST' }).catch(() => {}); } catch (_) {}
      }
      setEdgeSessionToken('');
      _edgeCookieAuthed = false;
      purgePrivateSeedCachesOnLogout();
      try { localStorage.removeItem('isabi_mfg_active_email'); } catch (_) {}
      try { localStorage.removeItem('isabi_mfg_last_seat'); } catch (_) {}
      try { localStorage.removeItem('isabi_mfg_kiosk_station_seat'); } catch (_) {}
      try { sessionStorage.removeItem('isabi_mfg_sw_resume'); } catch (_) {}
      if (rosterIsServerHeld()) {
        STATE.users = [];
        STATE.activeUserIdx = 0;
        _usersApiHydratedOnce = false;
        try { appStoreRemoveRaw('isabi_mfg_users_v2'); } catch (_) {}
        SEED.records = {};
        SEED.models = {};
        SEED.industryLive = null;
        SEED._coreReady = false;
        SEED._recordsReady = false;
        SEED._preAuthDeferred = true;
        SEED._canonicalById = null;
        SEED._canonicalByMain = null;
        SEED._origModelMasters = null;
        _seedHydrationPromise = null;
        window.__mfgCoreSeedLoaded = false;
        invalidateAllSeedCaches();
        applyUserRlsAndPermissions();
      }
    }
    clearTimeout(toastTimer);
    clearTimeout(toastFadeTimer);
    const tEl = $('toast');
    if (tEl) { tEl.classList.remove('is-leaving'); tEl.hidden = true; }
    closeEntryModal(true);
    if (window.MFG_ASK && typeof window.MFG_ASK.clearSessionState === 'function') {
      window.MFG_ASK.clearSessionState();
    }
    if (window.MFG_STEP_UP && typeof window.MFG_STEP_UP.clearLease === 'function') {
      window.MFG_STEP_UP.clearLease();
    }
    if (window.MFG_TELEMATICS && typeof window.MFG_TELEMATICS.clearSessionCache === 'function') {
      window.MFG_TELEMATICS.clearSessionCache();
    }
    const keep = new URLSearchParams();
    ['demo', 'nosse'].forEach(p => { if (PARAMS.has(p)) keep.set(p, PARAMS.get(p)); });
    history.replaceState({ view: STATE.view }, '', location.pathname + (keep.toString() ? '?' + keep.toString() : ''));
    openAuthGate('');
  }

  function authError(msg, opts = {}) {
    const errEl = $('authErrorBox');
    if (errEl) { errEl.textContent = msg; errEl.hidden = false; }
    const card = document.querySelector('.auth-card');
    if (card && !opts.noShake) { card.classList.remove('shake'); void card.offsetWidth; card.classList.add('shake'); }
    const pinEl = $('authPinInput');
    if (pinEl && !opts.keepPin) {
      pinEl.value = '';
      try { pinEl.focus({ preventScroll: true }); } catch (_) {}
    }
  }

  let loginAttempts = 0;
  let loginLockUntil = 0;
  let authUiLoginBusy = false;
  let authPinProbeTimer = null;
  let authPinProbeInFlight = false;
  async function performLogin(emailRaw, pinRaw, opts = {}) {
    let email = norm(emailRaw);
    const pin = String(pinRaw || '').trim();
    const silentProbe = Boolean(opts && opts.silentAutoProbe);
    const serverHeld = rosterIsServerHeld();
    if (Date.now() < loginLockUntil) {
      if (!silentProbe) authError(`Too many attempts. Wait ${Math.ceil((loginLockUntil - Date.now()) / 1000)}s.`);
      return false;
    }
    let serverVerifiedLogin = Boolean(opts && opts.serverToken);
    if (!email && pin) {
      if (serverHeld) {
        if (!silentProbe) authError('Enter your work email and Access PIN.', { keepPin: true });
        return false;
      }
      const matches = STATE.users.filter(u => u.status !== 'Suspended' && u.pin_code && String(u.pin_code).trim() === pin);
      if (matches.length === 1) {
        email = norm(matches[0].email);
        const emEl = $('authEmailInput');
        if (emEl && !FACE_STATE.seatDrawerOpen) emEl.value = matches[0].email;
      } else if (matches.length > 1) {
        FACE_STATE.disambiguatePin = pin;
        setAuthSeatDrawerOpen(true, { silentFocus: true });
        authError('Select your account below to finish signing in.', { keepPin: true, noShake: true });
        return false;
      } else {
        if (silentProbe) return false;
        loginAttempts += 1;
        if (loginAttempts >= 5) { loginLockUntil = Date.now() + 30000; loginAttempts = 0; authError('Too many wrong PINs. Locked for 30 seconds.'); }
        else authError('Incorrect Access PIN.');
        return false;
      }
    }
    const reqMethod = String((opts && opts.method) || '');
    const isPinlessBypass = Boolean(opts && opts.bypass2FA) && (
      (/^face\s*id/i.test(reqMethod) && !/face\s*id\s*\+\s*pin/i.test(reqMethod)) ||
      reqMethod === 'Owner Impersonation' ||
      reqMethod === 'Interactive Sandbox'
    );
    if (!email) {
      if (!silentProbe) authError(serverHeld ? 'Enter your work email and Access PIN.' : 'Enter your Access PIN.', { keepPin: serverHeld });
      return false;
    }
    if (!pin && !isPinlessBypass && !serverVerifiedLogin) {
      if (!silentProbe) authError('Enter your Access PIN.');
      return false;
    }

    const ua = navigator.userAgent || '';
    const devLabel = /iPhone|iPad/i.test(ua) ? 'iOS Safari' : (/Android/i.test(ua) ? 'Android Chrome' : (/Edg\//.test(ua) ? 'Desktop Edge' : 'Desktop Browser'));
    let idx = STATE.users.findIndex(u => norm(u.email) === email);
    if (idx < 0 && !serverHeld && !email.includes('@')) {
      const subMatches = STATE.users.filter(u => u.status !== 'Suspended' && (norm(u.full_name).includes(email) || norm(u.email).includes(email)));
      if (subMatches.length === 1) idx = STATE.users.indexOf(subMatches[0]);
    }
    if (idx < 0 && serverHeld && hasServerApi() && !isDemoSandboxSession()) {
      if (!email.includes('@')) {
        if (!silentProbe) authError('Enter your work email and Access PIN.', { keepPin: true });
        return false;
      }
      const recentGateFace = (Array.isArray(FACE_STATE.lastLiveGateDescriptor) && FACE_STATE.lastLiveGateDescriptor.length === 128 && (Date.now() - Number(FACE_STATE.lastLiveGateAt || 0)) < 30000)
        ? FACE_STATE.lastLiveGateDescriptor
        : undefined;
      const directFaceVec = (Array.isArray(opts.faceDescriptor) && opts.faceDescriptor.length === 128) ? opts.faceDescriptor : recentGateFace;
      const directMethod = opts.method || (directFaceVec ? (FACE_STATE.lastLiveGateMethod || 'Face ID + PIN 2FA') : 'PIN');
      const directConf = opts.confidence != null ? Number(opts.confidence) : (directFaceVec ? 92 : null);
      try {
        const rDirect = await edgeApiFetch('./api/auth/login', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            email,
            pin,
            device: devLabel,
            method: directMethod,
            confidence: directConf,
            face_descriptor: directFaceVec
          })
        });
        const jDirect = rDirect ? await rDirect.json().catch(() => null) : null;
        if (rDirect && rDirect.ok && jDirect && jDirect.ok && jDirect.user) {
          _edgeCookieAuthed = true;
          if (jDirect.token) setEdgeSessionToken(jDirect.token);
          else setEdgeSessionToken('');
          const authedSeat = ensureCanonicalMultiIndustrySeat(Object.assign({}, jDirect.user, { pin_redacted: true }));
          delete authedSeat.pin_code;
          delete authedSeat._verifiedPin;
          const existIdx = STATE.users.findIndex(u => norm(u.email) === norm(authedSeat.email));
          if (existIdx >= 0) { STATE.users[existIdx] = authedSeat; idx = existIdx; }
          else { STATE.users.push(authedSeat); idx = STATE.users.length - 1; }
          serverVerifiedLogin = true;
          opts = Object.assign({}, opts, { bypass2FA: true, method: directMethod, confidence: directConf });
        } else if (jDirect && jDirect.two_factor_face_required) {
          const twoFaSeat = {
            id: (jDirect.user && jDirect.user.id) || 'u-2fa',
            email,
            full_name: (jDirect.user && jDirect.user.full_name) || email,
            role: 'Entry',
            companies: 'WTC',
            status: 'Active',
            face_enrolled: true,
            auth_mode: 'both',
            pin_redacted: true
          };
          FACE_STATE.pending2faUser = twoFaSeat;
          FACE_STATE.pending2faPin = pin;
          FACE_STATE.pendingPinUser = null;
          FACE_STATE.streakUser = null;
          FACE_STATE.streakCount = 0;
          FACE_STATE.edgeProbeStreak = 0;
          FACE_STATE.edgeProbeCooldownUntil = 0;
          FACE_STATE.edgeProbeBusy = false;
          resetLivenessState();
          const errEl = $('authErrorBox');
          if (errEl) errEl.hidden = true;
          updateAuthFaceUi();
          syncAuthSelectedSeatUi();
          setAuthHint(`PIN verified. Look at the camera to verify ${twoFaSeat.full_name}.`, 'ok');
          if (!FACE_STATE.camActive && !navigator.webdriver) startAuthFaceScanner(true);
          return '2fa_pending';
        } else if (rDirect && rDirect.status === 429) {
          loginLockUntil = Date.now() + 30000;
          if (!silentProbe) authError((jDirect && jDirect.error) || 'Too many failed sign-in attempts. Wait 60 seconds.');
          return false;
        } else {
          if (silentProbe) return false;
          loginAttempts += 1;
          if (loginAttempts >= 5) { loginLockUntil = Date.now() + 30000; loginAttempts = 0; authError('Too many failed sign-in attempts. Locked for 30 seconds.'); }
          else authError((jDirect && jDirect.error) || 'Invalid email or Access PIN.');
          return false;
        }
      } catch (_) {
        if (!silentProbe) authError('Offline: cannot verify uncached seat credentials.');
        return false;
      }
    }
    if (idx < 0) { if (!silentProbe) authError('Account not found in this workspace.'); return false; }
    const user = STATE.users[idx];
    if (user.status === 'Suspended') { if (!silentProbe) authError('This seat is suspended. Contact an administrator.'); return false; }
    const localPinStr = String(user.pin_code || '').trim();
    const completedFaceFirst2FA = !!(FACE_STATE.pendingPinUser && norm(FACE_STATE.pendingPinUser.email) === norm(user.email));
    const pendingFaceVecForPin = completedFaceFirst2FA
      ? (opts.faceDescriptor || FACE_STATE.pendingPinDescriptor || FACE_STATE.lastVerifiedDescriptor || null)
      : null;
    if (!serverVerifiedLogin && !isPinlessBypass && (!localPinStr || pin !== localPinStr)) {
      let verifiedViaApi = false;
      let rateLimitedErr = '';
      if (hasServerApi() && !isDemoSandboxSession()) {
        try {
          const recentGateFace = (Array.isArray(FACE_STATE.lastLiveGateDescriptor) && FACE_STATE.lastLiveGateDescriptor.length === 128 && (Date.now() - Number(FACE_STATE.lastLiveGateAt || 0)) < 30000)
            ? FACE_STATE.lastLiveGateDescriptor
            : undefined;
          const checkFaceVec = pendingFaceVecForPin || opts.faceDescriptor || recentGateFace;
          const rCheck = await edgeApiFetch('./api/auth/login', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              email: user.email,
              pin,
              method: completedFaceFirst2FA ? (opts.method || 'Face ID + PIN 2FA') : (opts.method || 'PIN'),
              face_descriptor: Array.isArray(checkFaceVec) && checkFaceVec.length === 128 ? checkFaceVec : undefined,
              device: 'PIN Verify'
            })
          });
          const jCheck = rCheck ? await rCheck.json().catch(() => null) : null;
          if (rCheck && rCheck.ok && jCheck && jCheck.ok) {
            _edgeCookieAuthed = true;
            if (jCheck.token) setEdgeSessionToken(jCheck.token);
            if (serverHeld) {
              if (jCheck.user) {
                const cleanU = Object.assign({}, jCheck.user, { pin_redacted: true });
                delete cleanU.pin_code;
                STATE.users[idx] = mergeUserRow(user, cleanU);
              }
              delete STATE.users[idx].pin_code;
              delete STATE.users[idx]._verifiedPin;
              STATE.users[idx].pin_redacted = true;
            } else {
              if (jCheck.user) STATE.users[idx] = mergeUserRow(user, Object.assign({}, jCheck.user, { pin_code: pin, _verifiedPin: true }));
              user.pin_code = pin;
              user._verifiedPin = true;
              delete user.pin_redacted;
            }
            verifiedViaApi = true;
            serverVerifiedLogin = true;
          } else if (jCheck && jCheck.two_factor_face_required) {
            FACE_STATE.pending2faPin = pin;
            if (!serverHeld) {
              user.pin_code = pin;
              user._verifiedPin = true;
              delete user.pin_redacted;
            }
            verifiedViaApi = true;
          } else if (rCheck && rCheck.status === 429) {
            rateLimitedErr = (jCheck && jCheck.error) || 'Too many failed sign-in attempts. Wait 60 seconds.';
          }
        } catch (_) {}
      }
      const demoSeat = DEFAULT_USERS.concat(MULTI_INDUSTRY_ROLE_SEATS).find(du => norm(du.email) === norm(user.email));
      const demoFallbackPin = (demoSeat && DEMO_SEAT_PINS[demoSeat.id]) || DEMO_FALLBACK_PIN;
      if (!verifiedViaApi && (!localPinStr ? ((serverHeld || Boolean(window.ISABI_HAS_EDGE_API || window.__ISABI_TEST_EDGE)) && !isDemoSandboxSession() ? true : (pin !== demoFallbackPin && pin !== DEMO_FALLBACK_PIN)) : true)) {
        if (silentProbe) return false;
        if (rateLimitedErr) {
          loginLockUntil = Date.now() + 30000;
          authError(rateLimitedErr);
          return false;
        }
        loginAttempts += 1;
        if (loginAttempts >= 5) { loginLockUntil = Date.now() + 30000; loginAttempts = 0; authError('Too many wrong PINs. Locked for 30 seconds.'); }
        else authError(serverHeld ? 'Invalid email or Access PIN.' : ('Incorrect PIN for ' + user.full_name + '.'));
        return false;
      }
    }
    loginAttempts = 0;

    const seatMode = effectiveSeatAuthMode(user);
    // If seat is configured for Face ID Only, block PIN-only sign-in and prompt for live camera scan
    if (!opts.bypass2FA && seatMode === 'face_only' && !serverHeld) {
      authError(`${user.full_name} requires Face ID to sign in. Look at the camera above.`);
      setAuthHint(`Look at the camera to sign in as ${user.full_name}`, 'warn');
      if (!FACE_STATE.camActive && !navigator.webdriver) startAuthFaceScanner(true);
      return 'face_only_required';
    }

    // If user already completed Live Face ID Step 1 under 'both' mode, completing PIN Step 2 signs them in!
    if (completedFaceFirst2FA) {
      FACE_STATE.pendingPinUser = null;
      FACE_STATE.pendingPinDescriptor = null;
      opts = Object.assign({}, opts, { bypass2FA: true, method: opts.method || 'Face ID + PIN 2FA', faceDescriptor: pendingFaceVecForPin || opts.faceDescriptor });
    }

    // Step-Up 2FA Biometric Gate: if this seat has enrolled Face ID and 2FA ('both') is enforced, require Live Face ID confirmation!
    if (!opts.bypass2FA && userRequiresFace2FA(user)) {
      FACE_STATE.pending2faUser = user;
      FACE_STATE.pending2faPin = pin;
      FACE_STATE.pendingPinUser = null;
      FACE_STATE.streakUser = null;
      FACE_STATE.streakCount = 0;
      FACE_STATE.edgeProbeStreak = 0;
      FACE_STATE.edgeProbeCooldownUntil = 0;
      FACE_STATE.edgeProbeBusy = false;
      resetLivenessState();
      const errEl = $('authErrorBox');
      if (errEl) errEl.hidden = true;
      updateAuthFaceUi();
      syncAuthSelectedSeatUi();
      setAuthHint(`PIN verified. Look at the camera to verify ${user.full_name}.`, 'ok');
      if (!FACE_STATE.camActive && !navigator.webdriver) startAuthFaceScanner(true);
      return '2fa_pending';
    }

    const nowStr = nowStamp();
    const standalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone;
    const authMethod = opts.method || 'PIN';
    const authConf = opts.confidence != null ? Number(opts.confidence) : null;
    const isEdgeAuthActive = Boolean(serverHeld || window.ISABI_HAS_EDGE_API || window.__ISABI_TEST_EDGE);

    if (hasServerApi() && !serverVerifiedLogin && !isDemoSandboxSession()) {
      const loginFaceVec = (Array.isArray(opts.faceDescriptor) && opts.faceDescriptor.length === 128)
        ? opts.faceDescriptor
        : ((opts.bypass2FA && Array.isArray(user.face_samples) && Array.isArray(user.face_samples[0]) && user.face_samples[0].length === 128)
          ? user.face_samples[0]
          : (Array.isArray(FACE_STATE.lastVerifiedDescriptor) && FACE_STATE.lastVerifiedDescriptor.length === 128 ? FACE_STATE.lastVerifiedDescriptor : undefined));
      try {
        const rLogin = await edgeApiFetch('./api/auth/login', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ email: user.email, pin, device: devLabel, method: authMethod, confidence: authConf, face_descriptor: loginFaceVec })
        });
        if (rLogin && rLogin.ok) {
          const jLogin = await rLogin.json().catch(() => null);
          _edgeCookieAuthed = true;
          serverVerifiedLogin = true;
          if (jLogin && jLogin.token) setEdgeSessionToken(jLogin.token);
          else setEdgeSessionToken('');
          if (serverHeld) {
            if (jLogin && jLogin.user) {
              const cleanLoginU = Object.assign({}, jLogin.user, { pin_redacted: true });
              delete cleanLoginU.pin_code;
              STATE.users[idx] = mergeUserRow(STATE.users[idx], cleanLoginU);
            }
            delete STATE.users[idx].pin_code;
            delete STATE.users[idx]._verifiedPin;
            STATE.users[idx].pin_redacted = true;
          } else {
            const verifiedPinPatch = (pin && !isPinlessBypass) ? { pin_code: pin, _verifiedPin: true } : {};
            if (jLogin && jLogin.user) STATE.users[idx] = mergeUserRow(STATE.users[idx], Object.assign({}, jLogin.user, verifiedPinPatch));
            else if (pin && !isPinlessBypass) { STATE.users[idx].pin_code = pin; STATE.users[idx]._verifiedPin = true; delete STATE.users[idx].pin_redacted; }
          }
        } else if (isEdgeAuthActive) {
          const jErr = rLogin ? await rLogin.json().catch(() => null) : null;
          if (jErr && jErr.two_factor_face_required) {
            FACE_STATE.pending2faUser = user;
            FACE_STATE.pending2faPin = pin;
            FACE_STATE.pendingPinUser = null;
            resetLivenessState();
            updateAuthFaceUi();
            syncAuthSelectedSeatUi();
            setAuthHint(`PIN verified. Look at the camera to verify ${user.full_name}.`, 'ok');
            if (!FACE_STATE.camActive && !navigator.webdriver) startAuthFaceScanner(true);
            return '2fa_pending';
          }
          if (jErr && jErr.two_factor_pin_required) {
            FACE_STATE.pendingPinUser = user;
            FACE_STATE.pendingPinDescriptor = loginFaceVec || null;
            updateAuthFaceUi();
            syncAuthSelectedSeatUi();
            setAuthHint(`Face verified for ${user.full_name}. Enter PIN to finish sign-in.`, 'ok');
            return '2fa_pin_pending';
          }
          if (isPinlessBypass && user && Array.isArray(user.face_samples) && user.face_samples.length) {
            user.face_samples = [];
            user.face_redacted = true;
            FACE_STATE.cooldownUntil = 0;
          }
          authError((jErr && jErr.error) || ('Verification failed for ' + user.full_name + '.'));
          return false;
        } else {
          setEdgeSessionToken('');
        }
      } catch (_) {
        if (isEdgeAuthActive) {
          const canOfflineVerify = (localPinStr && pin === localPinStr) || (Array.isArray(loginFaceVec) && loginFaceVec.length === 128 && userFaceSamples(user).length > 0);
          if (!canOfflineVerify) {
            authError('Offline: cannot verify uncached seat credentials.');
            return false;
          }
        }
      }
    }

    FACE_STATE.pending2faUser = null;
    FACE_STATE.pending2faPin = '';
    FACE_STATE.pendingPinUser = null;
    FACE_STATE.lastLiveGateDescriptor = null;
    FACE_STATE.lastLiveGateMethod = '';
    FACE_STATE.lastLiveGateAt = 0;
    const finalAuthedUser = STATE.users[idx];
    if (window.MFG_ASK && typeof window.MFG_ASK.clearSessionState === 'function' && STATE.activeUserIdx !== idx) {
      window.MFG_ASK.clearSessionState();
    }
    finalAuthedUser.last_login_at = nowStr.slice(0, 16);
    STATE.activeUserIdx = idx;
    if (!isDemoSandboxSession()) {
      try { localStorage.removeItem('isabi_mfg_active_email'); } catch (_) {}
    }
    if (serverVerifiedLogin && !isDemoScopeActive() && finalAuthedUser && finalAuthedUser.email) {
      rememberVerifiedDeviceSeat(finalAuthedUser);
    }
    if (!IS_DEMO && !isDemoSandboxSession() && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
      try { localStorage.setItem('isabi_mfg_last_seat', finalAuthedUser.email); } catch (_) {}
      if (STATE.kioskLocked || STATE.view === 'kiosks') {
        try { localStorage.setItem('isabi_mfg_kiosk_station_seat', JSON.stringify({ email: finalAuthedUser.email, ts: Date.now() })); } catch (_) {}
      }
    }
    STATE.sessions.unshift({
      id: uid('sess'),
      full_name: finalAuthedUser.full_name,
      email: finalAuthedUser.email,
      role: finalAuthedUser.role,
      companies: finalAuthedUser.companies,
      device: devLabel + (standalone ? ' · Home Screen app' : ''),
      method: authMethod,
      confidence: authConf,
      logged_in_at: nowStr
    });
    STATE.sessions = STATE.sessions.slice(0, 50);
    saveLocalAuthAndRecords();

    if (!getAllowedCompanyKeys(finalAuthedUser).includes(STATE.company)) STATE.company = getAllowedCompanyKeys(finalAuthedUser)[0];
    if (!canViewView(STATE.view, finalAuthedUser)) STATE.view = defaultViewFor(finalAuthedUser);
    closeAuthGate();
    STATE.search = '';
    STATE.showAddUserForm = false;
    renderApp();
    toastWelcome(finalAuthedUser, authMethod);
    syncWithCloud(true);
    if (isOwner(finalAuthedUser) && !isDemoScopeActive() && !isDemoSandboxSession()) {
      loadCashflowBehindNotice();
    } else {
      STATE.cashflowBehind = null;
      STATE.sourceBehind = null;
    }
    return true;
  }

  // ==========================================================================
  // ASK ISABI COPILOT BRIDGE (DELEGATES TO js/ask_isabi.js HYBRID ENGINE)
  // ==========================================================================
  function answerAskIsabi(qRaw) {
    if (window.MFG_ASK && typeof window.MFG_ASK.answer === 'function') {
      return window.MFG_ASK.answer(qRaw);
    }
    const k = getKPI();
    const scope = `${String(COMPANY_LABELS[STATE.company] || 'Selected Entities').split('(')[0].trim()} · ${k.label || 'All-Time'}`;
    return `<strong>${esc(scope)} Summary:</strong><br>Sales ${fmtUSD(k.sales_ttc, 2)} across ${fmtNum(k.loads)} loads · Gross Margin ${fmtUSD(k.gross_margin, 0)} · Operating Profit ${fmtUSD(k.operating_profit, 0)}.`;
  }

  // ==========================================================================
  // MASTER RENDER & EVENT WIRING
  // ==========================================================================
  let searchTimer = null;

  function contextFormForView(view, user) {
    user = user || activeUser();
    if (view === 'kiosks') {
      const kf = STATE.activeKiosk === 'raw' ? 'raw' : (STATE.activeKiosk === 'fuel' ? (STATE.kioskFuelSubmode === 'refill' ? 'expense' : (STATE.kioskFuelSubmode === 'malfunction' ? 'malfunction' : 'fuel')) : (STATE.activeKiosk === 'attendance' ? 'attendance' : 'sales'));
      if (canEnterForm(kf, user)) return kf;
    }
    const map = {
      kiosks: 'sales', sales: 'sales', sales_vat: 'vatinvoice', sales_analytics: 'sales',
      sentinels: 'defect', alert_rules: 'defect', approvals: 'defect',
      raw: 'raw', raw_pricing: 'pricerule_raw', raw_analytics: 'raw', raw_jv: 'jv', jv: 'jv',
      fleet: 'fuel', fleet_equip: 'companyequipment', fleet_maint: 'defect', fleet_drivers: 'triprate', fleet_analytics: 'triprate',
      pricing: 'pricerule',
      cashflow: 'receipt', cashflow_analytics: 'receipt',
      external: 'external', conversions: 'conversion',
      customers: 'receipt', ar: 'receipt',
      suppliers: 'settlement', ap: 'settlement',
      expenses: 'expense', expenses_analytics: 'expense', recurring_expenses: 'recurringexpense', documents: 'document',
      warehouse: 'warehousestock', warehouse_parts: 'repair',
      payroll: 'salary', workforce_map: 'attendance', payroll_attendance: 'attendance', payroll_allowances: 'logistics', payroll_contracts: 'employment', payroll_analytics: 'salary',
      hld_consolidation: 'external', hld_entities: 'external', hld_interactions: 'external', hld_open_recon: 'external', hld_due_matrix: 'external',
      hld_partners: 'jv', hld_extended: 'extended', hld_distributions: 'jv', hld_loans: 'treasury', hld_assets: 'expense',
      hsp_revenue: 'sales', hsp_pos: 'receipt', hsp_vat: 'vatinvoice',
      hsp_memberships: 'sales', hsp_partners: 'jv',
      hsp_stock: 'warehousestock', hsp_menu: 'pricerule',
      hsp_energy: 'fuel', hsp_maint: 'repair',
      trd_sales: 'sales', trd_receivables: 'receipt', trd_targets: 'pricerule',
      trd_purchases: 'raw', trd_landed: 'expense', trd_grn: 'warehousestock',
      trd_trucks: 'equipment', trd_warranty: 'repair',
      trd_stock: 'item', trd_movements: 'warehousestock', trd_recon: 'warehousestock',
      re_leases: 'pricerule', re_invoicing: 'sales', re_receipts: 'receipt',
      re_sales: 'sales', re_instalments: 'receipt',
      re_properties: 'site', re_units: 'product', re_valuations: 'site', re_ownership: 'jv',
      re_workorders: 'repair', re_recharges: 'expense',
      ins_policies: 'sales', ins_renewals: 'sales', ins_items: 'equipment',
      ins_billing: 'receipt', ins_remittances: 'settlement', ins_statements: 'external',
      ins_claims: 'defect', ins_catalogue: 'product', ins_agreements: 'pricerule',
      ledger: 'treasury', gl: 'treasury', ledger_treasury: 'treasury',
      tables: 'pricerule',
      reg_equipment: 'equipment', reg_drivers: 'driver', reg_staff: 'staff', reg_roles: 'staffrole', reg_sites: 'site', reg_regions: 'region',
      reg_products: 'product', reg_items: 'item', reg_customers: 'customer', reg_suppliers: 'supplier', reg_categories: 'expensecategory',
      reg_fx_rates: 'fxrate', reg_currencies: 'currency', reg_vat_rates: 'vatrate'
    };
    let preferred = map[view] || 'sales';
    const activeIndForForm = getActiveIndustry(STATE.company);
    if (activeIndForForm !== 'Manufacturing' && ['overview', 'daily_ops', 'entities', 'pbi', 'statements'].includes(view)) {
      const indTpl0 = (INDUSTRY_QUICK_ENTRY_TEMPLATES[activeIndForForm] || [])[0];
      if (indTpl0 && indTpl0.form && FORM_TITLES[indTpl0.form]) preferred = indTpl0.form;
    }
    if (view === 'tables' && window.MFG_PBI) { // the hub's active table owns the form (e.g. Loans → Treasury desk)
      const meta = (window.MFG_PBI.TABLE_CATALOG || []).find(t => t.key === STATE.activeTableKey);
      if (meta && meta.form && (FORM_TITLES[meta.form] || meta.form === 'extended')) {
        preferred = (meta.key === 'external_movements' && activeIndForForm === 'Holding & Treasury' && STATE.tableViews && STATE.tableViews.external_movements === 'extended') ? 'extended' : meta.form;
      }
    } else if (String(view || '').startsWith('reg_') && window.MFG_PBI) {
      const meta = (window.MFG_PBI.TABLE_CATALOG || []).find(t => t.key === (STATE.activeUnivRegKey || UNIV_VIEW_TO_TABLE_KEY[view]));
      if (meta && meta.form && FORM_TITLES[meta.form]) preferred = meta.form;
    }
    if (canEnterForm(preferred, user)) return preferred;
    if (canEnterForm('sales', user)) return 'sales';
    if (canEnterForm('receipt', user)) return 'receipt';
    return 'sales';
  }

  function renderMobileSubnav(user, k, sentinelsOpen) {
    const el = $('mobileSubnav');
    if (!el) return;
    const v = STATE.view;
    const activeHubId = VIEW_TO_HUB[v] || 'overview';
    const activeHub = getHubDef(activeHubId) || HUB_CATALOG[0];
    const group = (activeHub && activeHub.group) || 'exec';

    const activeInd = getActiveIndustry(STATE.company);
    const activeIndSpec = INDUSTRY_SIDEBAR_SPEC[activeInd] || INDUSTRY_SIDEBAR_SPEC['Manufacturing'];
    const activeIndHubSet = new Set(activeIndSpec.slots.map(s => s.hub).concat(['expenses', 'payroll']));
    const hubsInGroup = HUB_CATALOG.filter(h => {
      if (h.group === 'commercial' || h.group === 'plant') {
        if (!activeIndHubSet.has(h.id)) return false;
      }
      const sameDock = (group === 'commercial' || group === 'plant')
        ? (h.group === 'commercial' || h.group === 'plant')
        : ((group === 'books' || group === 'universal' || group === 'system' || group === 'master')
          ? (h.group === 'books' || h.group === 'universal' || h.group === 'system' || h.group === 'master')
          : h.group === group);
      return sameDock && canViewHub(h.id, user);
    });
    el.innerHTML = hubsInGroup.map(h => {
      const on = h.id === activeHubId;
      const badge = getHubExceptionBadge(h.id, user, k, sentinelsOpen);
      return `<button type="button" class="m-subnav-pill${on ? ' on' : ''}" data-subnav-hub="${esc(h.id)}" data-subnav-view="${esc(resolveHubView(h.id, user))}" title="${esc(h.title)}"><i class="m-subnav-ico" aria-hidden="true">${ic(h.id)}</i><span>${esc(h.title)}</span>${badge ? `<em class="${esc(badge.cls)}">${esc(badge.text)}</em>` : ''}</button>`;
    }).join('');
    el.querySelectorAll('[data-subnav-hub]').forEach(btn => btn.addEventListener('click', () => clickHub(btn.getAttribute('data-subnav-hub'))));

    // Sync Mobile Bottom Dock active states
    const dOver = $('dockBtnOverview'), dDisp = $('dockBtnDispatch'), dBooks = $('dockBtnBooks'), dEntry = $('mobileDockEntryBtn'), dEntryLbl = $('mobileDockEntryLabel');
    if (dOver) dOver.classList.toggle('on', group === 'exec');
    if (dDisp) dDisp.classList.toggle('on', group === 'commercial' || group === 'plant' || group === 'dispatch');
    if (dBooks) dBooks.classList.toggle('on', group === 'books' || group === 'universal' || group === 'system' || group === 'master');
    // The operations dock button is named after the active industry, never a fixed Manufacturing word.
    const dDispLbl = dDisp ? dDisp.querySelector('span') : null;
    if (dDispLbl) {
      const dockOpsLabels = {
        'Manufacturing': 'Dispatch',
        'Holding & Treasury': 'Holding',
        'Hospitality & Resorts': 'Resorts',
        'Automotive & Heavy Trading': 'Trading',
        'Real Estate & Property': 'Properties',
        'Insurance & Brokerage': 'Policies'
      };
      const opsLbl = dockOpsLabels[activeInd] || 'Operations';
      if (dDispLbl.textContent !== opsLbl) dDispLbl.textContent = opsLbl;
    }
    if (dEntry && dEntryLbl) {
      if (canEnterAny(user)) {
        dEntry.hidden = false;
        const formLabels = {
          sales: 'Post Ticket', raw: 'Post Raw', fuel: 'Log Fuel', malfunction: 'Log Malfunction', receipt: 'Post Receipt',
          settlement: 'Settle AP', expense: 'Post Expense', recurringexpense: 'Recurring Sched', warehousestock: 'Warehouse Stock', salary: 'Pay Salary',
          vatinvoice: 'Post VAT Inv', attendance: 'Log Attendance', logistics: 'Site Transport', employment: 'New Contract',
          treasury: 'Loan / Settle', external: 'External Entry', extended: 'Extended Entry', conversion: 'FX Conversion', pricerule: 'New Agreement', pricerule_raw: 'New Site Rate',
          jv: 'Post JV Entry', defect: 'Report Warning', repair: 'Log Repair', oillog: 'Log Oil', partlog: 'Log Part', companyequipment: 'Assign Unit',
          customer: 'New Customer', supplier: 'New Supplier', product: 'New Product', item: 'New Item', expensecategory: 'New Category',
          site: 'New Site', region: 'New Region', equipment: 'New Equipment', driver: 'New Driver', staff: 'New Staff',
          fxrate: 'New FX Rate', vatrate: 'New VAT Rate', currency: 'New Currency'
        };
        const ctxEntryForm = contextFormForView(v, user);
        const mfgOnlyEntryForms = { sales: 1, raw: 1, fuel: 1, malfunction: 1, pricerule_raw: 1, jv: 1 };
        const siblingDomainEntry = activeInd !== 'Manufacturing' && (/^(hld_|hsp_|trd_|re_|ins_)/.test(String(v || '')) || mfgOnlyEntryForms[ctxEntryForm]);
        dEntryLbl.textContent = siblingDomainEntry ? 'New Entry' : (formLabels[ctxEntryForm] || 'Post Entry');
      } else {
        dEntry.hidden = true;
      }
    }
  }

  function renderHubSubtabBar(user, k, sentinelsOpen) {
    const hubId = VIEW_TO_HUB[STATE.view] || 'overview';
    const hubDef = getHubDef(hubId);
    if (!hubDef || hubId === 'kiosks') return '';
    const permittedTabs = hubDef.tabs.filter(t => canViewView(t.view, user));
    if (permittedTabs.length <= 1) return '';
    const pillsHtml = permittedTabs.map(t => {
      const matchViews = t.match || [t.view];
      const isActive = matchViews.includes(STATE.view);
      const lbl = (isActive && !UNIV_VIEW_TO_TABLE_KEY[STATE.view] && VIEW_TITLES[STATE.view])
        ? VIEW_TITLES[STATE.view]
        : (t.shortLabel || t.label || VIEW_TITLES[t.view] || t.view);
      const badge = typeof t.badgeFn === 'function' ? t.badgeFn(user, k, sentinelsOpen) : null;
      const pillHtml = badge && badge.text ? `<em class="hub-subtab-pill${badge.cls ? ' ' + badge.cls : ''}">${esc(badge.text)}</em>` : '';
      return `<button type="button" class="hub-subtab${isActive ? ' active' : ''}" data-hub-subtab="${esc(t.view)}" aria-current="${isActive ? 'page' : 'false'}"><i class="nav-ico" aria-hidden="true">${ic(t.icon || t.view)}</i><span class="hub-subtab-lbl">${esc(lbl)}</span>${pillHtml}</button>`;
    }).join('');
    return `<nav class="hub-subtab-bar no-print" id="hubSubtabBar" data-parent-hub="${esc(hubId)}" aria-label="${esc(hubDef.title)} Sub-Views">${pillsHtml}</nav>`;
  }

  function setRailWidth(w, persist = true) {
    STATE.railWidth = clampRailWidth(w);
    if (persist) {
      try { localStorage.setItem('isabi_mfg_rail_width', String(STATE.railWidth)); } catch (_) {}
    }
    syncRailCollapseUi();
  }

  function syncRailCollapseUi() {
    const shell = $('appShell');
    const menuBtn = $('mobileMenuBtn');
    const menuLbl = $('sidebarToggleLbl');
    const narrowBtn = $('railNarrowBtn');
    const widerBtn = $('railWiderBtn');
    const resizer = $('railResizer');
    const isMobile = typeof window !== 'undefined' && window.innerWidth <= 860;
    const collapsed = !isMobile && !!STATE.railCollapsed;
    const w = clampRailWidth(STATE.railWidth);
    document.documentElement.style.setProperty('--rail-w', `${w}px`);
    if (shell) {
      shell.style.setProperty('--rail-w', `${w}px`);
      shell.classList.toggle('rail-collapsed', collapsed);
      shell.classList.toggle('rail-narrow', !isMobile && !collapsed && w < 218);
      shell.classList.toggle('rail-wide', !isMobile && !collapsed && w >= 290);
    }
    if (narrowBtn) narrowBtn.disabled = w <= RAIL_MIN_W;
    if (widerBtn) widerBtn.disabled = w >= RAIL_MAX_W;
    if (resizer) {
      resizer.setAttribute('aria-valuenow', String(w));
      resizer.title = `Sidebar width: ${w}px — Drag left or right to make wider/narrower · Double-click to reset (${RAIL_DEFAULT_W}px)`;
    }
    if (menuBtn) {
      menuBtn.classList.toggle('rail-is-hidden', collapsed);
      menuBtn.setAttribute('aria-expanded', String(!collapsed));
      menuBtn.title = isMobile
        ? 'Open navigation menu'
        : (collapsed ? 'Show left navigation sidebar' : 'Hide left navigation sidebar to expand main view');
    }
    if (menuLbl) {
      menuLbl.textContent = collapsed ? 'Show Menu' : 'Hide Menu';
    }
  }

