  function loadKioskStationConfig() {
    if (IS_AUTOMATED_TEST) return null;
    try {
      const s = appStoreGetRaw('isabi_mfg_kiosk_station_cfg_v1');
      if (!s) return null;
      const raw = JSON.parse(s);
      return raw && typeof raw === 'object' ? raw : null;
    } catch (_) {
      return null;
    }
  }

  function saveKioskStationConfig(extra = {}) {
    if (IS_AUTOMATED_TEST) return;
    const prev = loadKioskStationConfig() || {};
    const next = Object.assign({}, prev, {
      activeKiosk: STATE.activeKiosk || 'sales',
      company: STATE.company || 'manufacturing-group',
      kioskAttSite: STATE.kioskAttSite || 'WTC Main Plant',
      kioskAttSiteCustom: !!STATE.kioskAttSiteCustom,
      kioskAttDir: STATE.kioskAttDir || 'auto',
      kioskIdleStandbySec: Number(STATE.kioskIdleStandbySec != null ? STATE.kioskIdleStandbySec : 60),
      kioskNightSleep: STATE.kioskNightSleep !== false,
      kioskLocked: !!STATE.kioskLocked,
      updatedAt: Date.now()
    }, extra || {});
    try {
      appStoreSetRaw('isabi_mfg_kiosk_station_cfg_v1', JSON.stringify(next));
    } catch (_) {}
  }

  function isKioskNightOffShiftNow(d = new Date()) {
    if (STATE.kioskNightSleep === false) return false;
    const h = d.getHours();
    const m = d.getMinutes();
    return h >= 23 || h < 5 || (h === 5 && m < 30);
  }

  function getEffectiveKioskIdleStandbyMs(d = new Date()) {
    if (isKioskNightOffShiftNow(d)) return 20 * 1000;
    const sec = Number(STATE.kioskIdleStandbySec != null ? STATE.kioskIdleStandbySec : 60);
    return sec > 0 ? sec * 1000 : 0;
  }

  function touchKioskAttActivity() {
    KIOSK_ATT_STATE.lastActivityAt = Date.now();
  }

  async function releaseAllKioskCameraHardware(settleMs = 380) {
    ['kioskAttVideo', 'ksaAdminFaceVideo', 'staffEnrolVideo', 'authFaceVideo', 'enrolFaceVideo'].forEach(id => {
      const el = $(id);
      if (!el) return;
      if (el.srcObject) {
        try { el.srcObject.getTracks().forEach(t => t.stop()); } catch (_) {}
        el.srcObject = null;
      }
      try { el.pause(); } catch (_) {}
    });
    if (FACE_STATE.stream) {
      try { FACE_STATE.stream.getTracks().forEach(t => t.stop()); } catch (_) {}
      FACE_STATE.stream = null;
    }
    if (window.Face && typeof window.Face.stopAllStreams === 'function') {
      try { window.Face.stopAllStreams(); } catch (_) {}
    }
    const waitMs = Math.max(0, Number(settleMs || 0));
    if (waitMs > 0 && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
      await new Promise(r => setTimeout(r, waitMs));
    }
  }

  function buildKioskIdleStandbyCardHtml() {
    const parts = formatKioskWallClockNow();
    const hhmm = String(parts.time || '').slice(0, 5);
    const isNight = !!KIOSK_ATT_STATE.nightSleep;
    const siteLbl = STATE.kioskAttSite || 'Main Station';
    return `
      <div class="kiosk-cam-standby-card kiosk-idle-saver-card ${isNight ? 'is-night-saver' : ''}" id="kioskIdleStandbyCard">
        <span class="kiosk-idle-pill">${isNight ? 'Night Power Saver (23:00-05:30)' : 'Camera Power Saver'}</span>
        <div class="kiosk-idle-clock mono" id="kioskIdleClockTime">${esc(hhmm)}</div>
        <div class="kiosk-idle-date" id="kioskIdleClockDate">${esc(parts.date)} · ${esc(siteLbl)}</div>
        <div class="kiosk-idle-cta">
          <span class="kiosk-idle-tap-dot"></span>
          <strong>Tap Anywhere on Screen to Activate Camera</strong>
        </div>
        <p>${isNight
          ? 'Camera and display dimmed during off-shift hours. Single tap wakes Face ID instantly.'
          : 'Camera powers down automatically when idle to keep this wall terminal cool and responsive.'}</p>
      </div>
    `;
  }

  function enterKioskAttIdleStandby(mode = 'idle') {
    if (navigator.webdriver || window.__MFG_HEADLESS_TEST || IS_AUTOMATED_TEST) return false;
    if (STATE.view !== 'kiosks' || STATE.activeKiosk !== 'attendance' || !STATE.kioskLocked) return false;
    if (KIOSK_ADMIN_MODAL_STATE.open) return false;
    const isNight = mode === 'night' || isKioskNightOffShiftNow();
    stopKioskAttCamera();
    KIOSK_ATT_STATE.standbyIdle = true;
    KIOSK_ATT_STATE.nightSleep = isNight;
    KIOSK_ATT_STATE.blackFrameStreak = 0;
    KIOSK_ATT_STATE.statusText = isNight
      ? 'Night power saver active. Tap screen once to wake Face ID camera.'
      : 'Display in power saver. Tap anywhere on screen to activate camera.';
    KIOSK_ATT_STATE.statusCls = '';
    if (typeof document !== 'undefined' && document.body) {
      document.body.classList.add('kiosk-idle-dimmed');
      document.body.classList.toggle('kiosk-night-sleep', isNight);
    }
    wireKioskAttIdleWakeOnce();
    syncKioskAttLiveUiInPlace();
    return true;
  }

  function wakeKioskAttFromStandby() {
    if (!KIOSK_ATT_STATE.standbyIdle && !KIOSK_ATT_STATE.nightSleep) return false;
    KIOSK_ATT_STATE.standbyIdle = false;
    KIOSK_ATT_STATE.nightSleep = false;
    KIOSK_ATT_STATE.camPausedByUser = false;
    KIOSK_ATT_STATE.blackFrameStreak = 0;
    KIOSK_ATT_STATE.justWokeAt = Date.now();
    KIOSK_ATT_STATE.lastActivityAt = Date.now();
    if (typeof document !== 'undefined' && document.body) {
      document.body.classList.remove('kiosk-idle-dimmed', 'kiosk-night-sleep');
    }
    const idleCard = $('kioskIdleStandbyCard');
    if (idleCard) idleCard.remove();
    const vpEl = $('kioskAttViewport');
    if (vpEl) vpEl.classList.remove('is-idle-saver');
    KIOSK_ATT_STATE.statusText = 'Waking camera... Look inside the oval guide';
    KIOSK_ATT_STATE.statusCls = 'ok';
    syncKioskAttLiveUiInPlace();
    startKioskAttCamera({ forceRestart: true, silentWatchdog: true });
    return true;
  }

  function wireKioskAttIdleWakeOnce() {
    if (KIOSK_ATT_STATE.idleWakeWired || typeof window === 'undefined') return;
    KIOSK_ATT_STATE.idleWakeWired = true;
    const onWakePointer = e => {
      if (!STATE.kioskLocked || STATE.view !== 'kiosks' || STATE.activeKiosk !== 'attendance') return;
      if (KIOSK_ADMIN_MODAL_STATE.open) return;
      const hitAdmin = Boolean(e.target && e.target.closest && e.target.closest('#kioskWallAdminBtn'));
      if (KIOSK_ATT_STATE.standbyIdle || KIOSK_ATT_STATE.nightSleep) {
        if (hitAdmin) {
          KIOSK_ATT_STATE.standbyIdle = false;
          KIOSK_ATT_STATE.nightSleep = false;
          KIOSK_ATT_STATE.lastActivityAt = Date.now();
          document.body.classList.remove('kiosk-idle-dimmed', 'kiosk-night-sleep');
          return;
        }
        e.preventDefault();
        e.stopPropagation();
        wakeKioskAttFromStandby();
        return;
      }
      KIOSK_ATT_STATE.lastActivityAt = Date.now();
    };
    const onWakeClickCapture = e => {
      if ((Date.now() - (KIOSK_ATT_STATE.justWokeAt || 0)) < 450) {
        const hitAdmin = Boolean(e.target && e.target.closest && e.target.closest('#kioskWallAdminBtn'));
        if (!hitAdmin) {
          e.preventDefault();
          e.stopPropagation();
        }
      }
    };
    window.addEventListener('pointerdown', onWakePointer, { capture: true });
    window.addEventListener('click', onWakeClickCapture, { capture: true });
  }

  function stashKioskSwResumeAndReload() {
    try {
      const u = activeUser();
      if (u && u.email) {
        sessionStorage.setItem('isabi_mfg_sw_resume', JSON.stringify({ email: u.email, ts: Date.now() }));
      }
      saveKioskStationConfig();
    } catch (_) {}
    location.reload();
  }

  async function checkAndApplyKioskOtaUpdate(opts = {}) {
    if (KIOSK_ATT_STATE.otaChecking || typeof window === 'undefined') return { ok: false, reason: 'busy' };
    if (navigator.webdriver || window.__MFG_HEADLESS_TEST) return { ok: false, reason: 'headless' };
    KIOSK_ATT_STATE.otaChecking = true;
    const btn = $('ksaCheckUpdateBtn');
    const curVer = String(window.__MFG_SHELL_VER || '');
    if (btn && !opts.silent) {
      btn.disabled = true;
      btn.textContent = 'Checking Update...';
    }
    try {
      let remoteVer = '';
      try {
        const res = await fetch('./sw.js?_ota=' + Date.now(), { cache: 'no-store' });
        if (res && res.ok) {
          const txt = await res.text();
          const m = txt.match(/SHELL_CACHE\s*=\s*['"]isabi-mfg-v([^'"]+)['"]/);
          if (m && m[1]) remoteVer = m[1];
        }
      } catch (_) {}
      if ('serviceWorker' in navigator) {
        try {
          const reg = await navigator.serviceWorker.getRegistration();
          if (reg) await reg.update().catch(() => {});
        } catch (_) {}
      }
      if (remoteVer && curVer && remoteVer !== curVer) {
        if (!opts.silent) toast(`Updating terminal from v${curVer} to v${remoteVer}...`, 'ok');
        if (window.caches) {
          try {
            const keys = await caches.keys();
            for (const k of keys) {
              if (k.startsWith('isabi-mfg-v') && k !== ('isabi-mfg-v' + remoteVer)) {
                await caches.delete(k);
              }
            }
          } catch (_) {}
        }
        await new Promise(r => setTimeout(r, 600));
        stashKioskSwResumeAndReload();
        return { ok: true, updated: true, remoteVer };
      }
      if (opts.forceReload) {
        stashKioskSwResumeAndReload();
        return { ok: true, reloaded: true, remoteVer: remoteVer || curVer };
      }
      if (!opts.silent) {
        toast(`Terminal is up to date (v${remoteVer || curVer})`, 'ok');
      }
      return { ok: true, updated: false, remoteVer: remoteVer || curVer };
    } finally {
      KIOSK_ATT_STATE.otaChecking = false;
      if (btn && !opts.silent) {
        btn.disabled = false;
        btn.innerHTML = `${ic('rotate')} Check &amp; Update (v${esc(curVer)})`;
      }
    }
  }

  function syncNativeStationPreset(roleKey) {
    try {
      const nb = window.IsabiNativeBridge;
      if (!nb || typeof nb.syncStationPreset !== 'function') return;
      const presetId = KIOSK_NATIVE_PRESET_MAP[roleKey] || KIOSK_NATIVE_PRESET_MAP[STATE.activeKiosk] || 'isabi_att';
      nb.syncStationPreset(presetId);
    } catch (_) {}
  }

  function syncKioskLockedUrl() {
    try {
      const keep = new URLSearchParams();
      ['demo', 'nosse'].forEach(p => { if (PARAMS.has(p)) keep.set(p, PARAMS.get(p)); });
      if (STATE.kioskLocked && STATE.view === 'kiosks' && STATE.activeKiosk) {
        keep.set('kiosk', STATE.activeKiosk);
      }
      const targetUrl = location.pathname + (keep.toString() ? '?' + keep.toString() : '') + (STATE.authed && VIEW_TITLES[STATE.view] ? '#' + STATE.view : '');
      if (location.pathname + location.search + location.hash !== targetUrl) {
        history.replaceState({ view: STATE.view }, '', targetUrl);
      }
    } catch (_) {}
  }

  function resolveIsabiSeatForFaceEntry(entry) {
    if (!entry) return null;
    const rawId = String(entry.id || '');
    const nName = norm(entry.name || entry.full_name || '');
    const nEmail = norm(entry.email || '');
    const users = ensureMultiIndustryRoleSeats(STATE.users || DEFAULT_USERS);
    const matched = users.find(su => {
      if (!su || su.status === 'Suspended' || isGenericTerminalSeat(su)) return false;
      if (!rawId.startsWith('stfbio:') && rawId && String(su.id || '') === rawId) return true;
      if (nEmail && norm(su.email) === nEmail) return true;
      if (nName && norm(su.full_name) === nName) return true;
      return false;
    });
    if (matched) return matched;
    const ownerRef = DEFAULT_USERS[0];
    if (ownerRef && ((nName && nName === norm(ownerRef.full_name)) || (nEmail && nEmail === norm(ownerRef.email)))) {
      return users.find(su => su && (String(su.id) === 'u1' || norm(su.email) === norm(ownerRef.email) || norm(su.full_name) === norm(ownerRef.full_name))) || ownerRef;
    }
    return null;
  }

  function isAuthorizedKioskAdminFace(entry) {
    if (!entry) return false;
    const nName = norm(entry.name || entry.full_name || '');
    const nEmail = norm(entry.email || '');
    const ownerRef = DEFAULT_USERS[0];
    if (String(entry.id || '') === 'u1' || (ownerRef && ((nName && nName === norm(ownerRef.full_name)) || (nEmail && nEmail === norm(ownerRef.email))))) return true;
    const matchedUser = resolveIsabiSeatForFaceEntry(entry);
    if (matchedUser) {
      const r = String(matchedUser.role || '').toLowerCase();
      if (isOwner(matchedUser) || isAdminUser(matchedUser) || /owner|admin|manager|supervisor|director/.test(r)) {
        return true;
      }
      return false;
    }
    if (!String(entry.id || '').startsWith('stfbio:') && entry.email) {
      const entryRole = String(entry.role || '').toLowerCase();
      if (/owner|admin|manager|supervisor|director/.test(entryRole)) return true;
    }
    return false;
  }

  function canUserEnrolStaff(u) {
    const target = u || getActiveEnrolOperatorUser();
    if (!target || target.status === 'Suspended' || isGenericTerminalSeat(target)) return false;
    const seat = resolveIsabiSeatForFaceEntry({
      id: target.id,
      name: target.full_name || target.name,
      email: target.email,
      role: target.role
    }) || ((target.email || target.id) ? target : null);
    if (!seat || seat.status === 'Suspended' || isGenericTerminalSeat(seat)) return false;
    const r = String(seat.role || '').toLowerCase();
    if (isOwner(seat) || isAdminUser(seat) || /owner|admin|manager|supervisor|director/.test(r)) return true;
    if (resolveCanonicalRoleKey(seat.role) === 'Entry' || /entry/i.test(r)) return true;
    if (canEnterForm('staff', seat) || canEnterForm('employment', seat)) return true;
    return false;
  }

  function isAuthorizedKioskStaffEnrolFace(entry) {
    if (!entry) return false;
    if (isAuthorizedKioskAdminFace(entry)) return true;
    const seat = resolveIsabiSeatForFaceEntry(entry);
    if (!seat) return false;
    return canUserEnrolStaff(seat);
  }

  function getActiveEnrolOperatorUser() {
    if (STAFF_FACE_MODAL_STATE.open && STAFF_FACE_MODAL_STATE.operatorUser) {
      return STAFF_FACE_MODAL_STATE.operatorUser;
    }
    if (KIOSK_ADMIN_MODAL_STATE.sessionActive && KIOSK_ADMIN_MODAL_STATE.verifiedUser) {
      return KIOSK_ADMIN_MODAL_STATE.verifiedUser;
    }
    return activeUser();
  }

  function isProtectedAdminSeatForEntry(targetUserObj, operatorUser) {
    if (!targetUserObj) return false;
    const op = operatorUser || getActiveEnrolOperatorUser();
    if (!op) return false;
    const opRole = String(op.role || '').toLowerCase();
    const opIsAdminOrSup = isOwner(op) || isAdminUser(op) || /owner|admin|manager|supervisor|director/.test(opRole);
    if (opIsAdminOrSup) return false;
    const targetRole = String(targetUserObj.role || '').toLowerCase();
    const targetIsAdminOrSup = isOwner(targetUserObj) || isAdminUser(targetUserObj) || /owner|admin|manager|supervisor|director/.test(targetRole);
    return targetIsAdminOrSup;
  }

  // PIN unlock is disabled on Kiosk Admin (Admin access is strictly Face ID only)
  function verifyKioskAdminPin(_pinInput) {
    return false;
  }

  function formatKioskAdminCountdown(msRemaining) {
    const totalSec = Math.max(0, Math.ceil(Number(msRemaining || 0) / 1000));
    const mm = String(Math.floor(totalSec / 60)).padStart(2, '0');
    const ss = String(totalSec % 60).padStart(2, '0');
    return `${mm}:${ss}`;
  }

  function updateKioskAdminCountdownDom() {
    if (!KIOSK_ADMIN_MODAL_STATE.sessionActive) return;
    const remMs = KIOSK_ADMIN_MODAL_STATE.expiresAt - Date.now();
    if (remMs <= 0) {
      expireKioskAdminSession('inactivity');
      return;
    }
    const badgeEl = $('ksaSessionCountdownBadge');
    if (badgeEl) {
      const who = KIOSK_ADMIN_MODAL_STATE.verifiedAdmin || 'Admin';
      badgeEl.textContent = `${who} · Auto-logout in ${formatKioskAdminCountdown(remMs)}`;
    }
  }

  function touchKioskAdminActivity() {
    if (!KIOSK_ADMIN_MODAL_STATE.sessionActive) return;
    KIOSK_ADMIN_MODAL_STATE.expiresAt = Date.now() + KIOSK_ADMIN_INACTIVITY_MS;
    clearTimeout(KIOSK_ADMIN_MODAL_STATE.inactivityTimer);
    KIOSK_ADMIN_MODAL_STATE.inactivityTimer = setTimeout(() => {
      expireKioskAdminSession('inactivity');
    }, KIOSK_ADMIN_INACTIVITY_MS);
    updateKioskAdminCountdownDom();
  }

  function wireKioskAdminActivityListenersOnce() {
    if (KIOSK_ADMIN_MODAL_STATE.activityWired || typeof window === 'undefined') return;
    KIOSK_ADMIN_MODAL_STATE.activityWired = true;
    const onAct = () => {
      if (KIOSK_ADMIN_MODAL_STATE.sessionActive) {
        touchKioskAdminActivity();
      }
    };
    ['pointerdown', 'touchstart', 'keydown', 'wheel', 'click'].forEach(ev => {
      window.addEventListener(ev, onAct, { passive: true });
    });
    document.addEventListener('visibilitychange', () => {
      if (!KIOSK_ADMIN_MODAL_STATE.sessionActive) return;
      if (Date.now() >= KIOSK_ADMIN_MODAL_STATE.expiresAt) {
        expireKioskAdminSession('inactivity');
      } else {
        updateKioskAdminCountdownDom();
      }
    });
  }

  function startOrResetKioskAdminSession(adminName = '', verifiedUserObj = null, sessionRole = '') {
    wireKioskAdminActivityListenersOnce();
    const resolvedSeat = verifiedUserObj
      || (adminName ? resolveIsabiSeatForFaceEntry({ name: adminName }) : null)
      || KIOSK_ADMIN_MODAL_STATE.verifiedUser
      || activeUser();
    const effRole = sessionRole
      || (isAuthorizedKioskAdminFace({ name: adminName || (resolvedSeat && resolvedSeat.full_name), email: resolvedSeat && resolvedSeat.email, role: resolvedSeat && resolvedSeat.role }) ? 'admin' : 'entry');
    KIOSK_ADMIN_MODAL_STATE.sessionActive = true;
    KIOSK_ADMIN_MODAL_STATE.sessionRole = effRole;
    KIOSK_ADMIN_MODAL_STATE.unlocked = (effRole === 'admin');
    if (resolvedSeat) KIOSK_ADMIN_MODAL_STATE.verifiedUser = resolvedSeat;
    if (adminName) KIOSK_ADMIN_MODAL_STATE.verifiedAdmin = adminName;
    else if (resolvedSeat && resolvedSeat.full_name) KIOSK_ADMIN_MODAL_STATE.verifiedAdmin = resolvedSeat.full_name;
    if (['sales', 'raw', 'fuel', 'attendance'].includes(STATE.activeKiosk)) {
      KIOSK_ADMIN_MODAL_STATE.originKioskTab = STATE.activeKiosk;
    }
    touchKioskAdminActivity();
    if (!KIOSK_ADMIN_MODAL_STATE.countdownTicker && typeof window !== 'undefined') {
      KIOSK_ADMIN_MODAL_STATE.countdownTicker = setInterval(updateKioskAdminCountdownDom, 1000);
    }
  }

  function clearKioskAdminTimers() {
    clearTimeout(KIOSK_ADMIN_MODAL_STATE.inactivityTimer);
    KIOSK_ADMIN_MODAL_STATE.inactivityTimer = null;
    clearInterval(KIOSK_ADMIN_MODAL_STATE.countdownTicker);
    KIOSK_ADMIN_MODAL_STATE.countdownTicker = null;
  }

  function stopKioskAdminFaceCamera(keepSharedStream = false) {
    KIOSK_ADMIN_MODAL_STATE.camActive = false;
    clearTimeout(KIOSK_ADMIN_MODAL_STATE.loopTimer);
    KIOSK_ADMIN_MODAL_STATE.loopTimer = null;
    KIOSK_ADMIN_MODAL_STATE.busy = false;
    KIOSK_ADMIN_MODAL_STATE.streakAdmin = '';
    KIOSK_ADMIN_MODAL_STATE.streakCount = 0;
    KIOSK_ADMIN_MODAL_STATE.streakVecs = [];
    KIOSK_ADMIN_MODAL_STATE.streakStartedAt = 0;
    KIOSK_ADMIN_MODAL_STATE.livenessHistory = [];
    KIOSK_ADMIN_MODAL_STATE.lastPadResult = null;
    const v = $('ksaAdminFaceVideo');
    if (v && v.srcObject) {
      if (!keepSharedStream) {
        try { v.srcObject.getTracks().forEach(t => t.stop()); } catch (_) {}
      }
      v.srcObject = null;
      try { v.pause(); } catch (_) {}
    }
    if (!keepSharedStream && FACE_STATE.stream) {
      try { FACE_STATE.stream.getTracks().forEach(t => t.stop()); } catch (_) {}
      FACE_STATE.stream = null;
    }
  }

  function syncKioskAdminFaceDomInPlace() {
    const hintEl = $('ksaFaceHint');
    if (hintEl) {
      const msg = KIOSK_ADMIN_MODAL_STATE.err || KIOSK_ADMIN_MODAL_STATE.statusText || 'Look at the camera to verify Admin or Manager Face ID.';
      const cls = KIOSK_ADMIN_MODAL_STATE.err ? 'warn' : (KIOSK_ADMIN_MODAL_STATE.statusCls || '');
      hintEl.className = 'kiosk-pin-hint' + (cls ? ' ' + cls : '');
      hintEl.textContent = msg;
    }
    const badgeEl = $('ksaFaceLiveBadge');
    if (badgeEl) {
      badgeEl.className = 'badge ' + (KIOSK_ADMIN_MODAL_STATE.camActive ? 'badge-ok' : '');
      badgeEl.textContent = KIOSK_ADMIN_MODAL_STATE.camActive ? 'Live Admin Scanner' : 'Camera Ready';
    }
    const vp = $('ksaFaceViewport');
    if (vp) {
      vp.classList.toggle('is-live', !!KIOSK_ADMIN_MODAL_STATE.camActive);
      vp.classList.toggle('is-standby', !KIOSK_ADMIN_MODAL_STATE.camActive);
    }
  }

  function getKioskFacePoolWithAdminSeed() {
    const pool = usableFaces(null, { includeKioskStaff: true });
    const seedKeys = Object.keys(DEFAULT_FACE_SEEDS || {});
    const seedKey = seedKeys[0] || '';
    const seed = seedKey ? DEFAULT_FACE_SEEDS[seedKey] : null;
    const ownerRef = DEFAULT_USERS[0] || DEMO_SANDBOX_USERS[0];
    if (seed && Array.isArray(seed.face_samples) && seed.face_samples.length) {
      const hasOwner = pool.some(p => p && (String(p.id) === 'u1' || norm(p.email) === norm(seedKey) || (ownerRef && norm(p.name) === norm(ownerRef.full_name))) && Array.isArray(p.samples) && p.samples.length);
      if (!hasOwner) {
        pool.unshift({
          id: 'u1',
          email: (ownerRef && ownerRef.email) || seedKey,
          name: (ownerRef && ownerRef.full_name) || 'Workspace Owner',
          role: 'Owner',
          companies: 'WTC, BBConstruction, Lions Transport, Bdeir Holding',
          samples: seed.face_samples.map(s => s.slice())
        });
      }
    }
    return pool;
  }

  function handleKioskAdminFaceDescriptor(det, opts = {}) {
    if (det && det.modelLoading && !det.descriptor) {
      KIOSK_ADMIN_MODAL_STATE.missedFrames = 0;
      return { ok: false, reason: 'model-loading' };
    }
    const resetKsaFaceAccumulators = () => {
      KIOSK_ADMIN_MODAL_STATE.streakAdmin = '';
      KIOSK_ADMIN_MODAL_STATE.streakCount = 0;
      KIOSK_ADMIN_MODAL_STATE.streakVecs = [];
      KIOSK_ADMIN_MODAL_STATE.streakStartedAt = 0;
      KIOSK_ADMIN_MODAL_STATE.livenessHistory = [];
      KIOSK_ADMIN_MODAL_STATE.lastPadResult = null;
      KIOSK_ADMIN_MODAL_STATE.edgeVerifyBusy = false;
    };
    if (!det || !det.descriptor) {
      KIOSK_ADMIN_MODAL_STATE.missedFrames = (KIOSK_ADMIN_MODAL_STATE.missedFrames || 0) + 1;
      if (!opts.liveVideo || KIOSK_ADMIN_MODAL_STATE.missedFrames >= 3) {
        resetKsaFaceAccumulators();
      }
      if (!KIOSK_ADMIN_MODAL_STATE.err) {
        KIOSK_ADMIN_MODAL_STATE.statusText = 'Position Admin or Manager face inside the oval guide';
        KIOSK_ADMIN_MODAL_STATE.statusCls = '';
        syncKioskAdminFaceDomInPlace();
      }
      return { ok: false, reason: 'no-face' };
    }
    KIOSK_ADMIN_MODAL_STATE.missedFrames = 0;
    const hasLivePixels = hasLiveVideoPixels(opts);
    const enforceLiveVideo = hasLivePixels || Boolean(opts && opts.videoEl);
    const shouldEvalLiveness = !opts.instant && STATE.faceSettings.liveness !== false && (enforceLiveVideo || Boolean(det.landmarks || typeof det.ear === 'number' || (det.pose && typeof det.pose === 'object')));
    const needFrames = opts.instant ? 1 : (enforceLiveVideo ? 4 : (opts.liveVideo ? 3 : 2));
    const minSpanMs = (!opts.instant && enforceLiveVideo) ? 600 : 0;
    const evalKsaLivenessOrPad = () => {
      if (shouldEvalLiveness) {
        return recordAndEvalFaceLiveness(KIOSK_ADMIN_MODAL_STATE, det, opts, { minFrames: needFrames, minSpanMs });
      }
      if (!opts.instant && hasLivePixels && window.Face && typeof window.Face.analyzePad === 'function') {
        const padOnly = window.Face.analyzePad(opts.videoEl, det);
        KIOSK_ADMIN_MODAL_STATE.lastPadResult = padOnly;
        if (padOnly && padOnly.frameSpoof) {
          return { ok: false, spoofSuspected: true, reason: 'pad_spoof', padReasons: padOnly.reasons || [] };
        }
      }
      return { ok: true, spoofSuspected: false };
    };

    const completeKioskAdminUnlock = (matchedSeat, fallbackName, isFullAdmin, isEnrolAllowed, preVerifiedEdge = false) => {
      if (!isEnrolAllowed) {
        resetKsaFaceAccumulators();
        KIOSK_ADMIN_MODAL_STATE.err = matchedSeat
          ? `Access denied: ${fallbackName} (${matchedSeat.role || 'Viewer'}) is not authorized for Station Admin or Staff Enrolment.`
          : `Access denied: ${fallbackName} is a company employee, not an ISABI Entry or Admin user. Only ISABI Entry Operators, Supervisors, or Admins can enrol staff.`;
        KIOSK_ADMIN_MODAL_STATE.statusText = KIOSK_ADMIN_MODAL_STATE.err;
        KIOSK_ADMIN_MODAL_STATE.statusCls = 'warn';
        syncKioskAdminFaceDomInPlace();
        const card = document.querySelector('#kioskStationAdminModal .ksa-modal-card');
        if (card) { card.classList.remove('shake'); void card.offsetWidth; card.classList.add('shake'); }
        return { ok: false, reason: 'not-admin', isEmployeeOnly: !matchedSeat, staff: fallbackName };
      }
      const effSeat = matchedSeat || activeUser();
      const adminName = (effSeat && effSeat.full_name) || fallbackName;
      if (!opts.instant && !preVerifiedEdge) {
        const curVec = Array.from(det.descriptor);
        if (KIOSK_ADMIN_MODAL_STATE.streakAdmin === adminName) {
          KIOSK_ADMIN_MODAL_STATE.streakCount += 1;
          if (!KIOSK_ADMIN_MODAL_STATE.streakStartedAt) KIOSK_ADMIN_MODAL_STATE.streakStartedAt = Date.now();
          KIOSK_ADMIN_MODAL_STATE.streakVecs.push(curVec);
          if (KIOSK_ADMIN_MODAL_STATE.streakVecs.length > 8) {
            KIOSK_ADMIN_MODAL_STATE.streakVecs = KIOSK_ADMIN_MODAL_STATE.streakVecs.slice(-8);
          }
          if (window.Face && typeof window.Face.checkDescriptorStability === 'function' && !window.Face.checkDescriptorStability(KIOSK_ADMIN_MODAL_STATE.streakVecs, 0.26)) {
            KIOSK_ADMIN_MODAL_STATE.streakCount = 1;
            KIOSK_ADMIN_MODAL_STATE.streakVecs = [curVec];
            KIOSK_ADMIN_MODAL_STATE.streakStartedAt = Date.now();
            KIOSK_ADMIN_MODAL_STATE.livenessHistory = [];
          }
        } else {
          KIOSK_ADMIN_MODAL_STATE.streakAdmin = adminName;
          KIOSK_ADMIN_MODAL_STATE.streakCount = 1;
          KIOSK_ADMIN_MODAL_STATE.streakVecs = [curVec];
          KIOSK_ADMIN_MODAL_STATE.streakStartedAt = Date.now();
          KIOSK_ADMIN_MODAL_STATE.livenessHistory = [];
        }
        const lv = evalKsaLivenessOrPad();
        if (lv && lv.spoofSuspected) {
          KIOSK_ADMIN_MODAL_STATE.streakAdmin = '';
          KIOSK_ADMIN_MODAL_STATE.streakCount = 0;
          KIOSK_ADMIN_MODAL_STATE.streakVecs = [];
          KIOSK_ADMIN_MODAL_STATE.streakStartedAt = 0;
          KIOSK_ADMIN_MODAL_STATE.err = faceTr('Screen or photo detected. Look directly at the camera.');
          KIOSK_ADMIN_MODAL_STATE.statusText = KIOSK_ADMIN_MODAL_STATE.err;
          KIOSK_ADMIN_MODAL_STATE.statusCls = 'warn';
          syncKioskAdminFaceDomInPlace();
          return { ok: false, reason: 'spoof-detected', padReasons: lv.padReasons || [] };
        }
        const elapsedOk = !minSpanMs || ((Date.now() - (KIOSK_ADMIN_MODAL_STATE.streakStartedAt || Date.now())) >= minSpanMs);
        if (KIOSK_ADMIN_MODAL_STATE.streakCount < needFrames || !elapsedOk) {
          KIOSK_ADMIN_MODAL_STATE.err = '';
          KIOSK_ADMIN_MODAL_STATE.statusText = isFullAdmin ? `Verifying Admin ${adminName}...` : `Verifying Entry Operator ${adminName}...`;
          KIOSK_ADMIN_MODAL_STATE.statusCls = 'ok';
          syncKioskAdminFaceDomInPlace();
          return { ok: false, reason: 'building-streak', streak: KIOSK_ADMIN_MODAL_STATE.streakCount, needFrames, admin: adminName, role: isFullAdmin ? 'admin' : 'entry' };
        }
        if (shouldEvalLiveness && !(lv && lv.ok)) {
          KIOSK_ADMIN_MODAL_STATE.streakCount = needFrames - 1;
          KIOSK_ADMIN_MODAL_STATE.err = '';
          KIOSK_ADMIN_MODAL_STATE.statusText = faceTr('Hold naturally in front of the camera');
          KIOSK_ADMIN_MODAL_STATE.statusCls = 'ok';
          syncKioskAdminFaceDomInPlace();
          return { ok: false, reason: 'awaiting-liveness', streak: KIOSK_ADMIN_MODAL_STATE.streakCount, needFrames, admin: adminName, role: isFullAdmin ? 'admin' : 'entry' };
        }
      }
      resetKsaFaceAccumulators();
      KIOSK_ADMIN_MODAL_STATE.err = '';
      const opAllowedCos = allowedCompanyNames(effSeat);
      const openEnrolDirectly = !isFullAdmin || KIOSK_ADMIN_MODAL_STATE.targetAction === 'enrol';
      KIOSK_ADMIN_MODAL_STATE.statusText = isFullAdmin
        ? `✓ Admin verified: ${adminName}`
        : `✓ Entry Operator verified: ${adminName} (${opAllowedCos.join(', ') || 'Scoped BU'})`;
      KIOSK_ADMIN_MODAL_STATE.statusCls = 'ok';
      stopKioskAdminFaceCamera(false);
      startOrResetKioskAdminSession(adminName, effSeat, isFullAdmin ? 'admin' : 'entry');
      if (openEnrolDirectly) {
        closeKioskStationAdminModal({ keepAdminSession: true, skipCameraResume: true });
        openStaffFaceEnrolModal('', { operatorUser: effSeat });
        toast(
          isFullAdmin
            ? `Verified ${adminName} · Staff Face ID & Enrolment Studio opened`
            : `Entry Operator verified: ${adminName} · Scoped to ${opAllowedCos.join(', ') || 'assigned BU'}`,
          'ok'
        );
        return { ok: true, admin: adminName, role: isFullAdmin ? 'admin' : 'entry', openedEnrolModal: true, allowedCompanies: opAllowedCos };
      }
      if (KIOSK_ADMIN_MODAL_STATE.open && typeof KIOSK_ADMIN_MODAL_STATE.renderInnerFn === 'function') {
        KIOSK_ADMIN_MODAL_STATE.renderInnerFn();
      }
      toast(`Admin verified via Face ID: ${adminName} (auto-locks after 5 min of inactivity)`, 'ok');
      return { ok: true, admin: adminName, role: 'admin', openedEnrolModal: false, allowedCompanies: opAllowedCos };
    };

    const failUnrecognized = (reason) => {
      resetKsaFaceAccumulators();
      KIOSK_ADMIN_MODAL_STATE.err = reason === 'no-pool'
        ? 'No Face ID profiles enrolled yet.'
        : (reason === 'multiple'
          ? 'Multiple faces in frame. Step into the oval guide one person at a time.'
          : (reason === 'too-small'
            ? 'Move slightly closer to the camera.'
            : 'Face not recognized. Look straight at the camera with an enrolled Admin Face ID.'));
      KIOSK_ADMIN_MODAL_STATE.statusText = KIOSK_ADMIN_MODAL_STATE.err;
      KIOSK_ADMIN_MODAL_STATE.statusCls = 'warn';
      syncKioskAdminFaceDomInPlace();
      return { ok: false, reason };
    };

    if (det.multiple) {
      return failUnrecognized('multiple');
    }
    const ksaMinFrac = Number(STATE.faceSettings.minFaceFrac || 0.14);
    if (det.faceSizeFrac != null && det.faceSizeFrac < ksaMinFrac) {
      return failUnrecognized('too-small');
    }

    const pool = getKioskFacePoolWithAdminSeed();
    if (pool.length && window.Face) {
      const m = window.Face.match(det.descriptor, pool);
      const thr = Number(STATE.faceSettings.threshold || 0.50);
      const dec = window.Face.decide(m, Object.assign({}, window.Face.CONFIG, { threshold: thr }), { faceSizeFrac: det.faceSizeFrac || 0.26 });
      if (dec.ok && dec.best) {
        const isFullAdmin = isAuthorizedKioskAdminFace(dec.best);
        const isEnrolAllowed = isFullAdmin || isAuthorizedKioskStaffEnrolFace(dec.best);
        const matchedSeat = resolveIsabiSeatForFaceEntry(dec.best);
        return completeKioskAdminUnlock(matchedSeat, dec.best.name, isFullAdmin, isEnrolAllowed, false);
      }
    }

    const canRemoteVerify = hasServerApi() && !isDemoSandboxSession() && STATE.users.some(u => u && u.status !== 'Suspended' && u.face_redacted && u.face_enrolled);
    if (canRemoteVerify) {
      if (Date.now() < (KIOSK_ADMIN_MODAL_STATE.edgeCooldownUntil || 0)) {
        return { ok: false, reason: 'cooldown' };
      }
      const rawVec = Array.from(det.descriptor);
      if (rawVec.length === 128) {
        if (!opts.instant) {
          if (KIOSK_ADMIN_MODAL_STATE.streakAdmin === '__edge_probe__') {
            KIOSK_ADMIN_MODAL_STATE.streakCount += 1;
            KIOSK_ADMIN_MODAL_STATE.streakVecs.push(rawVec);
            if (KIOSK_ADMIN_MODAL_STATE.streakVecs.length > 8) {
              KIOSK_ADMIN_MODAL_STATE.streakVecs = KIOSK_ADMIN_MODAL_STATE.streakVecs.slice(-8);
            }
            if (window.Face && typeof window.Face.checkDescriptorStability === 'function' && !window.Face.checkDescriptorStability(KIOSK_ADMIN_MODAL_STATE.streakVecs, 0.26)) {
              KIOSK_ADMIN_MODAL_STATE.streakCount = 1;
              KIOSK_ADMIN_MODAL_STATE.streakVecs = [rawVec];
              KIOSK_ADMIN_MODAL_STATE.streakStartedAt = Date.now();
              KIOSK_ADMIN_MODAL_STATE.livenessHistory = [];
            }
          } else {
            KIOSK_ADMIN_MODAL_STATE.streakAdmin = '__edge_probe__';
            KIOSK_ADMIN_MODAL_STATE.streakCount = 1;
            KIOSK_ADMIN_MODAL_STATE.streakVecs = [rawVec];
            KIOSK_ADMIN_MODAL_STATE.streakStartedAt = Date.now();
            KIOSK_ADMIN_MODAL_STATE.livenessHistory = [];
          }
          const lv = evalKsaLivenessOrPad();
          if (lv && lv.spoofSuspected) {
            KIOSK_ADMIN_MODAL_STATE.streakAdmin = '';
            KIOSK_ADMIN_MODAL_STATE.streakCount = 0;
            KIOSK_ADMIN_MODAL_STATE.streakVecs = [];
            KIOSK_ADMIN_MODAL_STATE.streakStartedAt = 0;
            KIOSK_ADMIN_MODAL_STATE.err = faceTr('Screen or photo detected. Look directly at the camera.');
            KIOSK_ADMIN_MODAL_STATE.statusText = KIOSK_ADMIN_MODAL_STATE.err;
            KIOSK_ADMIN_MODAL_STATE.statusCls = 'warn';
            syncKioskAdminFaceDomInPlace();
            return { ok: false, reason: 'spoof-detected', padReasons: lv.padReasons || [] };
          }
          const elapsedOk = !minSpanMs || ((Date.now() - (KIOSK_ADMIN_MODAL_STATE.streakStartedAt || Date.now())) >= minSpanMs);
          if (KIOSK_ADMIN_MODAL_STATE.streakCount < needFrames || !elapsedOk) {
            KIOSK_ADMIN_MODAL_STATE.err = '';
            KIOSK_ADMIN_MODAL_STATE.statusText = 'Verifying Admin Face ID...';
            KIOSK_ADMIN_MODAL_STATE.statusCls = 'ok';
            syncKioskAdminFaceDomInPlace();
            return { ok: false, reason: 'building-streak', streak: KIOSK_ADMIN_MODAL_STATE.streakCount, needFrames };
          }
          if (shouldEvalLiveness && !(lv && lv.ok)) {
            KIOSK_ADMIN_MODAL_STATE.streakCount = needFrames - 1;
            KIOSK_ADMIN_MODAL_STATE.err = '';
            KIOSK_ADMIN_MODAL_STATE.statusText = faceTr('Hold naturally in front of the camera');
            KIOSK_ADMIN_MODAL_STATE.statusCls = 'ok';
            syncKioskAdminFaceDomInPlace();
            return { ok: false, reason: 'awaiting-liveness', streak: KIOSK_ADMIN_MODAL_STATE.streakCount, needFrames };
          }
        }
        if (KIOSK_ADMIN_MODAL_STATE.edgeVerifyBusy) {
          return { ok: false, reason: 'verifying' };
        }
        KIOSK_ADMIN_MODAL_STATE.edgeVerifyBusy = true;
        const vecArr = (!opts.instant && KIOSK_ADMIN_MODAL_STATE.streakVecs.length && window.Face && typeof window.Face.averageDescriptors === 'function')
          ? (window.Face.averageDescriptors(KIOSK_ADMIN_MODAL_STATE.streakVecs) || rawVec)
          : rawVec;
        return edgeApiFetch('./api/auth/login', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ method: 'Face ID', verify_only: true, face_descriptor: vecArr })
        })
          .then(r => (r.ok ? r.json() : null))
          .then(j => {
            if (!KIOSK_ADMIN_MODAL_STATE.open || KIOSK_ADMIN_MODAL_STATE.unlocked) {
              return { ok: false, reason: 'closed' };
            }
            if (!j || !j.ok || !j.user) {
              KIOSK_ADMIN_MODAL_STATE.edgeCooldownUntil = Date.now() + 650;
              return failUnrecognized('unrecognized');
            }
            let existingIdx = STATE.users.findIndex(u => u && ((j.user.id && String(u.id) === String(j.user.id)) || norm(u.email) === norm(j.user.email)));
            if (existingIdx < 0 && j.user.email) {
              STATE.users.push(mergeUserRow(null, j.user));
              existingIdx = STATE.users.length - 1;
            } else if (existingIdx >= 0) {
              STATE.users[existingIdx] = mergeUserRow(STATE.users[existingIdx], j.user);
            }
            const matchedSeat = existingIdx >= 0 ? STATE.users[existingIdx] : j.user;
            const entry = {
              id: matchedSeat.id || j.user.id || '',
              email: matchedSeat.email || j.user.email || '',
              name: matchedSeat.full_name || j.user.full_name || 'Admin',
              role: matchedSeat.role || j.user.role || ''
            };
            const isFullAdmin = isAuthorizedKioskAdminFace(entry);
            const isEnrolAllowed = isFullAdmin || isAuthorizedKioskStaffEnrolFace(entry);
            return completeKioskAdminUnlock(matchedSeat, entry.name, isFullAdmin, isEnrolAllowed, !opts.instant);
          })
          .catch(() => {
            KIOSK_ADMIN_MODAL_STATE.edgeCooldownUntil = Date.now() + 650;
            return failUnrecognized('unrecognized');
          })
          .finally(() => {
            KIOSK_ADMIN_MODAL_STATE.edgeVerifyBusy = false;
          });
      }
    }

    return failUnrecognized(!pool.length || !window.Face ? 'no-pool' : 'unrecognized');
  }

  async function kioskAdminFaceTick() {
    if (!KIOSK_ADMIN_MODAL_STATE.open || KIOSK_ADMIN_MODAL_STATE.unlocked || !KIOSK_ADMIN_MODAL_STATE.camActive) return;
    const v = $('ksaAdminFaceVideo');
    if (v && v.srcObject !== FACE_STATE.stream && streamAlive()) {
      v.srcObject = FACE_STATE.stream;
      v.play().catch(() => {});
    }
    if (v && v.readyState >= 2 && !KIOSK_ADMIN_MODAL_STATE.busy && window.Face) {
      KIOSK_ADMIN_MODAL_STATE.busy = true;
      try {
        const det = await window.Face.detectOne(v, false);
        await handleKioskAdminFaceDescriptor(det, { liveVideo: true, videoEl: v });
      } catch (_) {}
      KIOSK_ADMIN_MODAL_STATE.busy = false;
    }
    if (KIOSK_ADMIN_MODAL_STATE.open && !KIOSK_ADMIN_MODAL_STATE.unlocked && KIOSK_ADMIN_MODAL_STATE.camActive) {
      KIOSK_ADMIN_MODAL_STATE.loopTimer = setTimeout(kioskAdminFaceTick, 85);
    }
  }

  async function startKioskAdminFaceCamera() {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      KIOSK_ADMIN_MODAL_STATE.camActive = false;
      KIOSK_ADMIN_MODAL_STATE.err = 'Camera unavailable on this browser. Admin Face ID requires a front camera.';
      KIOSK_ADMIN_MODAL_STATE.statusCls = 'warn';
      syncKioskAdminFaceDomInPlace();
      return false;
    }
    try {
      stopKioskAttCamera();
      KIOSK_ATT_STATE.standbyIdle = false;
      KIOSK_ATT_STATE.nightSleep = false;
      if (typeof document !== 'undefined' && document.body) {
        document.body.classList.remove('kiosk-idle-dimmed', 'kiosk-night-sleep');
      }
      await releaseAllKioskCameraHardware(380);
      if (!KIOSK_ADMIN_MODAL_STATE.open || KIOSK_ADMIN_MODAL_STATE.unlocked) {
        return false;
      }
      const modelsP = ensureFaceModelsLoaded();
      const stream = await requestKioskUserMediaWithTimeout({
        video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 }, frameRate: { ideal: 15, max: 20 } },
        audio: false
      }, 6000).catch(() => requestKioskUserMediaWithTimeout({
        video: { facingMode: 'user' },
        audio: false
      }, 6000));
      if (!KIOSK_ADMIN_MODAL_STATE.open || KIOSK_ADMIN_MODAL_STATE.unlocked) {
        try { stream.getTracks().forEach(t => t.stop()); } catch (_) {}
        return false;
      }
      if (window.Face && typeof window.Face.trackStream === 'function') {
        window.Face.trackStream(stream);
      }
      FACE_STATE.stream = stream;
      KIOSK_ADMIN_MODAL_STATE.camActive = true;
      KIOSK_ADMIN_MODAL_STATE.missedFrames = 0;
      KIOSK_ADMIN_MODAL_STATE.err = '';
      KIOSK_ADMIN_MODAL_STATE.statusText = 'Position Admin or Manager face inside the oval guide';
      KIOSK_ADMIN_MODAL_STATE.statusCls = 'ok';
      syncKioskAdminFaceDomInPlace();
      const v = $('ksaAdminFaceVideo');
      if (v) {
        v.srcObject = stream;
        await v.play().catch(() => {});
      }
      await modelsP;
      clearTimeout(KIOSK_ADMIN_MODAL_STATE.loopTimer);
      KIOSK_ADMIN_MODAL_STATE.loopTimer = setTimeout(kioskAdminFaceTick, 25);
      return true;
    } catch (_) {
      KIOSK_ADMIN_MODAL_STATE.camActive = false;
      KIOSK_ADMIN_MODAL_STATE.err = 'Camera permission denied or busy. Tap Restart Scanner to retry.';
      KIOSK_ADMIN_MODAL_STATE.statusCls = 'warn';
      syncKioskAdminFaceDomInPlace();
      return false;
    }
  }

  function expireKioskAdminSession(reason = 'inactivity') {
    const wasActive = Boolean(KIOSK_ADMIN_MODAL_STATE.sessionActive || KIOSK_ADMIN_MODAL_STATE.unlocked || KIOSK_ADMIN_MODAL_STATE.open);
    clearKioskAdminTimers();
    stopKioskAdminFaceCamera(false);
    KIOSK_ADMIN_MODAL_STATE.open = false;
    KIOSK_ADMIN_MODAL_STATE.unlocked = false;
    KIOSK_ADMIN_MODAL_STATE.sessionActive = false;
    KIOSK_ADMIN_MODAL_STATE.verifiedAdmin = '';
    KIOSK_ADMIN_MODAL_STATE.verifiedUser = null;
    KIOSK_ADMIN_MODAL_STATE.sessionRole = '';
    KIOSK_ADMIN_MODAL_STATE.targetAction = 'admin';
    KIOSK_ADMIN_MODAL_STATE.expiresAt = 0;
    KIOSK_ADMIN_MODAL_STATE.err = '';
    const m = $('kioskStationAdminModal');
    if (m) m.hidden = true;
    if ($('staffFaceEnrolModal') && !$('staffFaceEnrolModal').hidden) {
      stopStaffEnrolModalCamera();
      STAFF_FACE_MODAL_STATE.open = false;
      STAFF_FACE_MODAL_STATE.operatorUser = null;
      STAFF_FACE_MODAL_STATE.newStaffOpen = false;
      $('staffFaceEnrolModal').hidden = true;
    }
    document.body.classList.remove('modal-open', 'kiosk-idle-dimmed', 'kiosk-night-sleep');
    const targetKiosk = ['sales', 'raw', 'fuel', 'attendance'].includes(STATE.activeKiosk)
      ? STATE.activeKiosk
      : (KIOSK_ADMIN_MODAL_STATE.originKioskTab || 'attendance');
    STATE.activeKiosk = targetKiosk;
    STATE.view = 'kiosks';
    STATE.kioskLocked = true;
    STATE.kioskUnlockPromptOpen = false;
    document.body.classList.add('kiosk-locked');
    saveKioskStationConfig({ activeKiosk: targetKiosk, kioskLocked: true });
    syncNativeStationPreset(targetKiosk);
    syncKioskLockedUrl();
    renderApp();
    if (targetKiosk === 'attendance') {
      KIOSK_ATT_STATE.camPausedByUser = false;
      KIOSK_ATT_STATE.standbyIdle = false;
      KIOSK_ATT_STATE.nightSleep = false;
      KIOSK_ATT_STATE.lastActivityAt = Date.now();
      ensureLockedWallCameraRunning();
    }
    if (wasActive) {
      toast(
        reason === 'inactivity'
          ? 'Admin session logged out after 5 minutes of inactivity. Kiosk locked.'
          : 'Admin logged out. Kiosk locked.',
        'ok'
      );
    }
    return { ok: true, reason, locked: true, activeKiosk: targetKiosk };
  }

  function formatKioskWallClockNow() {
    const d = new Date();
    const pad = n => String(n).padStart(2, '0');
    const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return {
      time: `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`,
      date: `${days[d.getDay()]}, ${pad(d.getDate())} ${months[d.getMonth()]}`
    };
  }

  function ensureKioskWallClockTicker() {
    if (KIOSK_ATT_STATE.wallClockTimer || typeof window === 'undefined') return;
    wireKioskAttIdleWakeOnce();
    KIOSK_ATT_STATE.wallClockTimer = setInterval(() => {
      const nowDt = new Date();
      const now = nowDt.getTime();
      const parts = formatKioskWallClockNow();
      const elTime = $('kioskWallClockTime');
      const elDate = $('kioskWallClockDate');
      if (elTime && elTime.textContent !== parts.time) elTime.textContent = parts.time;
      if (elDate && elDate.textContent !== parts.date) elDate.textContent = parts.date;

      const idleTimeEl = $('kioskIdleClockTime');
      const idleDateEl = $('kioskIdleClockDate');
      if (idleTimeEl) {
        const hhmm = parts.time.slice(0, 5);
        if (idleTimeEl.textContent !== hhmm) idleTimeEl.textContent = hhmm;
      }
      if (idleDateEl) {
        const dTxt = `${parts.date} · ${STATE.kioskAttSite || 'Main Station'}`;
        if (idleDateEl.textContent !== dTxt) idleDateEl.textContent = dTxt;
      }
      const idleCardEl = $('kioskIdleStandbyCard');
      if (idleCardEl) {
        // Gentle pixel-shift orbit every minute (-4px..+4px) to prevent LCD image retention on 24/7 wall tablets
        const minIdx = nowDt.getHours() * 60 + nowDt.getMinutes();
        const dx = ((minIdx % 5) - 2) * 2;
        const dy = (((Math.floor(minIdx / 5)) % 5) - 2) * 2;
        idleCardEl.style.transform = `translate(${dx}px, ${dy}px)`;
      }

      if (navigator.webdriver || window.__MFG_HEADLESS_TEST || IS_AUTOMATED_TEST) return;

      const modalEnrolOpen = Boolean($('staffFaceEnrolModal') && !$('staffFaceEnrolModal').hidden);
      const hasActiveFlash = Boolean(KIOSK_ATT_STATE.flashPunch && KIOSK_ATT_STATE.flashPunch.expiresAt > now);

      // 1. Scheduled Daily 05:25 AM Self-Healing Clean Reload (resets WebView V8 heap, WebGL & Camera2 before morning shift)
      if (
        STATE.kioskLocked &&
        STATE.view === 'kiosks' &&
        !KIOSK_ADMIN_MODAL_STATE.open &&
        !modalEnrolOpen &&
        !hasActiveFlash &&
        !KIOSK_ATT_STATE.streakCount &&
        !KIOSK_ATT_STATE.busy &&
        nowDt.getHours() === 5 &&
        nowDt.getMinutes() >= 25 &&
        nowDt.getMinutes() <= 45 &&
        typeof performance !== 'undefined' &&
        performance.now() > 120000
      ) {
        try {
          const todayKey = todayISO();
          if (localStorage.getItem('isabi_mfg_kiosk_last_daily_reload') !== todayKey) {
            localStorage.setItem('isabi_mfg_kiosk_last_daily_reload', todayKey);
            stashKioskSwResumeAndReload();
            return;
          }
        } catch (_) {}
      }

      // 2. Background 60s OTA Version Poller (auto-pulls new deployments when wall terminal is idle)
      if (
        STATE.kioskLocked &&
        STATE.view === 'kiosks' &&
        !KIOSK_ADMIN_MODAL_STATE.open &&
        !modalEnrolOpen &&
        !hasActiveFlash &&
        !KIOSK_ATT_STATE.streakCount &&
        (now - (KIOSK_ATT_STATE.lastVersionPollAt || 0) >= 60000)
      ) {
        KIOSK_ATT_STATE.lastVersionPollAt = now;
        checkAndApplyKioskOtaUpdate({ silent: true }).catch(() => {});
      }

      // 3. Attendance Wall Camera Supervisor & Configurable Power Saver / Night Deep Sleep
      if (
        STATE.view === 'kiosks' &&
        STATE.activeKiosk === 'attendance' &&
        (STATE.kioskLocked || KIOSK_ATT_STATE.camActive) &&
        !KIOSK_ATT_STATE.camPausedByUser &&
        !KIOSK_ADMIN_MODAL_STATE.open &&
        !modalEnrolOpen
      ) {
        if (STATE.kioskLocked && KIOSK_ATT_STATE.standbyIdle) {
          const nightNow = isKioskNightOffShiftNow(nowDt);
          if (nightNow !== !!KIOSK_ATT_STATE.nightSleep) {
            KIOSK_ATT_STATE.nightSleep = nightNow;
            document.body.classList.toggle('kiosk-night-sleep', nightNow);
            if (!nightNow && Number(STATE.kioskIdleStandbySec != null ? STATE.kioskIdleStandbySec : 60) === 0) {
              wakeKioskAttFromStandby();
              return;
            }
            syncKioskAttLiveUiInPlace();
          }
          return;
        }

        if (STATE.kioskLocked) {
          const effIdleMs = getEffectiveKioskIdleStandbyMs(nowDt);
          const lastAct = KIOSK_ATT_STATE.lastActivityAt || now;
          if (
            effIdleMs > 0 &&
            !hasActiveFlash &&
            !KIOSK_ATT_STATE.streakCount &&
            !KIOSK_ATT_STATE.camStarting &&
            (now - lastAct) >= effIdleMs
          ) {
            enterKioskAttIdleStandby(isKioskNightOffShiftNow(nowDt) ? 'night' : 'idle');
            return;
          }
        }

        if (KIOSK_ATT_STATE.camStarting && (now - (KIOSK_ATT_STATE.camStartingSince || 0) > 8500)) {
          KIOSK_ATT_STATE.camStarting = false;
        }
        if (!KIOSK_ATT_STATE.camStarting && !KIOSK_ATT_STATE.watchdogTimer) {
          if (!KIOSK_ATT_STATE.camActive || !streamAlive()) {
            scheduleKioskAttCameraWatchdogRestart('clock-supervisor-inactive');
          } else if (!KIOSK_ATT_STATE.loopTimer && !KIOSK_ATT_STATE.busy) {
            KIOSK_ATT_STATE.loopTimer = setTimeout(kioskAttFaceTick, 60);
          } else if (KIOSK_ATT_STATE.lastTimeMoveAt > 0 && (now - KIOSK_ATT_STATE.lastTimeMoveAt > 12000) && !KIOSK_ATT_STATE.busy) {
            scheduleKioskAttCameraWatchdogRestart('clock-supervisor-stale');
          }
        }
      }
    }, 1000);
  }

  function buildKioskWallFlashBannerHtml(activeFlash) {
    if (!STATE.kioskLocked || !activeFlash || !activeFlash.punch) return '';
    const isRepeat = Boolean(activeFlash.alreadyClocked || activeFlash.alreadyClockedIn || activeFlash.reason === 'debounced' || activeFlash.reason === 'already-clocked-in-recent');
    const dir = activeFlash.punch.direction === 'OUT' ? 'OUT' : 'IN';
    const badgeHtml = isRepeat
      ? `${ic('check_circle')} Already Clocked ${dir}`
      : (dir === 'IN' ? `${ic('clock_in')} Clocked IN` : `${ic('clock_out')} Clocked OUT`);
    const timeMetaHtml = isRepeat
      ? `Since ${esc(activeFlash.punch.time)}${activeFlash.ageText ? ' (' + esc(activeFlash.ageText) + ')' : ''}`
      : (dir === 'OUT' && activeFlash.punch.in_time
        ? `IN ${esc(activeFlash.punch.in_time)} · OUT ${esc(activeFlash.punch.time)}`
        : esc(activeFlash.punch.time));
    const showEarlyOutBtn = Boolean((activeFlash.alreadyClockedIn || activeFlash.reason === 'already-clocked-in-recent') && dir === 'IN');
    return `
      <div class="kiosk-wall-flash-banner ${dir === 'IN' ? 'is-in' : 'is-out'}" id="kioskWallFlashBanner">
        <div class="kwf-left">
          <span class="badge ${dir === 'IN' ? 'badge-ok' : 'badge-warn'}">
            ${badgeHtml}
          </span>
          <div class="kwf-info">
            <strong>${esc(activeFlash.staff)}</strong>
            <span class="kwf-meta">
              <span class="mono">${timeMetaHtml}</span>
              · ${esc(activeFlash.punch.site)}
            </span>
          </div>
        </div>
        <div class="kwf-actions">
          ${showEarlyOutBtn ? `
            <button type="button" class="btn kiosk-flip-btn" data-force-early-out="${esc(activeFlash.staff)}" data-force-early-time="${esc(activeFlash.attemptedTime || '')}">
              ${ic('clock_out')} Clock OUT Early
            </button>
          ` : `
            <button type="button" class="btn kiosk-flip-btn" data-flip-punch="${esc(activeFlash.punch.id)}">
              ${ic('swap')} Switch to ${dir === 'IN' ? 'OUT' : 'IN'}
            </button>
          `}
          <button type="button" class="btn kiosk-mini-btn" id="kioskDismissFlashBtn">Done</button>
        </div>
      </div>
    `;
  }

  function wireKioskWallFlashBannerEvents(bannerEl) {
    if (!bannerEl) return;
    bannerEl.querySelector('#kioskDismissFlashBtn')?.addEventListener('click', e => {
      e.stopPropagation();
      clearKioskFlashPunch(true);
    });
    bannerEl.querySelectorAll('[data-flip-punch]').forEach(fBtn => {
      fBtn.addEventListener('click', e => {
        e.stopPropagation();
        flipKioskPunchDirection(fBtn.getAttribute('data-flip-punch'));
      });
    });
    bannerEl.querySelectorAll('[data-force-early-out]').forEach(eBtn => {
      eBtn.addEventListener('click', e => {
        e.stopPropagation();
        const stf = eBtn.getAttribute('data-force-early-out') || '';
        const tStr = eBtn.getAttribute('data-force-early-time') || '';
        if (!stf) return;
        recordKioskAttendancePunch({
          staff: stf,
          direction: 'OUT',
          time: tStr || undefined,
          method: 'Face ID',
          bypassDebounce: true,
          forceEarlyOut: true
        });
      });
    });
  }

  function syncKioskAttLiveUiInPlace() {
    const stEl = $('kioskAttCamStatus');
    if (stEl) {
      stEl.textContent = KIOSK_ATT_STATE.statusText || '';
      stEl.className = 'kiosk-att-status' + (KIOSK_ATT_STATE.statusCls ? ' ' + KIOSK_ATT_STATE.statusCls : '');
    }
    const badgeEl = $('kioskAttLiveBadge') || document.querySelector('.kiosk-att-cam-card .panel-head .badge');
    if (badgeEl) {
      if (KIOSK_ATT_STATE.camActive && (KIOSK_ATT_STATE.blackFrameStreak || 0) >= 4) {
        badgeEl.className = 'badge badge-warn';
        badgeEl.textContent = 'Reconnecting Camera...';
      } else if (KIOSK_ATT_STATE.camActive) {
        badgeEl.className = 'badge badge-ok';
        badgeEl.textContent = 'Live Camera';
      } else if (KIOSK_ATT_STATE.standbyIdle) {
        badgeEl.className = 'badge';
        badgeEl.textContent = KIOSK_ATT_STATE.nightSleep ? 'Night Sleep · Tap to Wake' : 'Power Saver · Tap to Wake';
      } else if (STATE.kioskLocked) {
        badgeEl.className = 'badge';
        badgeEl.textContent = KIOSK_ATT_STATE.camStarting ? 'Starting Camera...' : 'Tap to Start';
      }
    }
    const vpEl = $('kioskAttViewport');
    if (vpEl) {
      vpEl.classList.toggle('is-live', !!KIOSK_ATT_STATE.camActive);
      vpEl.classList.toggle('is-standby', !KIOSK_ATT_STATE.camActive);
      vpEl.classList.toggle('is-idle-saver', !!KIOSK_ATT_STATE.standbyIdle && !KIOSK_ATT_STATE.camActive);
      if (KIOSK_ATT_STATE.camActive) {
        vpEl.querySelectorAll('.kiosk-cam-standby-card').forEach(c => c.remove());
      } else if (KIOSK_ATT_STATE.standbyIdle) {
        const html = buildKioskIdleStandbyCardHtml();
        const tpl = document.createElement('template');
        tpl.innerHTML = html.trim();
        const nextCard = tpl.content.firstElementChild;
        if (nextCard) {
          const prevCards = vpEl.querySelectorAll('.kiosk-cam-standby-card');
          if (prevCards.length === 1 && prevCards[0].id === 'kioskIdleStandbyCard') {
            prevCards[0].replaceWith(nextCard);
          } else {
            prevCards.forEach(c => c.remove());
            vpEl.appendChild(nextCard);
          }
        }
      }
    }
    const wsShell = $('kioskAttendanceWorkspace');
    if (!wsShell) return false;
    const activeFlash = (KIOSK_ATT_STATE.flashPunch && KIOSK_ATT_STATE.flashPunch.punch && KIOSK_ATT_STATE.flashPunch.expiresAt > Date.now())
      ? KIOSK_ATT_STATE.flashPunch
      : null;
    const existingBanner = $('kioskWallFlashBanner');
    if (STATE.kioskLocked && activeFlash) {
      const html = buildKioskWallFlashBannerHtml(activeFlash);
      const tpl = document.createElement('template');
      tpl.innerHTML = html.trim();
      const nextBanner = tpl.content.firstElementChild;
      if (nextBanner) {
        if (existingBanner) {
          existingBanner.replaceWith(nextBanner);
        } else {
          wsShell.prepend(nextBanner);
        }
        wireKioskWallFlashBannerEvents(nextBanner);
      }
    } else if (existingBanner) {
      existingBanner.remove();
    }
    return true;
  }

  function clearKioskFlashPunch(reRender = true) {
    clearTimeout(KIOSK_ATT_STATE.flashTimer);
    KIOSK_ATT_STATE.flashTimer = null;
    KIOSK_ATT_STATE.flashPunch = null;
    KIOSK_ATT_STATE.lastActivityAt = Date.now();
    const b = $('kioskWallFlashBanner');
    if (b) b.remove();
    if (reRender && STATE.view === 'kiosks' && !(STATE.kioskLocked || KIOSK_ATT_STATE.camActive)) {
      renderApp();
    }
  }

  function setKioskFlashPunch(spec = {}) {
    clearTimeout(KIOSK_ATT_STATE.flashTimer);
    const ttlMs = Number(spec.ttlMs || 5500);
    KIOSK_ATT_STATE.lastActivityAt = Date.now();
    KIOSK_ATT_STATE.flashPunch = Object.assign({}, spec, {
      expiresAt: Date.now() + ttlMs
    });
    KIOSK_ATT_STATE.flashTimer = setTimeout(() => {
      KIOSK_ATT_STATE.flashTimer = null;
      KIOSK_ATT_STATE.flashPunch = null;
      KIOSK_ATT_STATE.lastActivityAt = Date.now();
      if (STATE.view === 'kiosks' && STATE.activeKiosk === 'attendance') {
        const b = $('kioskWallFlashBanner');
        if (b) b.remove();
      }
    }, ttlMs);
  }

  function ensureLockedWallCameraRunning() {
    if (typeof window === 'undefined') return;
    if (navigator.webdriver || window.__MFG_HEADLESS_TEST) return;
    if (!STATE.authed || STATE.view !== 'kiosks' || STATE.activeKiosk !== 'attendance' || !STATE.kioskLocked) return;
    if (KIOSK_ADMIN_MODAL_STATE.open) return;
    if (KIOSK_ATT_STATE.standbyIdle) return;
    if ((KIOSK_ATT_STATE.camActive && streamAlive()) || KIOSK_ATT_STATE.camStarting || KIOSK_ATT_STATE.camPausedByUser) return;
    if ($('staffFaceEnrolModal') && !$('staffFaceEnrolModal').hidden) return;
    clearTimeout(KIOSK_ATT_STATE.ensureTimer);
    KIOSK_ATT_STATE.ensureTimer = setTimeout(() => {
      KIOSK_ATT_STATE.ensureTimer = null;
      if (STATE.authed && STATE.view === 'kiosks' && STATE.activeKiosk === 'attendance' && STATE.kioskLocked && !KIOSK_ADMIN_MODAL_STATE.open && !KIOSK_ATT_STATE.standbyIdle && !(KIOSK_ATT_STATE.camActive && streamAlive()) && !KIOSK_ATT_STATE.camStarting && !KIOSK_ATT_STATE.camPausedByUser) {
        startKioskAttCamera();
      }
    }, 90);
  }

  function resolveKioskFormType() {
    if (STATE.activeKiosk === 'raw') return 'raw';
    if (STATE.activeKiosk === 'fuel') return STATE.kioskFuelSubmode === 'refill' ? 'expense' : (STATE.kioskFuelSubmode === 'malfunction' ? 'malfunction' : 'fuel');
    if (STATE.activeKiosk === 'attendance') return 'attendance';
    return 'sales';
  }

  function setKioskLockMode(locked, authArg) {
    if (!locked && STATE.kioskLocked) {
      let faceVerified = Boolean(KIOSK_ADMIN_MODAL_STATE.sessionActive && KIOSK_ADMIN_MODAL_STATE.unlocked);
      if (!faceVerified && Array.isArray(authArg) && authArg.length === 128 && window.Face) {
        const pool = getKioskFacePoolWithAdminSeed();
        const m = window.Face.match(authArg, pool);
        const thr = Number(STATE.faceSettings.threshold || 0.50);
        const dec = window.Face.decide(m, Object.assign({}, window.Face.CONFIG, { threshold: thr }), { faceSizeFrac: 0.26 });
        if (dec.ok && dec.best && isAuthorizedKioskAdminFace(dec.best)) {
          startOrResetKioskAdminSession(dec.best.name);
          faceVerified = true;
        }
      }
      if (!faceVerified) {
        toast('Admin Face ID verification is required to unlock Station Mode', 'err');
        return false;
      }
    }
    if (locked) {
      clearKioskAdminTimers();
      KIOSK_ADMIN_MODAL_STATE.sessionActive = false;
      KIOSK_ADMIN_MODAL_STATE.unlocked = false;
      KIOSK_ADMIN_MODAL_STATE.verifiedAdmin = '';
      KIOSK_ADMIN_MODAL_STATE.expiresAt = 0;
    } else if (!KIOSK_ADMIN_MODAL_STATE.sessionActive) {
      startOrResetKioskAdminSession(activeUser().full_name || 'Admin');
    }
    STATE.kioskLocked = !!locked;
    STATE.kioskUnlockPromptOpen = false;
    document.body.classList.toggle('kiosk-locked', STATE.kioskLocked);
    if (!STATE.kioskLocked) {
      document.documentElement.classList.remove('kiosk-prelock');
    }
    if (STATE.kioskLocked && STATE.view !== 'kiosks') {
      STATE.view = 'kiosks';
    }
    if (STATE.kioskLocked && STATE.authed && !IS_DEMO && !STATE.demoVisitor && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
      const u = activeUser();
      if (u && u.email) {
        try { localStorage.setItem('isabi_mfg_kiosk_station_seat', JSON.stringify({ email: u.email, ts: Date.now() })); } catch (_) {}
      }
    }
    saveKioskStationConfig({ kioskLocked: STATE.kioskLocked });
    syncNativeStationPreset(STATE.kioskLocked ? STATE.activeKiosk : 'command');
    syncKioskLockedUrl();
    renderApp();
    if (STATE.kioskLocked && STATE.activeKiosk === 'attendance') {
      KIOSK_ATT_STATE.camPausedByUser = false;
      ensureLockedWallCameraRunning();
    }
    toast(STATE.kioskLocked
      ? 'Station Mode active: back-office menus hidden for dedicated counter or wall use'
      : 'Station Mode unlocked via Admin Face ID (auto-locks after 5 min of inactivity)', 'ok');
    return true;
  }

  function closeKioskStationAdminModal(opts = {}) {
    stopKioskAdminFaceCamera(false);
    KIOSK_ADMIN_MODAL_STATE.open = false;
    KIOSK_ADMIN_MODAL_STATE.err = '';
    if (STATE.kioskLocked && !opts.keepAdminSession) {
      clearKioskAdminTimers();
      KIOSK_ADMIN_MODAL_STATE.unlocked = false;
      KIOSK_ADMIN_MODAL_STATE.sessionActive = false;
      KIOSK_ADMIN_MODAL_STATE.verifiedAdmin = '';
      KIOSK_ADMIN_MODAL_STATE.verifiedUser = null;
      KIOSK_ADMIN_MODAL_STATE.sessionRole = '';
      KIOSK_ADMIN_MODAL_STATE.targetAction = 'admin';
      KIOSK_ADMIN_MODAL_STATE.expiresAt = 0;
    }
    const m = $('kioskStationAdminModal');
    if (m) m.hidden = true;
    document.body.classList.remove('modal-open', 'kiosk-idle-dimmed', 'kiosk-night-sleep');
    if (!opts.skipCameraResume && STATE.view === 'kiosks' && STATE.kioskLocked && STATE.activeKiosk === 'attendance') {
      KIOSK_ATT_STATE.standbyIdle = false;
      KIOSK_ATT_STATE.nightSleep = false;
      KIOSK_ATT_STATE.blackFrameStreak = 0;
      KIOSK_ATT_STATE.lastActivityAt = Date.now();
      if (!KIOSK_ATT_STATE.camPausedByUser && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
        startKioskAttCamera({ forceRestart: true, silentWatchdog: true });
      }
    }
  }

  function wireKioskStationAdminKeyboardOnce() {
    if (KIOSK_ADMIN_MODAL_STATE.keyWired || typeof window === 'undefined') return;
    KIOSK_ADMIN_MODAL_STATE.keyWired = true;
    window.addEventListener('keydown', e => {
      const m = $('kioskStationAdminModal');
      if (!m || m.hidden || !KIOSK_ADMIN_MODAL_STATE.open) return;
      if (e.key === 'Escape') {
        e.preventDefault();
        closeKioskStationAdminModal();
      }
    });
  }

  function openKioskStationAdminModal(opts = {}) {
    wireKioskStationAdminKeyboardOnce();
    wireKioskAdminActivityListenersOnce();
    const targetAction = opts && opts.targetAction === 'enrol' ? 'enrol' : 'admin';
    KIOSK_ADMIN_MODAL_STATE.targetAction = targetAction;
    if (STATE.kioskLocked && KIOSK_ADMIN_MODAL_STATE.sessionActive && KIOSK_ADMIN_MODAL_STATE.verifiedUser) {
      if (targetAction === 'enrol' || KIOSK_ADMIN_MODAL_STATE.sessionRole === 'entry') {
        touchKioskAdminActivity();
        openStaffFaceEnrolModal('', { operatorUser: KIOSK_ADMIN_MODAL_STATE.verifiedUser });
        return $('staffFaceEnrolModal');
      }
    }
    KIOSK_ADMIN_MODAL_STATE.open = true;
    KIOSK_ADMIN_MODAL_STATE.err = '';
    KIOSK_ADMIN_MODAL_STATE.statusText = targetAction === 'enrol'
      ? 'Position ISABI Entry Operator, Supervisor, or Admin face inside the oval guide'
      : 'Position Admin, Supervisor, or ISABI Entry Operator face inside the oval guide';
    KIOSK_ADMIN_MODAL_STATE.statusCls = '';
    if (!STATE.kioskLocked) {
      startOrResetKioskAdminSession(activeUser().full_name || 'Admin', activeUser(), isAuthorizedKioskAdminFace({ name: activeUser().full_name, email: activeUser().email, role: activeUser().role }) ? 'admin' : 'entry');
      if (targetAction === 'enrol' || KIOSK_ADMIN_MODAL_STATE.sessionRole === 'entry') {
        KIOSK_ADMIN_MODAL_STATE.open = false;
        return openStaffFaceEnrolModal('', { operatorUser: activeUser() });
      }
    } else if (!KIOSK_ADMIN_MODAL_STATE.sessionActive) {
      KIOSK_ADMIN_MODAL_STATE.unlocked = false;
    }

    let modal = $('kioskStationAdminModal');
    if (!modal) {
      modal = document.createElement('div');
      modal.id = 'kioskStationAdminModal';
      modal.className = 'modal-backdrop kiosk-submodal-backdrop';
      modal.setAttribute('role', 'dialog');
      modal.setAttribute('aria-modal', 'true');
      wireBackdropDismiss(modal, closeKioskStationAdminModal);
      document.body.appendChild(modal);
    }

    const renderAdminInner = () => {
      const kMode = ['sales', 'raw', 'fuel', 'attendance'].includes(STATE.activeKiosk) ? STATE.activeKiosk : 'attendance';
      const defCo = defaultEntryCompany();
      const attSites = getKioskStationSites(defCo);
      if (!STATE.kioskAttSite || (!STATE.kioskAttSiteCustom && !attSites.includes(STATE.kioskAttSite))) {
        STATE.kioskAttSite = attSites[0] || 'WTC Main Plant';
      } else if (!attSites.includes(STATE.kioskAttSite)) {
        attSites.unshift(STATE.kioskAttSite);
      }
      const activeInd = typeof getActiveIndustry === 'function' ? getActiveIndustry(STATE.company) : 'Manufacturing';
      const opAdminUser = KIOSK_ADMIN_MODAL_STATE.verifiedUser || activeUser();
      const allAllowedKeys = getAllowedCompanyKeys(opAdminUser);
      const adminIndCoCatalogMap = {
        'Manufacturing': [
          { key: 'manufacturing-group', short: 'All Group' },
          { key: 'wtc', short: 'WTC' },
          { key: 'bbconstruction', short: 'BBC' },
          { key: 'lionstransport', short: 'Lions' }
        ],
        'Holding & Treasury': [
          { key: 'bdeirholding', short: 'Holding' }
        ],
        'Hospitality & Resorts': [
          { key: 'industry:Hospitality & Resorts', short: 'All Resorts' },
          { key: 'blanca', short: 'Blanca' },
          { key: 'launa', short: 'La Una' },
          { key: 'palms', short: 'Palms' },
          { key: 'voile', short: 'Voile' },
          { key: 'platinum', short: 'Platinum' }
        ],
        'Automotive & Heavy Trading': [
          { key: 'industry:Automotive & Heavy Trading', short: 'All Trading' },
          { key: 'korriauto', short: 'Korri Auto' },
          { key: 'shacman', short: 'Shacman' }
        ],
        'Real Estate & Property': [
          { key: 'industry:Real Estate & Property', short: 'All RE' },
          { key: 'properties', short: 'Properties' },
          { key: '4235company', short: '4235 S.A.L' }
        ],
        'Insurance & Brokerage': [
          { key: 'insurance', short: 'Insurance' }
        ]
      };
      const indShortMap = {
        'Manufacturing': 'Manufacturing',
        'Hospitality & Resorts': 'Hospitality',
        'Real Estate & Property': 'Real Estate',
        'Automotive & Heavy Trading': 'Trading',
        'Insurance & Brokerage': 'Insurance',
        'Holding & Treasury': 'Holding'
      };
      const orderedIndIds = (window.MFG_HOLDING && typeof window.MFG_HOLDING.getIndustryGroups === 'function')
        ? window.MFG_HOLDING.getIndustryGroups().map(g => g.id)
        : ['Manufacturing', 'Hospitality & Resorts', 'Real Estate & Property', 'Automotive & Heavy Trading', 'Insurance & Brokerage', 'Holding & Treasury'];
      const indChipCatalog = orderedIndIds
        .map(indId => {
          const cos = (adminIndCoCatalogMap[indId] || []).filter(c => !c.key.startsWith('industry:') && (c.key === 'manufacturing-group' ? ['wtc', 'bbconstruction', 'lionstransport'].some(k => allAllowedKeys.includes(k)) : allAllowedKeys.includes(c.key)));
          if (!cos.length) return null;
          const groupEntry = (adminIndCoCatalogMap[indId] || []).find(c => c.key === 'manufacturing-group' || c.key.startsWith('industry:'));
          const defaultKey = (cos.length > 1 && groupEntry) ? groupEntry.key : cos[0].key;
          return { id: indId, short: indShortMap[indId] || indId, defaultKey };
        })
        .filter(Boolean);
      const coChipCatalog = (adminIndCoCatalogMap[activeInd] || adminIndCoCatalogMap['Manufacturing']).filter(c => {
        if (c.key.startsWith('industry:')) {
          const realCos = (adminIndCoCatalogMap[activeInd] || []).filter(x => !x.key.startsWith('industry:') && allAllowedKeys.includes(x.key));
          return realCos.length > 1;
        }
        if (c.key === 'manufacturing-group') {
          return ['wtc', 'bbconstruction', 'lionstransport'].filter(k => allAllowedKeys.includes(k)).length > 1;
        }
        return allAllowedKeys.includes(c.key);
      });
      const pCfg = (window.MFG_PRINT && window.MFG_PRINT.SETTINGS) || { paperWidth: 80, priceMode: 'priced', channel: 'rawbt', bleDeviceName: '' };
      const nb = window.IsabiNativeBridge || null;
      const hasNative = Boolean(nb && typeof nb.isAndroidKiosk === 'function');
      let nativeOrient = 'auto';
      if (hasNative && typeof nb.getOrientationMode === 'function') {
        try { nativeOrient = String(nb.getOrientationMode() || 'auto'); } catch (_) {}
      }
      const curIdleSec = Number(STATE.kioskIdleStandbySec != null ? STATE.kioskIdleStandbySec : 60);
      const curNightSleep = STATE.kioskNightSleep !== false;
      const shellVer = String(window.__MFG_SHELL_VER || '');

      if (!KIOSK_ADMIN_MODAL_STATE.unlocked) {
        const hintMsg = KIOSK_ADMIN_MODAL_STATE.err || KIOSK_ADMIN_MODAL_STATE.statusText || 'Look at the camera to verify Admin or Manager Face ID.';
        const hintCls = KIOSK_ADMIN_MODAL_STATE.err ? 'warn' : (KIOSK_ADMIN_MODAL_STATE.statusCls || '');
        modal.innerHTML = `
          <div class="modal-card ksa-modal-card ksa-face-stage" id="ksaFaceStage">
            <div class="modal-head">
              <div>
                <div class="modal-title">${ic('camera')} ${KIOSK_ADMIN_MODAL_STATE.targetAction === 'enrol' ? 'Staff Enrolment Face ID' : 'Station Admin &amp; Enrolment Face ID'}</div>
                <div class="modal-sub">${KIOSK_ADMIN_MODAL_STATE.targetAction === 'enrol'
                  ? 'Scan an ISABI Entry Operator, Supervisor, or Admin Face ID to enrol staff in your assigned Business Unit'
                  : 'Scan Admin/Supervisor Face ID for Station Setup, or ISABI Entry Operator Face ID to enrol staff in your Business Unit'}</div>
              </div>
              <button type="button" class="icon-btn" id="ksaCloseBtn" aria-label="Close">✕</button>
            </div>
            <div class="modal-body ksa-face-body">
              <div class="ksa-face-head-row">
                <span class="badge ${KIOSK_ADMIN_MODAL_STATE.camActive ? 'badge-ok' : ''}" id="ksaFaceLiveBadge">${KIOSK_ADMIN_MODAL_STATE.camActive ? 'Live Admin Scanner' : 'Starting Camera'}</span>
                <span class="panel-meta">5-Min Inactivity Auto-Logout</span>
              </div>
              <div class="kiosk-att-viewport ksa-face-viewport ${KIOSK_ADMIN_MODAL_STATE.camActive ? 'is-live' : 'is-standby'}" id="ksaFaceViewport">
                <video id="ksaAdminFaceVideo" autoplay muted playsinline poster="data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7"></video>
                <div class="kiosk-att-reticle" aria-hidden="true">
                  <span class="kiosk-finder-corner tl"></span>
                  <span class="kiosk-finder-corner tr"></span>
                  <span class="kiosk-finder-corner bl"></span>
                  <span class="kiosk-finder-corner br"></span>
                  <div class="kiosk-att-oval"></div>
                </div>
              </div>
              <div class="kiosk-pin-hint ${esc(hintCls)}" id="ksaFaceHint">
                ${esc(hintMsg)}
              </div>
              <div class="ksa-face-actions">
                <button type="button" class="btn" id="ksaCancelFaceBtn">Cancel</button>
                <button type="button" class="btn btn-primary" id="ksaRetryFaceCamBtn">${ic('camera')} Restart Scanner</button>
              </div>
            </div>
          </div>
        `;
        stripNativeTitles(modal);
        $('ksaCloseBtn')?.addEventListener('click', () => closeKioskStationAdminModal());
        $('ksaCancelFaceBtn')?.addEventListener('click', () => closeKioskStationAdminModal());
        $('ksaRetryFaceCamBtn')?.addEventListener('click', () => {
          KIOSK_ADMIN_MODAL_STATE.err = '';
          startKioskAdminFaceCamera();
        });
        if (!navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
          startKioskAdminFaceCamera();
        }
        return;
      }

      const adminRoleMap = {
        'Holding & Treasury': { attendance: 'HQ Staff Clock', sales: 'Sister Transfer Desk', raw: 'Partner Draw Desk', fuel: 'HQ Expense Intake' },
        'Hospitality & Resorts': { attendance: 'Resort Staff Clock', sales: 'POS & Gate Desk', raw: 'Kitchen & Cellar Intake', fuel: 'Generator & Solar Log' },
        'Automotive & Heavy Trading': { attendance: 'Showroom Staff Clock', sales: 'Counter & Parts POS', raw: 'Container Receiving', fuel: 'Workshop & PDI Bay' },
        'Real Estate & Property': { attendance: 'Building Staff Clock', sales: 'Tenant Rent Cashier', raw: 'Contractor Work Order', fuel: 'Utility & Meter Log' },
        'Insurance & Brokerage': { attendance: 'Brokerage Office Clock', sales: 'Policy & Quote Desk', raw: 'Premium Cashier Till', fuel: 'Claims FNOL Intake' }
      }[activeInd] || null;

      const roleCards = [
        { id: 'attendance', icon: ic('kiosks'), title: adminRoleMap ? adminRoleMap.attendance : 'Staff Attendance', desc: 'Hands-free wall Face ID clock' },
        { id: 'sales', icon: ic('truck'), title: adminRoleMap ? adminRoleMap.sales : 'Sales Dispatch', desc: 'Weighbridge tickets & gate passes' },
        { id: 'raw', icon: ic('quarry'), title: adminRoleMap ? adminRoleMap.raw : 'Quarry & Raw Material', desc: 'Aggregate intakes & scale slips' },
        { id: 'fuel', icon: ic('fuel'), title: adminRoleMap ? adminRoleMap.fuel : 'Fuel & Lubricants', desc: 'Diesel dispense, refills & variance' }
      ];
      const remMs = Math.max(0, (KIOSK_ADMIN_MODAL_STATE.expiresAt || (Date.now() + KIOSK_ADMIN_INACTIVITY_MS)) - Date.now());
      const adminLabel = KIOSK_ADMIN_MODAL_STATE.verifiedAdmin || activeUser().full_name || 'Admin';

      modal.innerHTML = `
        <div class="modal-card ksa-modal-card">
          <div class="modal-head">
            <div>
              <div class="modal-title">${ic('cog')} Kiosk Switcher &amp; Station Setup</div>
              <div class="modal-sub">Repurpose this tablet in 1 tap or adjust station hardware without cluttering the operator screen</div>
            </div>
            <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
              <span class="badge badge-ok mono" id="ksaSessionCountdownBadge">${esc(adminLabel)} · Auto-logout in ${formatKioskAdminCountdown(remMs)}</span>
              <button type="button" class="icon-btn" id="ksaCloseBtn" aria-label="Close">✕</button>
            </div>
          </div>
          <div class="modal-body ksa-admin-body">
            <div class="ksa-section">
              <div class="ksa-sec-head">
                <strong>1. Choose Tablet Purpose</strong>
                <span>Locks to the selected terminal and remembers across reboots</span>
              </div>
              <div class="ksa-role-grid" id="ksaRoleGrid">
                ${roleCards.map(rc => `
                  <button type="button" class="ksa-role-card ${STATE.kioskLocked && kMode === rc.id ? 'active' : ''}" data-ksa-role="${rc.id}">
                    <div class="ksa-rc-top">
                      <span class="ksa-rc-ico">${rc.icon}</span>
                      ${STATE.kioskLocked && kMode === rc.id ? '<span class="badge badge-ok">Active</span>' : ''}
                    </div>
                    <strong>${esc(rc.title)}</strong>
                    <span>${esc(rc.desc)}</span>
                  </button>
                `).join('')}
              </div>
              <div class="ksa-backoffice-row">
                ${canViewView('payroll_attendance') ? `
                  <button type="button" class="btn" data-ksa-exit="payroll_attendance">
                    ${ic('payroll_attendance')} Open Attendance &amp; OT Analysis
                  </button>
                ` : ''}
                <button type="button" class="btn" data-ksa-exit="overview">
                  ${ic('unlock')} Unlock Full Command Center
                </button>
              </div>
            </div>

            <div class="ksa-section" id="ksaStationConfigBox">
              <div class="ksa-sec-head">
                <strong>2. Station Configuration (${esc((roleCards.find(r => r.id === kMode) || roleCards[0]).title)})</strong>
                <span>Applies only to this station</span>
              </div>
              <div class="ksa-config-grid">
                ${indChipCatalog.length > 1 ? `
                  <div class="ksa-cfg-row">
                    <span class="kiosk-bar-lbl">${ic('layers') || ic('building')} Industry</span>
                    <div class="kiosk-seg-group" id="ksaIndustryGroup">
                      ${indChipCatalog.map(ind => `
                        <button type="button" class="kiosk-seg-btn ${activeInd === ind.id ? 'active' : ''}" data-tone="sapphire" data-ksa-ind="${esc(ind.defaultKey)}">${esc(ind.short)}</button>
                      `).join('')}
                    </div>
                  </div>
                ` : ''}
                ${coChipCatalog.length > 1 ? `
                  <div class="ksa-cfg-row">
                    <span class="kiosk-bar-lbl">${ic('building')} Company</span>
                    <div class="kiosk-seg-group" id="ksaCompanyGroup">
                      ${coChipCatalog.map(c => `
                        <button type="button" class="kiosk-seg-btn ${STATE.company === c.key ? 'active' : ''}" data-tone="sapphire" data-ksa-co="${esc(c.key)}">${esc(c.short)}</button>
                      `).join('')}
                    </div>
                  </div>
                ` : ''}

                ${kMode === 'attendance' ? `
                  <div class="ksa-cfg-row">
                    <label class="kiosk-bar-lbl" for="ksaSiteSelect">${ic('pin')} Wall Location</label>
                    <select id="ksaSiteSelect" class="kiosk-select" data-plain-options="1">
                      ${attSites.map(s => `<option value="${esc(s)}" ${s === STATE.kioskAttSite ? 'selected' : ''}>${esc(s)}</option>`).join('')}
                    </select>
                  </div>
                  <div class="ksa-cfg-row">
                    <span class="kiosk-bar-lbl">${ic('clock')} Punch Direction</span>
                    <div class="kiosk-seg-group">
                      <button type="button" class="kiosk-seg-btn ${STATE.kioskAttDir === 'auto' ? 'active' : ''}" data-tone="sapphire" data-ksa-att-dir="auto">Auto (IN / OUT)</button>
                      <button type="button" class="kiosk-seg-btn ${STATE.kioskAttDir === 'in' ? 'active' : ''}" data-tone="emerald" data-ksa-att-dir="in">Clock IN Only</button>
                      <button type="button" class="kiosk-seg-btn ${STATE.kioskAttDir === 'out' ? 'active' : ''}" data-tone="amber" data-ksa-att-dir="out">Clock OUT Only</button>
                    </div>
                  </div>
                  <div class="ksa-cfg-row">
                    <span class="kiosk-bar-lbl">${ic('sliders')} Screen &amp; Cam Saver</span>
                    <div class="kiosk-seg-group">
                      <button type="button" class="kiosk-seg-btn ${curIdleSec === 30 ? 'active' : ''}" data-tone="emerald" data-ksa-idle-sec="30">30s</button>
                      <button type="button" class="kiosk-seg-btn ${curIdleSec === 60 ? 'active' : ''}" data-tone="emerald" data-ksa-idle-sec="60">1 min</button>
                      <button type="button" class="kiosk-seg-btn ${curIdleSec === 120 ? 'active' : ''}" data-tone="emerald" data-ksa-idle-sec="120">2 min</button>
                      <button type="button" class="kiosk-seg-btn ${curIdleSec === 0 ? 'active' : ''}" data-tone="amber" data-ksa-idle-sec="0">Always On</button>
                    </div>
                  </div>
                  <div class="ksa-cfg-row">
                    <span class="kiosk-bar-lbl">${ic('clock')} Night Sleep (23:00-05:30)</span>
                    <div class="kiosk-seg-group">
                      <button type="button" class="kiosk-seg-btn ${curNightSleep ? 'active' : ''}" data-tone="emerald" data-ksa-night-sleep="1">Auto Sleep (1-Tap Wake)</button>
                      <button type="button" class="kiosk-seg-btn ${!curNightSleep ? 'active' : ''}" data-tone="amber" data-ksa-night-sleep="0">Off</button>
                    </div>
                  </div>
                  <div class="ksa-cfg-row">
                    <span class="kiosk-bar-lbl">${ic('camera')} Biometrics</span>
                    <div style="display:flex;gap:8px;flex-wrap:wrap">
                      <button type="button" class="btn btn-primary" id="ksaEnrolFaceBtn">${ic('camera')} Enrol Staff Face ID</button>
                      <button type="button" class="btn" id="ksaToggleCamBtn">${KIOSK_ATT_STATE.camActive ? 'Pause Wall Camera' : 'Start Wall Camera'}</button>
                    </div>
                  </div>
                ` : `
                  <div class="ksa-cfg-row">
                    <span class="kiosk-bar-lbl">${ic('printer')} Paper Size</span>
                    <div class="kiosk-seg-group">
                      <button type="button" class="kiosk-seg-btn ${pCfg.paperWidth === 80 ? 'active' : ''}" data-tone="sapphire" data-ksa-paper="80">80mm Standard</button>
                      <button type="button" class="kiosk-seg-btn ${pCfg.paperWidth === 58 ? 'active' : ''}" data-tone="sapphire" data-ksa-paper="58">58mm Handheld</button>
                    </div>
                  </div>
                  ${(kMode === 'sales' || kMode === 'raw') ? `
                    <div class="ksa-cfg-row">
                      <span class="kiosk-bar-lbl">${ic('dollar')} Ticket Copy</span>
                      <div class="kiosk-seg-group">
                        <button type="button" class="kiosk-seg-btn ${pCfg.priceMode === 'priced' ? 'active' : ''}" data-tone="emerald" data-ksa-price="priced">Priced</button>
                        <button type="button" class="kiosk-seg-btn ${pCfg.priceMode === 'unpriced' ? 'active' : ''}" data-tone="amber" data-ksa-price="unpriced">Unpriced Pass</button>
                      </div>
                    </div>
                  ` : ''}
                  <div class="ksa-cfg-row">
                    <label class="kiosk-bar-lbl" for="ksaPrintChannelSelect">${ic('bluetooth')} Thermal Printer</label>
                    <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
                      <select id="ksaPrintChannelSelect" class="kiosk-select" data-plain-options="1">
                        <option value="rawbt" ${pCfg.channel === 'rawbt' ? 'selected' : ''}>RawBT Bluetooth</option>
                        <option value="web_bluetooth" ${pCfg.channel === 'web_bluetooth' ? 'selected' : ''}>Web Bluetooth (${pCfg.bleDeviceName ? esc(pCfg.bleDeviceName) : 'Direct BLE'})</option>
                        <option value="browser" ${pCfg.channel === 'browser' ? 'selected' : ''}>Browser Print</option>
                      </select>
                      <button type="button" class="btn" id="ksaPairBleBtn">${ic('bluetooth')} Pair Printer</button>
                    </div>
                  </div>
                `}
              </div>
            </div>

            <div class="ksa-section" id="ksaHardwareBox">
              <div class="ksa-sec-head">
                <strong>3. Tablet Hardware &amp; Software Version</strong>
                <span>Seat: ${esc(activeUser().full_name)}${shellVer ? ` · Build v${esc(shellVer)}` : ''}</span>
              </div>
              <div class="ksa-config-grid">
                <div class="ksa-cfg-row">
                  <span class="kiosk-bar-lbl">${ic('rotate')} App Version</span>
                  <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
                    <span class="badge badge-ok mono">v${esc(shellVer || 'live')}</span>
                    <button type="button" class="btn btn-primary" id="ksaCheckUpdateBtn">${ic('rotate')} Check &amp; Update${shellVer ? ` (v${esc(shellVer)})` : ''}</button>
                    <span class="panel-meta">Auto-checks OTA every 60s + daily 05:25 AM refresh</span>
                  </div>
                </div>
                ${hasNative ? `
                  <div class="ksa-cfg-row">
                    <span class="kiosk-bar-lbl">${ic('expand')} Screen Rotation</span>
                    <div class="kiosk-seg-group">
                      <button type="button" class="kiosk-seg-btn ${nativeOrient === 'auto' ? 'active' : ''}" data-tone="sapphire" data-ksa-orient="auto">Auto Rotate</button>
                      <button type="button" class="kiosk-seg-btn ${nativeOrient === 'portrait' ? 'active' : ''}" data-tone="sapphire" data-ksa-orient="portrait">Portrait</button>
                      <button type="button" class="kiosk-seg-btn ${nativeOrient === 'landscape' ? 'active' : ''}" data-tone="sapphire" data-ksa-orient="landscape">Landscape</button>
                    </div>
                  </div>
                  <div class="ksa-cfg-row">
                    <span class="kiosk-bar-lbl">${ic('cog')} Android Hardware</span>
                    <div style="display:flex;gap:8px;flex-wrap:wrap">
                      <button type="button" class="btn" data-ksa-sys="wifi">Wi-Fi Settings</button>
                      <button type="button" class="btn" data-ksa-sys="bluetooth">Bluetooth Settings</button>
                      <button type="button" class="btn" id="ksaOpenAndroidVaultBtn">Device Lock Vault</button>
                    </div>
                  </div>
                ` : ''}
              </div>
            </div>
          </div>
          <div class="modal-foot ksa-modal-foot">
            <div style="display:flex;gap:8px;flex-wrap:wrap">
              <button type="button" class="btn" id="ksaReloadAppBtn">${ic('rotate')} Reload Terminal</button>
              <button type="button" class="btn" id="ksaSignOutBtn">Sign Out Seat</button>
            </div>
            <button type="button" class="btn btn-primary" id="ksaDoneBtn">${ic('check_circle')} Lock &amp; Exit Admin</button>
          </div>
        </div>
      `;

      wireModalSuggestions(modal);
      stripNativeTitles(modal);

      $('ksaCloseBtn')?.addEventListener('click', () => closeKioskStationAdminModal());
      $('ksaDoneBtn')?.addEventListener('click', () => closeKioskStationAdminModal());

      modal.querySelectorAll('[data-ksa-role]').forEach(btn => {
        btn.addEventListener('click', () => {
          const nextRole = btn.getAttribute('data-ksa-role') || 'attendance';
          if (STATE.activeKiosk === 'attendance' && nextRole !== 'attendance') {
            stopKioskAttCamera();
          }
          STATE.activeKiosk = nextRole;
          KIOSK_ADMIN_MODAL_STATE.originKioskTab = nextRole;
          STATE.view = 'kiosks';
          STATE.kioskLocked = true;
          document.body.classList.add('kiosk-locked');
          saveKioskStationConfig({ activeKiosk: nextRole, kioskLocked: true });
          syncNativeStationPreset(nextRole);
          syncKioskLockedUrl();
          renderApp();
          renderAdminInner();
          const roleTitle = (roleCards.find(r => r.id === nextRole) || {}).title || nextRole;
          toast(`Switched tablet purpose to ${roleTitle}`, 'ok');
        });
      });

      modal.querySelectorAll('[data-ksa-exit]').forEach(btn => {
        btn.addEventListener('click', () => {
          const dest = btn.getAttribute('data-ksa-exit') || 'overview';
          stopKioskAttCamera();
          STATE.kioskLocked = false;
          STATE.kioskUnlockPromptOpen = false;
          document.body.classList.remove('kiosk-locked', 'kiosk-idle-dimmed', 'kiosk-night-sleep');
          document.documentElement.classList.remove('kiosk-prelock');
          saveKioskStationConfig({ kioskLocked: false });
          syncNativeStationPreset('command');
          startOrResetKioskAdminSession(KIOSK_ADMIN_MODAL_STATE.verifiedAdmin || activeUser().full_name || 'Admin');
          closeKioskStationAdminModal({ keepAdminSession: true, skipCameraResume: true });
          setView(dest);
        });
      });

      const applyKioskAdminScopeChange = targetCo => {
        if (!targetCo) return;
        if (!targetCo.startsWith('industry:') && targetCo !== 'manufacturing-group' && !getAllowedCompanyKeys(activeUser()).includes(targetCo)) return;
        if (window.MFG_HOLDING && typeof window.MFG_HOLDING.selectCompanyScope === 'function') {
          window.MFG_HOLDING.selectCompanyScope(targetCo, true);
        } else {
          STATE.company = targetCo;
          saveFilterState();
        }
        STATE.kioskAttSiteCustom = false;
        STATE.kioskAttStaff = '';
        const nextSites = getKioskStationSites(defaultEntryCompany());
        if (nextSites.length) STATE.kioskAttSite = nextSites[0];
        saveKioskStationConfig({
          company: STATE.company,
          kioskAttSite: STATE.kioskAttSite,
          kioskAttSiteCustom: false
        });
        renderApp();
        renderAdminInner();
      };

      modal.querySelectorAll('[data-ksa-ind]').forEach(btn => {
        btn.addEventListener('click', () => {
          applyKioskAdminScopeChange(btn.getAttribute('data-ksa-ind') || 'manufacturing-group');
        });
      });

      modal.querySelectorAll('[data-ksa-co]').forEach(btn => {
        btn.addEventListener('click', () => {
          applyKioskAdminScopeChange(btn.getAttribute('data-ksa-co') || 'manufacturing-group');
        });
      });

      const siteSel = $('ksaSiteSelect');
      if (siteSel) {
        siteSel.addEventListener('change', () => {
          STATE.kioskAttSite = siteSel.value;
          STATE.kioskAttSiteCustom = true;
          saveKioskStationConfig({ kioskAttSite: STATE.kioskAttSite, kioskAttSiteCustom: true });
          renderApp();
        });
      }

      modal.querySelectorAll('[data-ksa-att-dir]').forEach(btn => {
        btn.addEventListener('click', () => {
          STATE.kioskAttDir = btn.getAttribute('data-ksa-att-dir') || 'auto';
          saveKioskStationConfig({ kioskAttDir: STATE.kioskAttDir });
          renderApp();
          renderAdminInner();
        });
      });

      modal.querySelectorAll('[data-ksa-idle-sec]').forEach(btn => {
        btn.addEventListener('click', () => {
          const nextSec = Math.max(0, Number(btn.getAttribute('data-ksa-idle-sec') || 0));
          STATE.kioskIdleStandbySec = [0, 30, 60, 120].includes(nextSec) ? nextSec : 60;
          saveKioskStationConfig({ kioskIdleStandbySec: STATE.kioskIdleStandbySec });
          renderAdminInner();
          toast(
            STATE.kioskIdleStandbySec === 0
              ? 'Screen & camera saver set to Always On'
              : `Screen & camera saver set to ${STATE.kioskIdleStandbySec === 60 ? '1 minute' : (STATE.kioskIdleStandbySec === 120 ? '2 minutes' : '30 seconds')} (1-tap wake)`,
            'ok'
          );
        });
      });

      modal.querySelectorAll('[data-ksa-night-sleep]').forEach(btn => {
        btn.addEventListener('click', () => {
          STATE.kioskNightSleep = btn.getAttribute('data-ksa-night-sleep') !== '0';
          saveKioskStationConfig({ kioskNightSleep: STATE.kioskNightSleep });
          renderAdminInner();
          toast(
            STATE.kioskNightSleep
              ? 'Night Deep Sleep enabled (23:00-05:30, 1-tap instant wake)'
              : 'Night Deep Sleep disabled',
            'ok'
          );
        });
      });

      $('ksaCheckUpdateBtn')?.addEventListener('click', () => {
        checkAndApplyKioskOtaUpdate({ silent: false });
      });

      $('ksaEnrolFaceBtn')?.addEventListener('click', () => {
        stopKioskAttCamera();
        const opUser = KIOSK_ADMIN_MODAL_STATE.verifiedUser || activeUser();
        startOrResetKioskAdminSession(KIOSK_ADMIN_MODAL_STATE.verifiedAdmin || opUser.full_name || 'Admin', opUser, KIOSK_ADMIN_MODAL_STATE.sessionRole || 'admin');
        closeKioskStationAdminModal({ keepAdminSession: true, skipCameraResume: true });
        openStaffFaceEnrolModal('', { operatorUser: opUser });
      });

      $('ksaToggleCamBtn')?.addEventListener('click', async () => {
        if (KIOSK_ATT_STATE.camActive) {
          KIOSK_ATT_STATE.camPausedByUser = true;
          stopKioskAttCamera();
          KIOSK_ATT_STATE.statusText = 'Camera paused by Admin. Tap Start Camera to resume hands-free Face ID.';
          KIOSK_ATT_STATE.statusCls = '';
          renderApp();
          renderAdminInner();
        } else {
          KIOSK_ATT_STATE.camPausedByUser = false;
          await startKioskAttCamera();
          renderAdminInner();
        }
      });

      modal.querySelectorAll('[data-ksa-paper]').forEach(btn => {
        btn.addEventListener('click', () => {
          if (!window.MFG_PRINT) return;
          window.MFG_PRINT.savePrintSettings({ paperWidth: Number(btn.getAttribute('data-ksa-paper')) === 58 ? 58 : 80 });
          renderApp();
          renderAdminInner();
        });
      });

      modal.querySelectorAll('[data-ksa-price]').forEach(btn => {
        btn.addEventListener('click', () => {
          if (!window.MFG_PRINT) return;
          window.MFG_PRINT.savePrintSettings({ priceMode: btn.getAttribute('data-ksa-price') === 'unpriced' ? 'unpriced' : 'priced' });
          renderApp();
          renderAdminInner();
        });
      });

      const prChSel = $('ksaPrintChannelSelect');
      if (prChSel && window.MFG_PRINT) {
        prChSel.addEventListener('change', () => {
          window.MFG_PRINT.savePrintSettings({ channel: prChSel.value });
          toast(`Printer channel set to ${prChSel.value}`);
        });
      }

      $('ksaPairBleBtn')?.addEventListener('click', async () => {
        if (!window.MFG_PRINT) return;
        const r = await window.MFG_PRINT.pairWebBluetoothPrinter();
        if (r.ok) {
          toast(`Connected to Bluetooth printer: ${r.name}`, 'ok');
          renderApp();
          renderAdminInner();
        } else {
          toast(`Bluetooth pairing: ${r.error}`, 'warn');
        }
      });

      modal.querySelectorAll('[data-ksa-orient]').forEach(btn => {
        btn.addEventListener('click', () => {
          const modeId = btn.getAttribute('data-ksa-orient') || 'auto';
          try { nb?.setScreenOrientation?.(modeId); } catch (_) {}
          renderAdminInner();
        });
      });

      modal.querySelectorAll('[data-ksa-sys]').forEach(btn => {
        btn.addEventListener('click', () => {
          const target = btn.getAttribute('data-ksa-sys') || '';
          try { nb?.openSystemSettings?.(target); } catch (_) {}
        });
      });

      $('ksaOpenAndroidVaultBtn')?.addEventListener('click', () => {
        stopKioskAttCamera();
        closeKioskStationAdminModal({ keepAdminSession: true, skipCameraResume: true });
        try { nb?.openAndroidVault?.(); } catch (_) {}
      });

      $('ksaReloadAppBtn')?.addEventListener('click', () => {
        stashKioskSwResumeAndReload();
      });

      $('ksaSignOutBtn')?.addEventListener('click', () => {
        stopKioskAttCamera();
        closeKioskStationAdminModal({ skipCameraResume: true });
        signOut();
      });
    };

    KIOSK_ADMIN_MODAL_STATE.renderInnerFn = renderAdminInner;
    modal.hidden = false;
    document.body.classList.add('modal-open');
    renderAdminInner();
    return modal;
  }

