            badge: 'HACCP STOCK INTAKE',
            refLabel: 'INTAKE #',
            counterpartyLbl: 'Purveyor / Supplier',
            counterparty: strV('ik_supplier') || 'Cold-Chain Purveyor',
            scopeLbl: 'Store / Cold Room',
